using System;

public static class FrenchQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://fr.wikiquote.org/wiki/Brenda_Castillo", Text = "Je demande seulement à Dieu la force d'en haut, parce que je ressens une grande douleur dans ma poitrine", Author = "Brenda Castillo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-F%C3%A9licit%C3%A9_Ebokea", Text = "Le rire n’est pas seulement ce mouvement des lèvres; il faut le penser, le réfléchir, le réfracter sur les autres, rire avec la compagnie ou pourquoi pas, rire d’elle.", Author = "Marie-Félicité Ebokea" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Steve_Mouni%C3%A9", Text = "Un début comme celui-ci est incroyable. Nous avons travaillé toute la journée pendant la pré-saison, nous avons travaillé dur et le coach nous a donné beaucoup de conseils. Les conséquences de notre travail ont montré. C'est fou, je vais prendre une photo du tableau.", Author = "Steve Mounié" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Acteurs", Text = "André Dussollier: Un mec qui sourit tout le temps, c'est qu'il a quelque chose à cacher.", Author = "Les Acteurs" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Et_pour_quelques_dollars_de_plus", Text = "Là où la vie n'avait pas de valeur, la mort, parfois, avait son prix. C'est ainsi que les chasseurs de primes firent leur apparition.", Author = "Et pour quelques dollars de plus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Impression", Text = "L'individu n'est pas la somme de ses impressions générales, il est la somme de ses impressions singulières.", Author = "Impression" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Blanche_Gardin", Text = "Ça fait toujours du bien de rire de ce qui est très pénible", Author = "Blanche Gardin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Don_DeLillo", Text = "Car il n'est pas de bien dont nous soyons plus dépourvus que le savoir-faire intellectuel.", Author = "Don DeLillo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Audrey_Millet", Text = "Quand ces enseignes (ie. H&M et Zara) sont arrivées, on a trouvé ça génial: on pouvait enfin s'habiller à la mode sans trop dépenser. Sauf qu'il s'agit aussi d'une mode éphémère, fast fashion et ultra fast fashion, c'est le même combat.", Author = "Audrey Millet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Bonaparte", Text = "Si quelqu'un écrit ma vie, qu'il l'intitule La dernière Bonaparte car je le suis. Mes cousins de la branche impériale ne sont que Napoléon.", Author = "Marie Bonaparte" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Ray", Text = "Il n’y a que la fortune pour faire d’un ruffian un honnête homme, soumis aux lois des hommes.", Author = "Jean Ray" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Baptiste_Bidegain", Text = "Tous ces gens, politiciens pillards, fonctionnaires arrivistes, ont mis la France en coupe réglée. Ils estiment que tout va bien et ils éprouvent, vis-à-vis du citoyen malencontreux dont le pied heurte leur écuelle, la colère farouche du chien à qui l'on veut enlever son os.", Author = "Jean-Baptiste Bidegain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/American_Gangster", Text = "Frank Lucas: Soit on est quelqu'un, soit on est personne.", Author = "American Gangster" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marcus_Furius_Camillus", Text = "Pas avec l'or mais avec le fer, on rachète la patrie.", Author = "Marcus Furius Camillus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mohammed_Dib", Text = "Sans la mer, sans les femmes, nous serions restés définitivement des orphelins; elles nous couvrirent du sel de leur langue et cela, heureusement, préserva maints d’entre nous! Il faudra le proclamer un jour publiquement.", Author = "Mohammed Dib" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_II", Text = "J'aime féliciter et récompenser à haute voix et gronder dans un murmure.", Author = "Catherine II" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maurice_Rajsfus", Text = "Si tu leur réponds, il y a outrage. Si tu résistes, il y a rébellion. Si tu prends la foule à témoin, il y a incitation à l'émeute.", Author = "Maurice Rajsfus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Allemagne", Text = "L'Allemagne était là où on luttait pour elle; elle se montrait là où des ennemis en armes voulaient s'emparer de ses biens, elle brillait d'un éclat radieux là où ceux qui étaient pénétrés de son esprit risquaient pour elle le dernier enjeu.", Author = "Allemagne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tribunal", Text = "En 2011, notre étude sur l’impartialité de la justice a montré que les libérations sur parole accordées par les tribunaux varient de 65% (après une restauration) à pratiquement zéro relaxe obtenue avant la pause déjeuner.", Author = "Tribunal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diana_Spencer", Text = "Un instant, je n’étais personne. La minute suivante, j’étais la princesse de Galles, mère, jouet des médias. C’était trop à la fois pour une seule personne.", Author = "Diana Spencer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Raymonde_Goudou_Coffie", Text = "Pour moi, une femme se définit non seulement par sa visibilité, sa compétence mais par son esprit d'ouverture. Il faut que les femmes osent.", Author = "Raymonde Goudou Coffie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89chelle", Text = "[…] d'une gare, je ne conçois pas qu'on sorte autrement que par les échelles qui montent indéfiniment vers l'horizon.", Author = "Échelle" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Protocoles_des_Sages_de_Sion", Text = "Aux premières époques de la vie sociale, ils étaient soumis à la force brutale et aveugle, puis ils se soumirent à la loi, qui n’est, en réalité, que la même force masquée. Cette constatation me mène à déduire que, de par la loi naturelle, le droit réside dans la force.", Author = "Protocoles des Sages de Sion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ludwig_van_Beethoven", Text = "Malheureusement, un démon jaloux, ma mauvaise santé, est venu se jeter à la traverse. Depuis trois ans, mon ouïe est toujours devenue plus faible. Cela doit avoir été causé par mon affection du ventre, dont je souffrais déjà autrefois, comme tu sais, mais qui a beaucoup empiré.", Author = "Ludwig van Beethoven" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Amoyal", Text = "Qui a deux femmes perd son âme, qui a deux violons perd la raison.", Author = "Pierre Amoyal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mona_Eltahawy", Text = "Les mères élèvent leurs enfants pour qu’ils survivent dans un environnement misogyne", Author = "Mona Eltahawy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Darnton", Text = "N'importe quel boulot peut faire rêver tant qu'on ne s'y essaie pas.", Author = "John Darnton" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Presse", Text = "Il parait que la presse a tué un ministre. Par rapport à ceux qu'elle fait vivre, c'est pas très grave.", Author = "Presse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mystic_River", Text = "Merci d'avoir trouvé les assassins de ma fille Sean. Si seulement t'avais été plus rapide.", Author = "Mystic River" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ingmar_Bergman", Text = "Le cinéma en tant que rêve, le cinéma en tant que musique. Aucun art ne traverse, comme le cinéma, directement notre conscience diurne pour toucher à nos sentiments, au fond de la chambre crépusculaire de notre âme.", Author = "Ingmar Bergman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuel_Levinas", Text = "On conviendra aisément qu’il importe au plus haut point de savoir si l’on n’est pas dupe de la morale.", Author = "Emmanuel Levinas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/George_W._Bush", Text = "Après tout, cet homme a tenté de tuer mon père à un moment.", Author = "George W. Bush" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Olympe_Audouard", Text = "Il existe un génie féminin.", Author = "Olympe Audouard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Galabru", Text = "Pour vivre jusqu'à 90 ans, mon spécialiste m'a conseillé pas de fruit, pas de légume!: avec des pâtes, du riz et des pommes de terre, on vit très bien... si vous le voulez.", Author = "Michel Galabru" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaamelott_%3A_Premier_Volet", Text = "ARTHOUR! ARTHOUR! ARTHOUR! ARTHOOOUUR! ARTHOUR! QU'EST-CE À DIRE QU'EST CECI?! Ahahahahah.", Author = "Kaamelott : Premier Volet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Eug%C3%A8ne_Robert-Houdin", Text = "Et comme l'art suppose toujours un idéal que l'artiste cherche à réaliser, je rêve déjà ce jour où un réseau de fils électriques partant d'un régulateur unique, rayonnera sur la France entière et portera l'heure précise dans les plus importantes cités comme dans les plus modestes villages.", Author = "Jean-Eugène Robert-Houdin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aurelie_Nemours", Text = "Il y a l’amour\nSi je l’oublie un jour\nAyez pitié de moi", Author = "Aurelie Nemours" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Madison_Grant", Text = "Au point de vue zoologique, depuis le début de l'époque tertiaire, l'Afrique du Nord, au nord du Sahara, fait partie de l'Europe. Cela est vrai à la fois des animaux et des races humaines. Les Berbères de l'Afrique du Nord sont identiques comme race aux Espagnols et aux Italiens du Sud.", Author = "Madison Grant" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mycorhize", Text = "Mieux comprendre et améliorer l’interaction mycorhizienne est un enjeu agronomique majeur à moyen terme. Il faut réexpoiter ces mécanismes qui ont entretenu la flore terrestre depuis 400 millions d'années.", Author = "Mycorhize" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gerty_Dambury", Text = "Peur du silence. Peur du vide. Peur de ne plus être vu·e et entendu·e. Et à ce jeu, certaines œuvres demeureront encore invisibles, comme elles l’étaient déjà.", Author = "Gerty Dambury" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Axelle_Kabou", Text = "Le sous-développement de l'Afrique a fait couler des flots d'encre et inspiré tant de réflexions, qu'aujourd'hui entre les analyses centrées sur les causes du retard proprement dit, et les recettes proposées pour y remédier, on pense n'avoir que l'embarras de choix.", Author = "Axelle Kabou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tendre_Poulet", Text = "Tanquerelle: J'aurais tellement aimé rencontrer un professeur de trompette. Je sais pas pourquoi.", Author = "Tendre Poulet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maharishi_Mahesh_Yogi", Text = "Notre message est le même message séculaire de la vie. Nous avons enseigné au monde depuis un demi-siècle La vie est bonheur, exempte de problème, il n'est pas nécessaire de souffrir", Author = "Maharishi Mahesh Yogi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rakiatou_Kaffa-Jackou", Text = "C'est ce qui explique l'implication et l'engagement sans faille des gouvernements, sous la haute égide de leurs Présidents respectifs afin d'accélérer la capture du dividende démographique.", Author = "Rakiatou Kaffa-Jackou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kahina_Bahloul", Text = "(...) nous ne pouvons que constater les avancées clairement favorables aux femmes apportées par l’islam. Ce qui pose problème aujourd’hui, ce sont les lectures patriarcales faites par des hommes ayant évolué dans des traditions misogynes où le rôle de la femme se limite à la sphère domestique", Author = "Kahina Bahloul" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ugo_Foscolo", Text = "[…] la renommée des héros n’est guère que l’ouvrage du sort, et celui de leur audace, et de leurs crimes.", Author = "Ugo Foscolo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Dionis_du_S%C3%A9jour", Text = "L’actualité en Crimée rappelle froidement l’anschluss de l'Autriche par les Nazis en 1938.", Author = "Jean Dionis du Séjour" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sidib%C3%A9_Dedeou_Ousmane", Text = "L’arme du syndicaliste, c’est la grève mais elle n’est pas toujours efficace à tout point de vue.", Author = "Sidibé Dedeou Ousmane" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Pierre_Kwambamba_Masi", Text = "La contribution de l’Église est inévitablement l’invitation à la paix, à la réconciliation et l’invitation au retour à la fraternité.", Author = "Jean-Pierre Kwambamba Masi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Solitaire", Text = "Adieu, vie que je mène présentement. Tu ne saurais durer telle qu'elle. Noble tu fus. Pur esprit. Paisible et solitaire. Adieu honneur, dès le premier pas fait en public.", Author = "Solitaire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Algue", Text = "Nous entrons dans l'ère de la grande peinture. Quelque chose s'est achevé en 1954 avec la mort de ce peintre d'algue tout juste bon à favoriser la digestion bourgeoise, je veux dire Henri Matisse, peintre de la révolution de 1789.", Author = "Algue" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Dubois_%28auteur%29", Text = "Ils vivent dans des lutinières aussi actives que d'immenses termitières, mais où le jeu et les cabrioles remplacent le travail.", Author = "Pierre Dubois (auteur)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nourane_Fotsing_Moluh_Hassana", Text = "Pour toute personne qui veut faire des affaires, intéressez vous aux réseaux sociaux. C'est vraiment un très bel élément pour pouvoir décoller. Il faudrait que la jeunesse comprenne vraiment ça. C'est très très important.", Author = "Nourane Fotsing Moluh Hassana" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alfred_Korzybski", Text = "La structure de toute chose, qu'il s'agisse d'un langage, d'une maison, d'une machine, etc., se résume à des relations. Pour qu'il y ait structure, il doit y avoir tout un complexe ou réseau de parties ordonnées et reliées entre elles.", Author = "Alfred Korzybski" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arm%C3%A9e_fran%C3%A7aise", Text = "Le Président de la République est le chef des armées. Il préside les conseils et comités supérieurs de la Défense nationale.", Author = "Armée française" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tara_Fela-Durotoye", Text = "J'ai toujours su que le risque de gérer une entreprise au Nigeria était élevé, mais parfois, on ne réalise pas à quel point, jusqu'à ce que mes produits soient contrefaits.", Author = "Tara Fela-Durotoye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joan_Fontaine", Text = "Je me suis mariée la première, j’ai gagné\nl’Oscar avant Olivia, et, si je meurs la première, elle sera sans doute folle de rage parce que je l’ai encore battue.", Author = "Joan Fontaine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vin_et_religion", Text = "Tour à tour offrande divine ou égérie des poètes, le vin exprime, sous toutes les civilisations, la gaîté, la franchise, le courage ou la force.", Author = "Vin et religion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hugo_Horiot", Text = "L'autisme n'est pas une maladie; la maladie c'est la névrose de la normalité.", Author = "Hugo Horiot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Green", Text = "Hazel Grace Lancaster: Je suis tombée amoureuse pendant qu'il lisait, comme on s'endort: d'abord doucement et puis tout d'un coup.", Author = "John Green" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%C3%A9on_Bourgeois", Text = "Les partis sont toujours en retard sur les idées.", Author = "Léon Bourgeois" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Gautier", Text = "On avait revu sur les autoroutes des citoyens honorables prêts à tout pour fuir. Les plus anciens avaient des réminiscences de juin 1940, les moins vieux d'Alger en juillet 1962. C'était toujours le même peuple qui fuyait.", Author = "Philippe Gautier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Mare_au_diable", Text = "Voyez donc la simplicité, vous autres, voyez le ciel et les champs, et les arbres, et les paysans dans ce qu'ils ont de bon et de vrai: vous les verrez un peu dans mon livre, vous les verrez beaucoup mieux dans la nature.", Author = "La Mare au diable" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Madou_%28chanteuse%29", Text = "Je suis venue dire non à la guerre, parce qu'on n'en pas besoin. Moi je l'ai vécue, et je peux témoigner. Je suis venue dire oui à la paix.", Author = "Madou (chanteuse)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89douard_Ngirente", Text = "Notre coopération bilatérale avec la Chine a joué un rôle important dans la transformation de nos secteurs de développement clés, notamment les infrastructures, l’agriculture, la santé, l’éducation, les TIC, le commerce, l’exploitation minière, les transports ainsi que le tourisme.", Author = "Édouard Ngirente" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Taiye_Selasi", Text = "La vue est subjective. Nous l'avons appris en classe.", Author = "Taiye Selasi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jacques_Pierre_Brissot", Text = "Nous n’avons cessé de le répéter dans les divers ouvrages que la société a publiés, l’esclavage a deux terribles conséquences; il avilit l’esclave, il rend le maître barbare. Mais la barbarie du maître surpasse encore la bassesse de l’opprimé; elle ne connoît point de frein, point de loi.", Author = "Jacques Pierre Brissot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gasandji_R%C3%AAver", Text = "Je tuerai, je tuerai, je tuerai le temps...", Author = "Gasandji Rêver" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dieudonn%C3%A9_Niangouna", Text = "L’intellectuel est un poisson qui suit la tempête dans le fleuve.", Author = "Dieudonné Niangouna" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kiy%C3%A9mis", Text = "Debout, divines Negresses, si l'autre, ébloui par la poussière d'étoile que contenait nos auréoles crépues et le reflet du soleil sur la sombre carnation de nos épidermes, voulait éteindre les rayons irradiant de nos auras, il devra se rendre à l'évidence. Nous sommes toujours debout.", Author = "Kiyémis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Monde_diplomatique", Text = "Vous avez quelques journaux quand même qui font un bon boulot et ça vaut la peine. Moi vous savez je suis un fan du Monde diplomatique, parce que je pense que c'est eux qui ont sauvé la pensée pendant les années terribles 90. Et puis ils continuent à faire des papiers absolument formidables.", Author = "Le Monde diplomatique" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nouria_Benghabrit-Remaoun", Text = "Ce bruit ne m’empêchera pas d’avancer et personne n’a le monopole du nationalisme en Algérie.", Author = "Nouria Benghabrit-Remaoun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ndusi_Ntembe", Text = "Les tâches dévolues à l'inspection générale du travail sont assurées par les inspecteurs du travail et contrôleurs du travail assermentés dans leur ressorts territoriaux respectifs, lesquels ont suivi une formation appropriée, ils sont nommés par le ministre de l'ETPS.", Author = "Ndusi Ntembe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aminata_Tall", Text = "Celui qui se sent pousser des ailes sera surpris par sa chute. Moi je connais la valeur intrinsèque de tous les membres du Conseil.", Author = "Aminata Tall" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Constantine", Text = "C'est Constantine, John Constantine, pauvre con.", Author = "Constantine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mathilde_Alanic", Text = "Il y a des endroits qui vous laissent un souvenir aussi touchant qu’un visage aimé.", Author = "Mathilde Alanic" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sniper", Text = "Chérie, toujours la même story une vraie chauve-souris\nOn m’a dit c’est pas une vie faut que t’arrêtes\nMais moi j’suis dans mon monde, laissez moi c’est ma planète", Author = "Sniper" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kalevala", Text = "Le désir têtu me démange, \nl'envie me trotte la cervelle\nd'aller entonner la chanson,\nbouche parée pour le chant mage", Author = "Kalevala" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Odilon_Redon", Text = "L'artiste vient à la vie pour un accomplissement qui est mystérieux. Il est un accident. Rien ne l’attend dans le monde social.", Author = "Odilon Redon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Erreur", Text = "A force d'incanter la perfection, l'indépassable perfection, on pousse à l'erreur, à la faute.", Author = "Erreur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Gu%C3%A9henno", Text = "L'orgueil des jeunes gens ne trouve pas son compte quand on les loue pour ce qu'ils sont. Rien ne les satisfait que de les louer pour ce qu'ils veulent être.", Author = "Jean Guéhenno" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Guillaume_Lecointre", Text = "[La rationalité] consiste simplement à respecter les lois de la logique et le principe de parcimonie. Aucune démonstration scientifique ne souffre de fautes de logique. La sanction immédiate étant sa réfutation.", Author = "Guillaume Lecointre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/N%C3%A9gritude", Text = "Ce n'est pas nous qui avons inventé la négritude, elle a été inventée par tous ces écrivains de la Negro Renaissance que nous lisions en France dans les années 1930.", Author = "Négritude" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C5%93urs_perdus_en_Atlantide", Text = "Aborde ce livre comme tu le ferais d'un territoire inconnu; aborde-le sans carte. Explore-le, et dresse ta propre carte.", Author = "Cœurs perdus en Atlantide" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aicha_Nanette_Cont%C3%A9", Text = "Le numérique présente de nouvelles opportunités pour les enfants, qu’il s’agisse de l’accès à l’éducation ou des possibilités qu’il leur offre pour l’acquisition de connaissances et, pour l’expression de leurs opinions sur des sujets qui les concernent.", Author = "Aicha Nanette Conté" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Samuel_Beckett", Text = "Ces Murphy, Molloy, et autres Malone, je n'en suis pas dupe. Ils m'ont fait perdre mon temps [...] Ils n'ont pas souffert mes douleurs, leurs douleurs ne sont rien, à côté des miennes, rien qu'une petite partie des miennes, celle dont je croyais pouvoir me détacher, pour la contempler.", Author = "Samuel Beckett" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9e_Vivien", Text = "J’ai si longtemps respiré l’air des forêts, l’air vibrant de neige, je me suis si souvent mêlée aux Blancheurs vastes et désertes, que mon âme est un peu l’âme des louves fuyantes.", Author = "Renée Vivien" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Canard_encha%C3%AEn%C3%A9", Text = "Qui imagine le général de Gaulle, tante Yvonne et leurs enfants s’embourber autant de pognon?", Author = "Le Canard enchaîné" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hallgrimur_Helgason", Text = "L'intelligence n'a rien à voir avec l'amour. Et l'amour ne se soucie guère de l'intelligence. Lorsqu'il s'agit d'amour, nous sommes tous plus idiots les uns que les autres.", Author = "Hallgrimur Helgason" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/David_Strauss", Text = "La naissance surnaturelle du Christ, ses miracles, sa résurrection, et son ascension au ciel, demeurent d’éternelles vérités, à quelque doute que soit soumise la réalité de ces choses en tant que faits historiques.", Author = "David Strauss" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mialy_Rajoelina", Text = "Éduquer une fille, c’est éduquer toute la Nation.", Author = "Mialy Rajoelina" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Auguste-Dominique_Ingres", Text = "Il n'y a pas deux arts, il n'y en a qu'un: c'est celui qui a pour fondement le beau éternel et naturel. Ceux qui cherchent ailleurs se trompent, et de la manière la plus fatale.", Author = "Jean-Auguste-Dominique Ingres" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Red_Hot_Chili_Peppers", Text = "Pour faire de la musique c'est simple: imaginez une grande Mona Lisa, et peignez lui des moustaches!", Author = "Red Hot Chili Peppers" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rita_Atria", Text = "Avant de combattre la mafia, vous devez faire un examen de conscience puis, après avoir vaincu la mafia en vous, vous pouvez la combattre dans le cercle de vos amis. La mafia, c’est nous et notre mauvaise façon de nous comporter.", Author = "Rita Atria" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Liqueur", Text = "Les deux ou trois invités retirent leur cache-col. Quand les liqueurs pailletées ne leur feront plus une assez belle nuit dans la gorge, ils allumeront le réchaud à gaz.", Author = "Liqueur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Juin", Text = "Être malheureux en juin est aussi inconvenant que d'être heureux en écoutant du Schubert. C'est ce qui rend ce mois intolérable: pendant trente jours, le moindre état d'âme convainc de sa propre impolitesse.", Author = "Juin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rythme", Text = "Ça et là, un genou cambre le tissu transparent et luit comme un fruit, tandis que les bouches arquées découvrent les dents nettes, au rythme des mots lents suivis de gestes rares et félins.", Author = "Rythme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nicole_Belloubet", Text = "La fonction d'enseignant n'est plus suffisament attractive", Author = "Nicole Belloubet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Opium", Text = "Mon corps est un bocal d'excellent opium qui sert à charmer mes loisirs.", Author = "Opium" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Busola_Tejumola", Text = "Avoir un état d’esprit d’excellence. Elle doit choisir d’être la meilleure dans ce qu’elle fait. L’excellence n’est pas négociable.", Author = "Busola Tejumola" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeanne_d%27Arc_Mujawamariya", Text = "Nous partageons tous la propriété et la responsabilité de la croissance verte et de la résilience climatique.", Author = "Jeanne d'Arc Mujawamariya" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Corde", Text = "La lumière suivra; le jour fera amende honorable, pieds nus, la corde des étoiles au cou, en chemise verte.", Author = "Corde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zouley_Sangar%C3%A9", Text = "On naît seul, meurt seul.", Author = "Zouley Sangaré" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sabine_Huynh", Text = "L'ici est dans l'ici \nl'ailleurs quelque part là-bas", Author = "Sabine Huynh" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mata_Sy_Diallo", Text = "Il y a des gens qui considèrent que je suis une femme âgée. Je suis prête à leur faire comprendre la battante que j’ai toujours été. Je leur prouverai que j’ai toujours été une battante.", Author = "Mata Sy Diallo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabelle_Huppert", Text = "Ce qu’éprouve le spectateur n’a strictement rien à voir avec ce qu’éprouve l’acteur, heureusement... C’est fait pour ça, d’ailleurs.", Author = "Isabelle Huppert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Scholastique_Dianzinga", Text = "Ainsi, les femmes n'ont jamais reculé devant les situations graves et, à toutes les époques elles ont apporté leur contribution.", Author = "Scholastique Dianzinga" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mary_Spio", Text = "Nous vivons une époque de l'Histoire sans précédent, un extraordinaire moment où la technologie nous offre d'incroyables possibilités.", Author = "Mary Spio" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Richard_Millet", Text = "Ce qui est mort, c'est l'idée de culture en tant que civilisation, le Culturel lui, étant l'alliance du divertissement et de la Propagande, c'est-à-dire un conditionnement de masse opérant au nom même du narcissisme individuel.", Author = "Richard Millet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Caroline_Faye_Diop", Text = "La présence d’une seule voix féminine au sein d’une assemblée de voix masculines ne peut constituer un réel poids. Mais celle de Caroline a compté lors du vote du Code de la famille, portant la voix de toutes les autres femmes aphones jusque-là.", Author = "Caroline Faye Diop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dandi_Gnamou", Text = "Une cour n’existe que parce qu’elle rend des décisions. Jusqu’à ce moment, la Haute cour de Justice n’existe pas vraiment parce qu’une cour a une seule vocation: celle de rendre des décisions.", Author = "Dandi Gnamou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Miracle", Text = "L'ardoise du ciel vient justement d'être effacée et tu sais que les miracles ne sont plus que de demi-saison. Rentre chez toi", Author = "Miracle" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Berthe_Morisot", Text = "Je ne crois pas qu’il n'y ait jamais eu un homme traitant une femme d’égale à égal, et c’est tout ce que j’aurais demandé. Car je sais que je les vaux.", Author = "Berthe Morisot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tyler_Rake", Text = "Ovi Mahajan Jr: Quand on se noie, c’est pas en tombant dans la rivière mais en restant submergé par elle.", Author = "Tyler Rake" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Judi_Dench", Text = "Je pense qu'il faut garder bien les pieds sur terre, tout particulièrement dans ce domaine, et qu'on ne doit pas croire ce qui est dit ou écrit à notre sujet, parce que tout devient disproportionné dans un sens ou dans l'autre.", Author = "Judi Dench" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alphonse_de_Lamartine", Text = "Je suis le premier qui ai fait descendre la poésie du Parnasse, et qui ai donné à ce qu'on nommait la muse, au lieu d’une lyre à sept cordes de convention, les fibres mêmes du cœur de l’homme, touchées et émues par les innombrables frissons de l’âme et de la nature.", Author = "Alphonse de Lamartine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pascal_N%C3%A8gre", Text = "La moitié des ventes du catalogue disponible sur iTunes est réalisée par le top 200, contre seulement un tiers pour le marché physique.", Author = "Pascal Nègre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hassiba_Boulmerka", Text = "Je ne peux tout de même pas courir avec un hidjab (robe longue et foulard qui cache le cou et les cheveux). Après tout on ne va pas à la mosquée en short.", Author = "Hassiba Boulmerka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Garou-Garou%2C_le_passe-muraille", Text = "Les têtes d'assassins ça se reconnaît qu'une fois dans le panier. Et encore pas toujours.", Author = "Garou-Garou, le passe-muraille" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Short_Circuit", Text = "Mauvais fonctionnement. Demande infos.", Author = "Short Circuit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Henning_Mankell", Text = "Vieillir, c'est être en proie à l'inquiétude. L'inquiétude envers tout ce qui vous faisait peur quand on était enfant revient quand on est vieux...", Author = "Henning Mankell" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christine_Lagarde", Text = "Je pense que les Grecs devraient se venir en aide mutuellement [...] en payant tous leurs impôts.", Author = "Christine Lagarde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dani%C3%A8le_Diwouta-Kotto", Text = "La politique en matière de préservation du patrimoine au Cameroun est très succincte, et l'État tarde d'une manière générale à aller au-delà de l'inventaire renouvelé de bâtiments qui mériteraient une attention particulière en matière de préservation. Cette architecture tolérée n'est pas entretenue.", Author = "Danièle Diwouta-Kotto" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne_F._Garr%C3%A9ta", Text = "Au premier coup de couteau, de minuit ou de foudre, le criminel et l'amant estoquent ou se toquent aussi sûrement que jaillit des kitsch tréfonds d'une horloge jurassienne le grotesque coucou.", Author = "Anne F. Garréta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Falk_van_Gaver", Text = "Face à cette conspiration du bruit, fomentons la conjuration du silence. Face à la majorité bruiteuse, tweeteuse, réseauteuse, soyons la minorité silencieuse.", Author = "Falk van Gaver" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Louis_Murat", Text = "Je prends le clavier ou je me mets à la guitare, sur chaque ligne mélodique, il y a des mots, donc je ne sais pas vraiment ce que c’est que de mettre un texte sur une musique.", Author = "Jean-Louis Murat" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Agence_France-Presse", Text = "Tu lis trop l'AFP, pas assez les grands philosophes!", Author = "Agence France-Presse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ira_Levin", Text = "– Tu étais vivant, tu ressentais quelque chose. Et n'importe quel sentiment vaut mieux que pas de sentiment du tout.", Author = "Ira Levin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kenneth_Boulding", Text = "Celui qui croit à une croissance exponentielle infinie dans un monde fini est soit un fou, soit un économiste.", Author = "Kenneth Boulding" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cameroun", Text = "Camerounais, Camerounaises, le Cameroun est libre.", Author = "Cameroun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Battlestar_Galactica_%282003%29", Text = "C'est ce que tous nous disons.", Author = "Battlestar Galactica (2003)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Julien_Denormandie", Text = "Et le gaspillage! Savez-vous quelle quantité d'aliments est perdue chaque année? Plus d'un milliard de tonnes, soit l'équivalent d'un tiers de la production totale des denrées alimentaires à destination de la consommation humaine.", Author = "Julien Denormandie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sorj_Chalandon", Text = "La première fois que j'ai vu mon traitre, il m'a appris à pisser.", Author = "Sorj Chalandon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Jos%C3%A9_Mondzain", Text = "Cette vie propre à l’image peut être celle d’un corps, d’une pensée, d’un déroulement conceptuel, d’une action politique.", Author = "Marie-José Mondzain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vendeur", Text = "Ceux qui posent le plus de questions, vendent le plus.", Author = "Vendeur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bozoma_Saint_John", Text = "S'il vous plaît. Cela me procure tout ce dont j'ai besoin.", Author = "Bozoma Saint John" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Relativit%C3%A9_g%C3%A9n%C3%A9rale", Text = "Il est fascinant de voir dans le carnet de notes dit de Zurich, qu'Einstein et Grossmann arrivent à deux doigts des équations finales de la relativité générale, mais les rejettent car elle ne redonnent pas celles de Newton dans la limite des champs faibles.", Author = "Relativité générale" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Onzi%C3%A8me_Docteur", Text = "Le Docteur: Pour moi, la vie de chaque individu est une pile de bonnes choses et de mauvaises choses. Les bons moments ne te font pas forcément oublier les moments difficiles, mais dis-toi bien que les mauvaises expériences ne gâchent pas nécessairement les bonnes expériences.", Author = "Onzième Docteur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Antoni_Pastor_Cabrer", Text = "Quand on affronte une situation limite, il faut savoir quel est le scénario limite. Il est évident que je ne pensais pas que le PP pût prendre une décision comme celle-ci au sujet de la langue.", Author = "Antoni Pastor Cabrer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Leroux", Text = "La société n'est plus qu'un amas d'égoïsmes, ce n'est plus un corps, ce sont les membres séparés d'un cadavre.", Author = "Pierre Leroux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Angelin_Preljocaj", Text = "Aujourd’hui, le hip-hop a rendu la danse plus masculine, donc plus acceptable pour les hommes, mais à l’époque, dans le quartier de banlieue où j’habitais, c’était une chose très étrange, un garçon qui faisait de la danse.", Author = "Angelin Preljocaj" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Toponymie", Text = "La toponymie n'est pas à la disposition d'une majorité compétente, elle est un patrimoine qui doit être géré précautionneusement dans le respect des générations passées et dans l'intérêt de celles à venir.", Author = "Toponymie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/V%C3%A9ronique_Tadjo", Text = "Si tu veux aimer\nFais-le\nJusqu'au bout du monde\nSans faux détours\nÀ vol d'oiseau.", Author = "Véronique Tadjo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bibata_Ouedraogo", Text = "C’est nous et nous seules qui menons une grossesse à terme. Et c’est à nous de décider si nous voulons être enceintes ou pas.", Author = "Bibata Ouedraogo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lizzy_Hawker", Text = "Ma stratégie pour chaque course est simplement de courir du mieux que je peux à chaque instant.", Author = "Lizzy Hawker" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mohammed_Kudus", Text = "Naturellement, j'ai été construit avec ce centre de gravité bas par rapport au sol, il m'est donc facile de me retourner. J'ai également travaillé là-dessus au gymnase, car j'ai vu que c'était ma force, donc je continue de bâtir là-dessus et c'est ce qui m'a le plus aidé dans mes dribbles.", Author = "Mohammed Kudus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ad%C3%A8le_Kahinda_Mayina", Text = "Nos entreprises ont besoin d'un renouveau pour le développement de l'économie nationale", Author = "Adèle Kahinda Mayina" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Genevi%C3%A8ve_de_Gaulle-Anthonioz", Text = "Du fond de l'abîme, moi aussi j'appelle Dieu comme l'ont fait tant d'autres. J'essaie de me remettre à la miséricorde du Père, de m'unir à l'agonie de Jésus au Jardin des Oliviers. Ce n'est même pas un silence qui me répond, mais la misérable rumeur de ma détresse.", Author = "Geneviève de Gaulle-Anthonioz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7oise_Mbango_Etone", Text = "Que personne ne vous fasse croire que je ne m’investis pas, je ne demande qu’à m’investir pour transmettre aux jeunes mon vécu et mon expérience.", Author = "Françoise Mbango Etone" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joseph_Joubert", Text = "Quand mes amis sont borgnes, je les regarde de profil.", Author = "Joseph Joubert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ludwig_Wittgenstein", Text = "En un certain sens, nous ne devons pas pouvoir nous tromper en logique. C’est ce qui est déjà partiellement exprimé dans la phrase: la logique doit prendre soin d’elle-même. C’est là une connaissance exceptionnellement importante et profonde.", Author = "Ludwig Wittgenstein" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mutale_Nalumango", Text = "Une Afrique intégrée, prospère et pacifique, dirigée par ses propres citoyens, représentant une force dynamique sur la scène internationale.", Author = "Mutale Nalumango" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isra%C3%ABl", Text = "En Israël, les rabbins ont acquis de plus en plus d'influence et ils s'en servent pour maintenir le peuple dans l'ignorance. Autant le peuple est ignorant et crédule, autant est plus forte la caste sacerdotale.", Author = "Israël" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joyce_Mansour", Text = "Il m'est difficile de penser à la mort \nQuand sur mon ventre hésitent de grands oiseaux \nAux pâles retards de sperme \nEt habiletés d'écume.", Author = "Joyce Mansour" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Douglas_MacArthur", Text = "La menace communiste est mondiale. Sa victoire dans n'importe quel domaine menace de détruire tous les autres domaines.", Author = "Douglas MacArthur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zygmunt_Bauman", Text = "Peu de chose se rapprochent autant de la mort que l'amour accompli. Chaque apparition des deux est unique mais aussi définitive, elle n'admet pas la répétition, n'autorise aucun appel et ne promet aucun sursis. Chacun doit, et le fait, tenir tout seul.", Author = "Zygmunt Bauman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roger_Golay", Text = "Nous avons fait beaucoup de propositions. Je suis fier de notre modification constitutionnelle sur le double mandat, que le peuple a plébiscité. Mais bien des partis refusent de soutenir nos idées, même s'ils les approuvent, afin de nous affaiblir.", Author = "Roger Golay" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Omar_el-Bechir", Text = "Ils ont dit vouloir que l'armée prenne le pouvoir. Aucun problème. Si quelqu'un arrive en tenue militaire, nous n'avons aucune objection. Quand l'armée se déplace, elle ne se déplace pas en vase clos. Elle ne se déplace pas pour soutenir des traîtres. Elle se déplace pour soutenir la patrie.", Author = "Omar el-Bechir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Foire_aux_cancres", Text = "Le vrai fondateur du royaume d'Israël était David qui tua le géant Colgate.", Author = "La Foire aux cancres" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C3%A9lestine_Adjanohoun", Text = "La volonté politique c’est ce qu’il faut pour le développement énergétique du Bénin. Et puis, l’Etat est en train de diversifier les sources d’approvisionnement", Author = "Célestine Adjanohoun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/St%C3%A9phane_Rousson", Text = "Voler avec un ballon à pédale, ca sert à rien, mais c'est un défi technologique.", Author = "Stéphane Rousson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Trois_Mousquetaires_%28film%2C_1953%29", Text = "Une amitié pour être bien trempée doit l’être dans le sang des autres.", Author = "Les Trois Mousquetaires (film, 1953)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Johan_Bourret", Text = "Il suffit de peu de choses pour rassasier celui qui ne possède rien.", Author = "Johan Bourret" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zita_Oligui_Nguema", Text = "J’ai grandi voyant des jeunes sombrer dans la drogue et l’alcool, et je souffrais d’être impuissante pour agir. Aujourd’hui le destin m’offre la possibilité d’apporter ma contribution pour le bien-être de mon prochain.", Author = "Zita Oligui Nguema" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dr_House", Text = "House: Le labo vient d'analyser ce métal. Il n'est pas répertorié sur Terre. Il serait même d'origine extraterrestre.\nChase: C'est sérieux?\nHouse: Mais non imbécile, c'est du titane!", Author = "Dr House" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Desplechin", Text = "Elliott Erwitt a photographié des enfants. Il a aussi photographié des chiens.(...). Des mômes et des clebs. D'autres ne s'en seraient pas relevés.", Author = "Marie Desplechin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Matsuo_Bash%C5%8D", Text = "Au printemps qui s'en va\nles oiseaux crient -\nles yeux des poissons en larmes", Author = "Matsuo Bashō" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jaha_Dukureh", Text = "Parfois, quand une chose est insupportable à imaginer, nous faisons le contraire de ce que nous devrions: nous nous en détournons pour protéger nos cœurs et nos esprits afin de préserver notre paix intérieure.", Author = "Jaha Dukureh" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/X-Files_%3A_Aux_fronti%C3%A8res_du_r%C3%A9el", Text = "Mulder: Désolé, il n'y a personne à part le plus-mal aimé des agents du FBI.", Author = "X-Files : Aux frontières du réel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Magda_Szab%C3%B3", Text = "Je n'avais pas analysé à fond à quel point l'affection est un sentiment illogique, immortel, imprévisible, et pourtant je connaissais la littérature grecque qui ne représentait rien d'autre que les passions, la mort.", Author = "Magda Szabó" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Onfray", Text = "Il n'est d'autre remède aux tyrannies que de cultiver l'énergie des puissances singulières, des monades.", Author = "Michel Onfray" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Apostasie", Text = "La Franc-Maçonnerie, qui avait inspiré cette apostasie criminelle, a désorganisé la famille, comme elle a désorganisé l’école.", Author = "Apostasie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Geluck", Text = "Le meilleur en termes d'humour, c'est Philippe Geluck. Il n'y a pas aussi productif, inventif et drôle que lui.", Author = "Philippe Geluck" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/SOS_Fant%C3%B4mes_2", Text = "Professeur Janosz Poha (à une élève): Tout ce que vous faites est affreux; je veux que vous le sachiez.", Author = "SOS Fantômes 2" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Luc_Coudray", Text = "L'infiniment petit est plus riche que l'infiniment grand.", Author = "Jean-Luc Coudray" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Christophe_Grang%C3%A9", Text = "Il existe un axiome universel: plus on descend vers le sud, plus rigueur et fiabilité s'amenuisent, comme si ces deux valeurs fondaient au soleil.", Author = "Jean-Christophe Grangé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Genet", Text = "Le jardinier est la plus belle rose de son jardin.", Author = "Jean Genet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-C%C3%A9lie_Agnant", Text = "La haine, c’est comme une odeur de brûlé ou de pourri. Il n’est pas facile de la maquiller.", Author = "Marie-Célie Agnant" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hadiza_Bazoum", Text = "chacun et chacune d’entre nous, a un rôle à jouer dans la consolidation et la préservation de la paix et de la sécurité.", Author = "Hadiza Bazoum" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fr%C3%A9d%C3%A9ric_Titinga_Pac%C3%A9r%C3%A9", Text = "Si la branche veut fleurir, qu’elle honore ses racines.", Author = "Frédéric Titinga Pacéré" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/P%C3%A9ch%C3%A9s_capitaux", Text = "Les péchés capitaux sont appelés ainsi, parce qu'ils sont en effet, les chefs, la cause, le principe, la source de tous les péchés. Comme la tête conduit le corps et lui imprime le mouvement, de même les péchés capitaux impriment le mouvement à l'âme pour commettre les autres péchés.", Author = "Péchés capitaux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yayoi_Kusama", Text = "Le pois a la forme du soleil, il signifie énergie masculine, source de la vie. Le pois a la forme de la lune, il symbolise le principe féminin de la reproduction et de la croissance. Les pois suggèrent la multiplication à l'infini. Notre terre n'est qu'un pois parmi les millions d'autres...", Author = "Yayoi Kusama" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Henri_Alleg", Text = "Un jour arrive où les silences, les omissions, les fausses vérités et les simples mensonges ne résistent plus à la réalité des faits.", Author = "Henri Alleg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Madjissem_Beringaye", Text = "Rêvez grand, commencez petit et agissez maintenant.", Author = "Madjissem Beringaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vitas_Gerulaitis", Text = "Et que ce soit une leçon pour vous tous. Personne ne bat Vitas Gerulaitis 17 fois de suite!", Author = "Vitas Gerulaitis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Maquisards", Text = "La raison d’être du colonialisme, c’est l’exploitation des richesses.", Author = "Les Maquisards" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Henri_Jeanson", Text = "Par terre on se dispute, mais au lit on s'explique. Et sur l'oreiller, on se comprend!", Author = "Henri Jeanson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yasmine_Char", Text = "Les mots sortent trop vite. Les mots glissent, heurtent, s'entrechoquent et nous restons immobiles, plus petits que la parole, à regarder le cœur en lambeaux notre idéal qui s'écroule.", Author = "Yasmine Char" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ada_Lovelace", Text = "Je crois que je possède une singulière combinaison de qualités, qui semble précisément ajustées pour me prédisposer à devenir une exploratrice des réalités cachées de la Nature.", Author = "Ada Lovelace" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hector_Malot", Text = "C'est avec les fils qui aiment leur mère qu'on fait les maris qui aiment leur femme.", Author = "Hector Malot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mah%C4%81bh%C4%81rata", Text = "Le sage n'obtient rien qui aille contre l'ordre du monde.", Author = "Mahābhārata" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Antoinette_Pesk%C3%A9", Text = "Elle était d'avis, comme moi, que ce qu'on détestait, il faillait non pas l'éloigner de soi par le geste ou la pensée, mais le supprimer radicalement, et ce qu'on aimait, afin d'être sûr de n'en pas être séparé, mieux valait le dévorer plutôt qu'essayer de l'étreindre dans ses bras ou dans sa main.", Author = "Antoinette Peské" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Violet", Text = ". Sa robe était du même violet que le soir.", Author = "Violet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Phoebe_Philo", Text = "Je m'occupe de la location, de l’espace et de l'achat de mobilier de bureau.", Author = "Phoebe Philo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Benjamin_Constant", Text = "La guerre et le commerce ne sont que deux moyens différents d'arriver au même but: celui de posséder ce que l'on désire.", Author = "Benjamin Constant" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mariatou_Kon%C3%A9", Text = "La journée internationale de l’éducation vient nous rappeler que l’éducation est un droit fondamental dans lequel il est nécessaire d’investir et d’en faire une priorité.", Author = "Mariatou Koné" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roland_Ries", Text = "Nous servons de la viande halal par respect pour la diversité mais pas de poisson le vendredi par respect pour la laïcité.", Author = "Roland Ries" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/J%C3%A9mima_Catray%C3%A9", Text = "Les saisons sont déséquilibrées. Nous panafricaines, avons l’intention de fédérer nos efforts pour montrer au monde entier que les changements climatiques ne sont pas une fatalité.", Author = "Jémima Catrayé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Timothy_Gowers", Text = "Ce ne sont pas les problèmes eux-mêmes et les résultats qui ont un grand intérêt, mais plutôt les méthodes et les techniques qu’il faut développer pour résoudre les problèmes.", Author = "Timothy Gowers" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Arme_fatale", Text = "Je suis trop vieux pour ces conneries.", Author = "L'Arme fatale" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mariano_Melgarejo", Text = "Soldats! L’intégrité de la France est menacée par la Prusse. Celui qui menace la France menace la civilisation et la liberté. Je vais protéger les Français qui sont nos amis et qui nous aiment. Venez avec moi, nous traverserons l’océan à la nage, et attention à ne pas mouiller vos munitions!", Author = "Mariano Melgarejo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Madame_de_La_Fayette", Text = "La magnificence et la galanterie n'ont jamais paru en France avec tant d'éclat que dans les dernières années du règne de Henri second.", Author = "Madame de La Fayette" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mo_Abudu", Text = "Si tu peux y penser, tu peux le faire.", Author = "Mo Abudu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Esprit", Text = "Une psychologie de l'esprit en action est automatiquement la psychologie d'un esprit exceptionnel, la psychologie d'un esprit que tente l'exception: l'image nouvelle greffée sur une image ancienne.", Author = "Esprit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mama_Kanny_Diallo", Text = "Chaque citoyen, intellectuel ou non, percevra aisément la portée du plan, et l’adhésion de tous est absolument indispensable.", Author = "Mama Kanny Diallo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-Augustin_Caron_de_Beaumarchais", Text = "Quand on cède à la peur du mal, on ressent déjà le mal de la peur.", Author = "Pierre-Augustin Caron de Beaumarchais" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Natalie_Dessay", Text = "Nous, chanteurs d'opéra, sommes des athlètes, et donc nous avons une date de péremption, quand le corps ne répond plus selon nos normes. De plus, si on commence à s'ennuyer pour diverses raisons, il faut passer à autre chose.", Author = "Natalie Dessay" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Percy_Jackson", Text = "Pour vous, c'est deux heures de divertissement. Pour moi, c'est le travail d'une vie traversant un hachoir à viande alors que je les ai implorés de ne pas faire ça.", Author = "Percy Jackson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yannick_Noah", Text = "Si Sarkozy passe, je me casse.", Author = "Yannick Noah" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_Katungu_Furaha", Text = "Lorsque vous placez votre confiance aux hommes, faites-le aussi pour les femmes. Les hommes et les femmes sont égaux devant la loi", Author = "Catherine Katungu Furaha" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C._S._Lewis", Text = "Je suis un païen converti vivant au milieu de puritains apostats.", Author = "C. S. Lewis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/No%C3%ABl_Coward", Text = "Ce qu'on ne peut vraiment pas pardonner aux Français, c'est que parfois parmi eux il y a des gens très bien.", Author = "Noël Coward" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-F%C3%A9lix_P%C3%A9degert", Text = "J’ai dit adieu à la poésie française, et si j’ai jamais vie et loisir, je composerai en gascon.", Author = "Jean-Félix Pédegert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Konrad_Lorenz", Text = "Mon livre traite de l'agressivité, c'est-à-dire l'instinct de combat de l'animal et de l'homme, dirigé contre son propre congénère.", Author = "Konrad Lorenz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sh%C5%8Dtar%C5%8D_Ishinomori", Text = "Dans la nature tous les animaux et végétaux, quels qu'ils soient, constituent un maillon indispensable d'une même communauté. Oui, une communauté dont nous faisons tous partie!", Author = "Shōtarō Ishinomori" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Muhammad_Sa%C3%AFd_al-Ashmawi", Text = "Dieu voulait que l'islam fût une religion, mais les hommes ont voulu en faire une politique.", Author = "Muhammad Saïd al-Ashmawi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Micheline_Calmy-Rey", Text = "Si la Suisse n'est pas membre de l'Union européenne, elle a de tout temps partagé les valeurs européennes.", Author = "Micheline Calmy-Rey" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Circ%C3%A9", Text = "Des cochons, ils avaient les groins, les grognements, les soies,\ntout enfin, sauf l'esprit, qui resta esprit de mortel.", Author = "Circé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Duchamp", Text = "Voir\nOn peut regarder voir;\nOn ne peut pas entendre entendre.", Author = "Marcel Duchamp" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Antoine_de_Rivarol", Text = "Il y a des temps où le gouvernement perd la confiance du peuple, mais je n'en connais pas où le gouvernement puisse se fier au peuple.", Author = "Antoine de Rivarol" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bernard_Tirtiaux", Text = "Il vient un temps où toute conquête devient sans objet, où les jours sont, sur le métier d’un tisserand, de simples fils de trame qui s’ajoutent les uns aux autres pour terminer l’étoffe grise de la vie.", Author = "Bernard Tirtiaux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Reckya_Madougou", Text = "Il n’y a pas de démocratie tant que certaines cibles de la population sont mal intégrées", Author = "Reckya Madougou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Albert_Allen_Bartlett", Text = "Si cette croissance modeste de 1,3% pourrait continuer, la population mondiale atteindrait la densité d'une personne par mètre carré de terre émergée dans 780 ans. Et la masse des gens équivaudrait à la masse de la terre dans 2400 ans.", Author = "Albert Allen Bartlett" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Blade_Runner", Text = "Rachel: Notre hibou vous plaît.\nRick Deckard: Il est artificiel?\nRachel: Bien sûr qu'il l'est.\nRick Deckard: Il a dû coûter cher.\nRachel: Une fortune. Je m'appelle Rachel.\nRick Deckard: Deckard.", Author = "Blade Runner" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Angela_Bassett", Text = "L’univers ne vous fait jamais mentir", Author = "Angela Bassett" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Malika_Sorel", Text = "On n'a jamais tant parlé de laïcité que depuis qu'elle s'enfuit à grands pas, de même que l'on n'a jamais tant parlé de vivre-ensemble que depuis que ce dernier est malmené, se traduisant par un fort désir d'évitement. Ces deux volets ne sont d'ailleurs pas sans rapport, loin s'en faut.", Author = "Malika Sorel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ayra_Starr", Text = "En regardant en arrière, je dirais [à mon moi passé]: Arrête de ressasser le passé, ne regarde pas de côté, ne regarde pas à gauche et à droite, continue d’avancer – je te dis que tu vas voir un changement, crois-moi.", Author = "Ayra Starr" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Politique", Text = "Les gens gueulent: j'ai voté pour celui-là, et au lieu de mettre de l'argent dans les écoles, il met de l'argent dans les prisons. Si y'a une chose de sûre, quand on est ministre, c'est qu'on retournera pas à l'école, tandis qu'en prison, faut voir…", Author = "Politique" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tourn%C3%A9e_%28film%29", Text = "Joachim: If Le Havre loves you, France is gonna love you.", Author = "Tournée (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeannette_Kavira_Mapera", Text = "Quand on n’est pas en paix, même si on reçoit un don, c’est difficile de consommer ce don.", Author = "Jeannette Kavira Mapera" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Proph%C3%A9tie_des_grenouilles", Text = "Ferdinand: Et voilà, c'est reparti avec tes grand-père! Tu veux pas m'appeler Papa, tout simplement?\nTom: Papa?! Mais j'y arriverai jamais, t'es trop vieux!", Author = "La Prophétie des grenouilles" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89velyne_Mpoudi_Ngol%C3%A9", Text = "Il faut que la femme puisse vivre sa vie comme un être humain à part entière et non pas comme le complément de quelque chose d'autre.", Author = "Évelyne Mpoudi Ngolé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaamelott/S%C3%A9li", Text = "Des bons à rien, j’en ai vu, mais le coup de la Table Ronde, alors là… C’est le rendez-vous des mains dans les poches.", Author = "Kaamelott/Séli" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Tumba_Nzeza", Text = "La Haine n’a jamais construit. Bien au contraire, elle détruit tout et en définitive, elle tue.", Author = "Marie Tumba Nzeza" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/B%C3%AAte_du_G%C3%A9vaudan", Text = "C'est en l'an 1764 que la bête apparut sur nos terres, et les fit siennes. Un an plus tard, sa renommée dépassait les frontières de notre province et l'on commençait à penser que nul mortel n'en viendrait jamais à bout. Sous ses assauts, le pays de Gévaudan s'enfonçait peu à peu dans les ténèbres.", Author = "Bête du Gévaudan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Proc%C3%A8s_de_Socrate", Text = "Platon a exécuté le tour d’illusionniste le plus réussi de l’histoire, en persuadant la postérité que le procès de Socrate fut unique parmi les poursuites intentées en raison de la loi de Diopeithès, et même parmi tous les événements de l’histoire athénienne.", Author = "Procès de Socrate" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mame_Younousse_Dieng", Text = "Si c’est réclamer les droits de la Femme sur le plan social, professionnel et religieux, le respect réciproque tout en étant soumise à un mari raisonnable, responsable et respectable, qui se comporte comme le mari religieux cité ci- dessus… alors, je suis féministe.", Author = "Mame Younousse Dieng" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rama_Yade", Text = "Je me suis longtemps méfiée de l'engagement politique, en particulier des beaux parleurs qui ne sont pas toujours là pour assumer.", Author = "Rama Yade" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Salla_Dieng", Text = "Une lettre, ce n'est jamais que du temps que l'on transforme en amitié, en colère, en exigence, en souvenir, en amour, en regret, en douleur, en douceur... Une lettre, c’est comme de la pâte à modeler, on lui fait prendre la forme que l’on veut en y imprimant une parcelle de soi, don à autrui.", Author = "Salla Dieng" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vitellius", Text = "Le cadavre d’un ennemi sent toujours bon, surtout si c'est celui d'un concitoyen.", Author = "Vitellius" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fabiola_Faida_Mwangilwa", Text = "Je suis intéressée par la défense de droits de femme mais surtout leur participation dans la gestion des affaires publiques. Mais ce n’est pas seulement en politique, j’ai dit tous les secteurs de la vie nationale", Author = "Fabiola Faida Mwangilwa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ang%C3%A9lique_Kidjo", Text = "Je travaille avec tous ceux qui pensent que la musique est l’arme de la paix. Pour moi, la musique est avant tout la seule forme d’art qui lie tout le monde.", Author = "Angélique Kidjo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ir%C3%A8ne_Esambo_Diata", Text = "La femme est le socle de la famille et de la nation.", Author = "Irène Esambo Diata" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Deuxi%C3%A8me_R%C3%A9publique_de_Pologne", Text = "Cette Pologne s'est trouvée reconstituée en une nation indépendante et souveraine. Son premier acte a été la violation du traité auquel elle doit sa souveraineté et sa nationalité.", Author = "Deuxième République de Pologne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Veeby", Text = "C’est un voyage au cœur de ce qui fait ma personnalité musicale. Des rythmes variées, un style original et des messages engagés qui interpellent.", Author = "Veeby" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/V%C3%A9ronique_Kanor", Text = "Je suis le vernis cassé. Je suis la misère délabrée, le poisson mal vidé. Je suis ma case en tôle, une jarre d’or qui n’existe pas. Je suis la nouvelle venue à godillots, celle qui ne sait pas faire la bise avec le front, celle qui revient au pays prénatal sans avoir composté l’aller.", Author = "Véronique Kanor" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Louise_Correa", Text = "J’exhorte les jeunes à entreprendre une nouvelle citoyenneté autour des valeurs éducatives.", Author = "Marie-Louise Correa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amina_Damerdji", Text = "Aïcha courut à travers le village. Ses jambes tremblaient et son coeur battait si fort qu'il semblait vouloir sortir de sa poitrine. Elle connaissait le mot, dhabahine, les égorgeurs. Dhabahine, dhabahine!", Author = "Amina Damerdji" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Initiative_populaire_%C2%ABPour_la_protection_face_%C3%A0_la_violence_des_armes%C2%BB", Text = "Les dictatures sont les premières à désarmer leurs citoyens car l'arme, c'est le pouvoir.", Author = "Initiative populaire «Pour la protection face à la violence des armes»" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Victor_Chklovski", Text = "Mon ami, mon très cher. Ne me parle pas d'amour. Il ne faut pas. Je suis très fatiguée. Comme tu le dis toi-même, j'en ai plein le dos. C'est la vie, la vie de tous les jours, qui nous sépare, toi et moi. Je ne t'aime pas et ne t'aimerai jamais.", Author = "Victor Chklovski" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eug%C3%A9nie_Dossa_Quenum", Text = "La République doit traiter ses enfants de la même manière, qu’ils soient citadins ou villageois de localités éloignées.", Author = "Eugénie Dossa Quenum" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/R%C3%A9volution_fran%C3%A7aise_de_1848", Text = "Nul n’a droit au superflu tant que chacun n’a pas le nécessaire.", Author = "Révolution française de 1848" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Rawls", Text = "La justice est la première vertu des institutions sociales comme la vérité est celle des systèmes de pensée.", Author = "John Rawls" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/R%C3%A9seaux_sociaux", Text = "Ce que raconte Cœur du Sahel – le viol d'une domestique, ou le plaisir que prend une jeune fille en faisant l'amour – a provoqué un scandale sur les réseaux sociaux immédiatement après la publication du livre. Ces conséquences ne me gênent pas: j'écris pour bousculer et provoquer des changements.", Author = "Réseaux sociaux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Psychiatrie", Text = "La psychiatrie actuelle est dans une impasse. Elle est totalement inféodée à l’industrie pharmaceutique, qui réalise des bénéfices astronomiques avec ses médicaments chimiques et contrôle ainsi la société de manière très détaillée.", Author = "Psychiatrie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_S%C3%A9guin", Text = "Voilà trente-cinq ans que toute une oligarchie d'experts, de juges, de fonctionnaires, de gouvernants prend, au nom des peuples, sans en avoir reçu mandat, des décisions dont une formidable conspiration du silence dissimule les enjeux et minimise les conséquences.", Author = "Philippe Séguin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Paul-Louis_Courier", Text = "On écrit aujourd’hui assez ordinairement sur les choses qu’on entend le moins. Il n’y a si petit écolier qui ne s’érige en docteur. À voir ce qui s’imprime tous les jours, on dirait que chacun se croit obligé de faire preuve d’ignorance.", Author = "Paul-Louis Courier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emma_de_Caunes", Text = "Je suis pour les lois progressistes, les lois qui voient devant […] À partir du moment où les gens savent s’aimer, je ne vois pas le problème. Tant que l’enfant reçoit de l’amour, il n’y a aucune raison que le résultat de leur amour ne soit pas légal", Author = "Emma de Caunes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christine_Ntahe", Text = "Elles, Un hommage aux oubliées raconte le travail d'ombre de ces battantes qui n’avaient d’autre urgence qu’un peu de sérénitépourlesleurs.", Author = "Christine Ntahe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Koko_Ateba", Text = "Au fait quelqu’un peut il me dire pourquoi je ne suis jamais invitée dans ce genre de truc? La soirée du tourisme et du potentiel de notre pays… je ne suis pas assez typique d’une région?", Author = "Koko Ateba" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ad%C3%A8le_Haenel", Text = "Je dois le fait de pouvoir parler à celles qui ont parlé avant dans le cadre de #Metoo. C’est une responsabilité pour moi, aujourd’hui je ne suis pas dans la même précarité que la plupart des gens à qui ça arrive. Je voulais leur parler à eux. Leur dire qu’ils ne sont pas seuls.", Author = "Adèle Haenel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-Joseph_Proudhon", Text = "La propriété, c'est le vol!", Author = "Pierre-Joseph Proudhon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aranya_Johar", Text = "Depuis l’âge de 9 ans, je gifle mon visage avec des crèmes pour l’éclaircir.", Author = "Aranya Johar" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gladiator", Text = "Maximus: Force et honneur.", Author = "Gladiator" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabelle_Monnin", Text = "Nous étions fiers de nos valeurs comme des héritiers peuvent être fiers d'une maison qu'on leur a léguée, nous devenons des complexés des bons sentiments", Author = "Isabelle Monnin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sophie_Coignard", Text = "Alors que j’enquête sur ce sujet depuis des années, j’ai longtemps oscillé entre deux convictions: la franc-maçonnerie n’est plus que l’ombre d’elle- même; elle connaît, au contraire, une vivacité discrète mais bien réelle.", Author = "Sophie Coignard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mambou_Aim%C3%A9e_Gnali", Text = "Le mariage n’est pas un jeu. Dans nos us et coutumes, il s’agit là d’un acte visant à perpétuer la famille.", Author = "Mambou Aimée Gnali" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Robert_Seldon_Lady", Text = "Quand on travaille pour les renseignements, on fait des choses qui ne sont pas légales dans le pays dans lequel on travaille. On vit dans l’illégalité.", Author = "Robert Seldon Lady" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Abiba_Dafia_Ouassagari", Text = "J’ai toujours été responsable au sein de notre syndicat. Je n’aime pas voir les gens être brimés dans leurs droits.", Author = "Abiba Dafia Ouassagari" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_Millet", Text = "Je ne suis pas complètement désespérée .", Author = "Catherine Millet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karamatou_Fagbohoun", Text = "le temps est donc arrivé pour partir du Bloc Républicain, pas sans regrets, mais sans animosité, sans méchanceté.", Author = "Karamatou Fagbohoun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mpule_Kwelagobe", Text = "Nous devons nous attaquer à ce problème [VIH/SIDA] et améliorer davantage nos comportements.", Author = "Mpule Kwelagobe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christian_Tal_Schaller", Text = "De nombreux travaux de recherche montrent que les fruits et légumes cultivés biologiquement contiennent 25% de plus de vitamines, enzymes, oligoéléments et hormones bioactives que des végétaux cultivés avec des engrais chimiques.", Author = "Christian Tal Schaller" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuelle_B%C3%A9art", Text = "J'ai dans la tête des histoires qui courent et je pense que le cinéma prendra cette forme-là, je l'espère…", Author = "Emmanuelle Béart" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_de_La_Tour_du_Pin", Text = "Le travail n’a pas pour but la production des richesses, mais la sustentation de l’homme.", Author = "René de La Tour du Pin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Choderlos_de_Laclos", Text = "Je suis sûre que si j'avais le bon esprit de le quitter à présent, il en serait au désespoir; et rien ne m'amuse comme un désespoir amoureux. Il m'appellerait perfide, et ce mot de perfide m'a toujours fait plaisir; c'est, après celui de cruelle, le plus doux à l'oreille d'une femme.", Author = "Pierre Choderlos de Laclos" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/W._H._Auden", Text = "Il y a dix-sept ans est paru, sans fanfare, un livre appelé Le Hobbit qui, à mon avis, est l'une des meilleures histoires pour enfants de notre siècle.", Author = "W. H. Auden" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Simon_%28m%C3%A9decin%29", Text = "L’euthanasie procède d’une démarche qui ne s’admet pas sans heurts. Les solutions que nous fournit la morale traditionnelle ne peuvent pourtant plus nous contenter. Elles reposent sur une sacralisation du principe de vie, dont l’essence est superstitieuse et la démarche fétichiste.", Author = "Pierre Simon (médecin)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Big_Fish", Text = "Edward Bloom: Parfois, le seul moyen d'attraper une femme insaisissable, c'est de lui offrir une alliance.", Author = "Big Fish" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arnaud_Montebourg", Text = "Ségolène Royal n'a qu'un seul défaut, c'est son compagnon.", Author = "Arnaud Montebourg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Agn%C3%A8s_Desarthe", Text = "Chacun pense avoir un secret. Pour certains, c'est une douleur, pour d'autres, une joie. C'est toutefois sans importance, car, un jour ou l'autre, une main indifférente, tombée mollement du ciel, les moissonnera", Author = "Agnès Desarthe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-B%C3%A9ranger_Biscaye", Text = "Depuis Les glaciers mauves du paradis, publié chez Oswald en 1966, jusqu’à Ephémérides de Rodez, donné en 1987, Pierre-Bérenger Biscaye n’aura cessé de brosser des paysages intimes, de célébrer le paradis perdu de l’enfance.", Author = "Pierre-Béranger Biscaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Muse", Text = "Pour commencer, chantons les Muses Héliconiennes, reines de l'Hélicon, la grande et divine montagne.", Author = "Muse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diam%27s", Text = "Laisse parler les sœurs\nLaistee, laisse-les parler seuls\nIls savent pas que c'est plus textuel que sexuel\nCes vies plus sensuelles", Author = "Diam's" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gr%C3%A9goire", Text = "J'aurais aimé tenir ta main,\nUn peu plus longtemps…\nJ'aurais aimé que mon chagrin,\nNe dure qu'un instant.\nEt tu sais, j'espère au moins,\nQue tu m'entends.", Author = "Grégoire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Martin_Winckler", Text = "Un soignant n'est pas un sauveur de vies, mais quelqu'un qui aide la plupart des patients à vivre le moins mal possible. Son objectif: faire en sorte qu'on ait besoin de lui le moins possible.", Author = "Martin Winckler" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Belle_%C3%A9poque", Text = "Grand pays de bronze de la belle époque, par tes chemins en pente douce, l'inquiétude a déserté.", Author = "Belle époque" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yacouba_Konat%C3%A9", Text = "Quand la sauce est bonne, chacun plonge la main dans la soupière. Quand elle est mauvaise, elle retourne à la marmite de la cuisinière qui, le matin, la déverse sur le dépotoir. Et les poules l'éparpillent.", Author = "Yacouba Konaté" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karl_Schiller", Text = "Autant de marché que possible, autant d’État que nécessaire.", Author = "Karl Schiller" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Camara_Laye", Text = "La terre natale - quoi que l'on fasse et en dépit de la générosité ou de l'hospitalité qu'on trouve en d'autres pays - sera toujours plus qu'une simple terre: c'est toute la Terre!", Author = "Camara Laye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Allan_Bloom", Text = "La philosophie est une plante rare, qui n’a poussé qu’en Occident; peut-être même est-elle l’essence de l’Occident.", Author = "Allan Bloom" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%27Artagnan", Text = "Je ne m’amuserai point ici à vous parler de ma naissance, ni de ma jeunesse, parce que je ne trouve pas que j’en puisse rien dire qui soit digne d’être rapporté.", Author = "D'Artagnan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bintou_Chabi_Adam_Taro", Text = "Quand une femme enceinte, accouche avant les délais requis, il y a souvent de risques que le bébé ne se porte pas bien ou que cette femme, elle-même rencontre de graves difficultés.", Author = "Bintou Chabi Adam Taro" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Union_europ%C3%A9enne", Text = "Construire l'identité européenne, c'est dépasser l'identité nationale, tout en protégeant les moments de progrès civilisationnel développés par chaque nation.", Author = "Union européenne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jos%C3%A9_Manuel_Dur%C3%A3o_Barroso", Text = "Aujourd'hui, l'Europe peut proposer les principes et les règles qui modèleront un nouvel ordre mondial.", Author = "José Manuel Durão Barroso" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marguerite_Van_de_Wiele", Text = "La foi est une vertu si délicieuse à exercer que ce n’est pas trop d’en savoir gré à qui nous l’inspire.", Author = "Marguerite Van de Wiele" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karl_Deutsch", Text = "Le patriotisme s’adresse à tous les habitants d’un pays, sans tenir compte de leurs origines ethniques. Le nationalisme s’adresse à tous les membres d’un groupe ethnique, sans tenir compte du pays ou ils vivent.", Author = "Karl Deutsch" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mariam_Issoufou", Text = "Les nantis et les ministères sont sur le plateau qui domine toujours la partie populaire et déshéritée de la ville.", Author = "Mariam Issoufou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fidel_Castro", Text = "L’impérialisme sera vaincu, inévitablement. Qui nous a appris cette leçon? Ce sont les peuples qui nous l’ont apprise…", Author = "Fidel Castro" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lahiri_Mahasaya", Text = "[…] Rappelez-vous que vous n'appartenez à personne et que personne ne vous appartient. Pensez qu'un jour vous devrez soudain tout quitter en ce monde.", Author = "Lahiri Mahasaya" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Edmund_Husserl", Text = "Il est absurde de considérer la nature comme étrangère en elle-même à l'esprit et ensuite d'édifier les sciences de l'esprit sur le fondement des sciences de la nature, avec la prétention d'en faire des sciences exactes.", Author = "Edmund Husserl" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dictionnaire_des_id%C3%A9es_re%C3%A7ues", Text = "ACADÉMIE FRANÇAISE. La dénigrer mais tâcher d'en faire partie, si l'on peut.", Author = "Dictionnaire des idées reçues" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Odette_Dulac", Text = "La maternité!… Romance sans parole…", Author = "Odette Dulac" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bandit", Text = "Et toi, bandit, bandit, ah tu me tues, bandit de l'eau qui effeuilles tes couteaux dans mes yeux, tu n'as donc pitié de rien, eau rayonnante, eau lustrale que je chéris!", Author = "Bandit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Horizon", Text = "Silence. Le silence éclatant de ses rêves\nCaresse l'horizon.", Author = "Horizon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stanley_G._Weinbaum", Text = "Argent économisé, chance perdue.", Author = "Stanley G. Weinbaum" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hermann_Hesse", Text = "Tu as envie d'apprendre, Siddharta, eh bien! apprends encore cela: l'amour peut se mendier, s'acheter, se donner, se ramasser dans la rue, mais il ne se vole pas!", Author = "Hermann Hesse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Corbeau_%28film%2C_1943%29", Text = "Docteur Michel Vorzet: Je ne connais rien de plus ridicule qu’un congrès de médecins, si ce n’est un congrès de psychiatres.", Author = "Le Corbeau (film, 1943)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Confucius", Text = "Du vivant de son père, observez les intentions d'un homme. Après la mort de son père, observez son comportement: si, pendant trois ans, il ne s'écarte pas de la voie que lui a tracée son père, on peut dire que c'est un bon fils.", Author = "Confucius" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Le symptôme invariable de la science humaine est de voir du miraculeux dans les choses vulgaires.", Author = "Ralph Waldo Emerson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rudolf_Rocker", Text = "Et tout comme on employait les mots la volonté de Dieu pour justifier la volonté des castes privilégiées, de même, aujourd'hui, ne se cachent derrière la volonté de l'État que les intérêts égoïstes de ceux qui se sentent autorisés à interpréter cette volonté à leur idée pour l'imposer au peuple.", Author = "Rudolf Rocker" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Quintilien", Text = "[…] c’est le cœur, c’est la force du sentiment qui rend éloquent.", Author = "Quintilien" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Intouchables", Text = "Philippe: J'ai jamais eu les pieds aussi bien coiffés!", Author = "Intouchables" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/The_Social_Network", Text = "Sean Parker: Enlevez le the. Juste Facebook.", Author = "The Social Network" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/In%C3%A8s_Leonarduzzi", Text = "L'art donne à voir une vision du monde, une autre réalité.", Author = "Inès Leonarduzzi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Margaret_Mead", Text = "Ne doutez jamais qu'un petit groupe de citoyens engagés et réfléchis puisse changer le monde. En réalité, cela se passe toujours de cette manière.", Author = "Margaret Mead" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emma", Text = "Nous autres valétudinaires, nous nous arrogeons des privilèges!", Author = "Emma" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_Gbagbo", Text = "Nous sommes dans une conflictualité larvée et dans une bataille de positionnement stratégique qui ne dit pas son nom parce que ce positionnement répond à une volonté proactive d’exister.", Author = "Simone Gbagbo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Castex", Text = "Ce n’est pas l’Etat qui frappe, c’est le virus.", Author = "Jean Castex" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lucr%C3%A8ce", Text = "Il est doux, quand sur la grande mer les vents soulèvent les flots, d'assister de la terre aux rudes épreuves d'autrui: non que la souffrance de personne nous soit un plaisir si grand; mais voir à quels maux on échappe soi-même est chose douce.", Author = "Lucrèce" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sobdibe_Kemaye", Text = "Étant donné que la littérature orale n’est pas écrite, il est difficile de la documenter et de la préserver. Les récits peuvent être modifiés ou perdus au fil du temps, ce qui entraîne une perte irremplaçable du patrimoine culturel.", Author = "Sobdibe Kemaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Espagne", Text = "L’Espagne n’est pas un jardin, ni l’Espagnol un jardinier. L’Espagne est une planète où les roses sont des ânes pourris.", Author = "Espagne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ibrahima_Ly", Text = "L’arbre qui sait qu’il ne portera plus de fruits n’appréhende pas les jets de pierres.", Author = "Ibrahima Ly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_de_S%C3%A9vign%C3%A9", Text = "L’espérance m’a trop bien servie pour l’abandonner.", Author = "Marie de Sévigné" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cl%C3%A9mentine_Ananga_Messina", Text = "L’agriculture est l’un des piliers de l’émergence. Un pays émergeant c’est un pays qui produit, un pays qui transforme, un pays qui vend.", Author = "Clémentine Ananga Messina" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Dyson", Text = "Je pense que les choses qui fonctionnent bien commencent également à avoir une belle apparence.", Author = "James Dyson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_Dumont", Text = "La position ambiguë de notre classe ouvrière d'Europe Occidentale l'empêche de se lancer à fond contre les injustices au plan mondial, car elle en profite aussi.", Author = "René Dumont" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chantal_Safu", Text = "La parité n'est pas une donne facile, mais une conquête.", Author = "Chantal Safu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sagesse", Text = "La Prieure: Quand les sages sont au bout de leur sagesse, il convient d'écouter les enfants.", Author = "Sagesse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Agrippine_%28bande_dessin%C3%A9e%29", Text = "Agrippine: Quand j'aurai 90 ans, même si le pape en personne m'apporte des chaussons marron, c'est 2 claques direct.", Author = "Agrippine (bande dessinée)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Juliette_M%C3%A9adel", Text = "Le doute ne doit pas bénéficier aux accusés.", Author = "Juliette Méadel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/S%C3%A9v%C3%A9rine_Lawson", Text = "Le Président de la République n'est aucunement mêlé à la gestion opérationnelle du dossier. Il n'est informé que lorsque à sa demande des points lui sont faits quant à l'évolution du dossier.", Author = "Sévérine Lawson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Orgueil", Text = "[…] dans nos regards vains \nBrillent nos plans chétifs que nous croyons divins, \nNos vœux, nos passions que notre orgueil encense, \nEt notre petitesse, ivre de sa puissance; \nEt, bouffis d'ignorance ou gonflés de venin,\nNotre prunelle éclate et dit: Je suis ce nain!", Author = "Orgueil" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nutrition", Text = "On croit que la nutrition est une cause majeure dans au moins 35% des cas de cancers. Certains auteurs avancent même le chiffre de 60%. La consommation régulière et abondante de fruits et légumes apporte une protection anticancéreuse indéniable.", Author = "Nutrition" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roald_Dahl", Text = "Puis, un jour, les parents du petit James se rendirent à Londres pour faire des achats et il leur arriva une chose épouvantable. Tous deux furent dévorés, en plein jour qui plus est, dans une rue pleine de monde, par un énorme et très méchant rhinocéros échappé du jardin zoologique.", Author = "Roald Dahl" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Visiteur_du_futur", Text = "Le Visiteur: C'est un plan de Qualité, avec un Q majuscule, d'ailleurs, on a qu'à l'appeler le plan Q.", Author = "Le Visiteur du futur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_Pasteur", Text = "Souvenez-vous que dans les champs de l'observation le hasard ne favorise que les esprits préparés.", Author = "Louis Pasteur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Didon", Text = "Anna ma sœur, quelles visions nocturnes m'inquiètent et m'effraient! Quel est ce nouvel hôte entré dans nos demeures!", Author = "Didon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maigret_et_l%27Affaire_Saint-Fiacre", Text = "Je sais que la bière fait grossir et que je devrais y renoncer. Mais j'ai préféré renoncer à la coquetterie.", Author = "Maigret et l'Affaire Saint-Fiacre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Bourgault", Text = "Les Anglais en Angleterre sont unilingues anglais, les Suédois en Suède sont unilingues suédois, les Allemands en Allemagne sont unilingues allemands et les Anglais au Québec sont unilingues anglais.", Author = "Pierre Bourgault" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jacqueline_Moudeina", Text = "Il ne suffit pas d'envoyer une fille à l'école. Ça ne suffit pas de lancer des slogans comme Éduquer une fille, éduquer toute une nation. Les indicateurs sont très mauvais, une fille sur 4 passe en secondaire.", Author = "Jacqueline Moudeina" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_Schittly", Text = "Autrefois, la disparition annoncée de l'Alsacien me rendait malheureux, hargneux même, confiait-il. aujourd'hui, j'en suis à dire que si les gens ne veulent pas le parler, tant pis. C'est dommage pour eux, pas pour moi. Il ne faut rien imposer, jamais!", Author = "Louis Schittly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anaxim%C3%A8ne", Text = "De même que notre âme qui est d’air nous contient, de même le souffle et l’air enveloppent le tout de l’univers.", Author = "Anaximène" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fanny_S%C3%A8nan", Text = "Je me suis dit désormais quand on vient du Bénin, même si Serge Diesel  ou Rodolpho Tumba ne sont pas présents, on peut dire que nous avons la reine nationale et internationale ici.", Author = "Fanny Sènan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Venturini", Text = "Dans mes veines ce n’est pas du sang qui coule, c’est l’eau, l’eau amère des océans houleux…", Author = "Jean Venturini" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Guide_de_haute_montagne", Text = "Auprès de tels pèlerins, de ceux du moins qui ne se fient pas à leurs forces, un guide d’aujourd’hui a encore sa mission à remplir, la mission héritée de ses pères, et à laquelle la noblesse intacte de l’adversaire réserve toujours sa vertu.", Author = "Guide de haute montagne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Oracle", Text = "C'était l'heure la plus divine de la Grèce: celle qui fait oublier les Grecs, celle qui fait croire que les dieux ne sont pas morts.", Author = "L'Oracle" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jacques_Vach%C3%A9", Text = "J'ai successivement été un littérateur couronné, un dessinateur pornographe connu et un peintre cubiste scandaleux – Maintenant, je reste chez moi et laisse aux autres le soin d'expliquer et de discuter ma personnalité d'après celles indiquées.", Author = "Jacques Vaché" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Huiti%C3%A8me_Docteur", Text = "Le Docteur: Grace, je suis revenu à la vie devant vos yeux. J'ai vaincu la mort. Écoutez, je ne suis pas toujours en mesure de réaliser tous vos rêves, mais aujourd'hui, je le peux.", Author = "Huitième Docteur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jacques-Yves_Cousteau", Text = "Mon but n'est pas d'enseigner, je ne suis ni un scientifique ni un professeur. Je suis un découvreur, mon but est d'émerveiller. On aime ce qui nous a émerveillé, et on protège ce que l'on aime.", Author = "Jacques-Yves Cousteau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Starck", Text = "…d'un point de vue structurel, le design est totalement inutile. […] J'ai essayé de donner à mes produits un peu de sens et d'énergie. Mais même quand j'ai donné le meilleur de moi-même, c'était absurde.", Author = "Philippe Starck" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mecano", Text = "Lune tu veux être mère\nEt tu ne trouves pas l'amour\nQui te ferait femme\nDis-moi lune d'argent,\nQue prétends-tu faire\nAvec un enfant de chair,\nFils de la lune?", Author = "Mecano" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jane_Goodall", Text = "Travailler dur, saisir toutes les chances au vol et ne jamais renoncer. C'est le conseil que je donne aux jeunes qui viennent me voir, en particulier lorsqu'ils appartiennent à des communautés désavantagées.", Author = "Jane Goodall" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27As_des_as", Text = "Gabrielle Belcourt: Dans les trains, je lis des journaux écrits avec les pieds, je bavarde avec des inconnus, plus ou moins spirituels. Mais quand j'arrive à destination, je choisis avec un extrême discernement les hommes avec lesquels je mets à table. Et surtout au lit.", Author = "L'As des as" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stendhal", Text = "On voit que c'est nous qui fûmes les barbares à l'égard de l'Orient, quand nous allâmes le troubler par nos croisades. Aussi devons-nous ce qu'il y a de noble dans nos mœurs à ces croisades et aux Maures d'Espagne.", Author = "Stendhal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zara_Mahamat_Yacoub", Text = "Nous avons choisi d’être aux côtés de la population pour lui donner une information de proximité, des informations auxquelles elle tient afin de savoir tout ce qui se passe autour d’elle.", Author = "Zara Mahamat Yacoub" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yves_Rouquette", Text = "Tot un temps serem estats\nde mèstres durs.\nAviam tròp de tèrra pels pès,\nd’argent sarrat.\nViviam tròp sols tanben\nper nos mainar\nque los d’enbàs avián pas ren\nque la paur de pèrdre sa plaça.", Author = "Yves Rouquette" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Enya", Text = "Qu'il advienne qu'une étoile du soir\nFasse descendre sa lumière sur toi\nQu'il advienne, quand l'obscurité tombera,\nQue ton cœur soit intègre\nTu marches sur une route solitaire\nOh! Combien tu es loin de ta maison", Author = "Enya" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Otto_Klemperer", Text = "La musique est l’art des arts, l’art métaphysique par excellence. Là où les mots s’achèvent, commence la musique. Et où la musique s’achève-t-elle? La musique est infinie. Elle est le langage de l’âme.", Author = "Otto Klemperer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%C3%A9gende", Text = "La légende de la séduction entre Adam et Eve au paradis terrestre se continue dans notre manière de voir et dans nos lois, et donne raison au christianisme: La femme est la grande corruptrice, le vase d'élection du péché", Author = "Légende" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/International", Text = "L'international est une aberration, car inter signifie entre et entre les nations il n'y a aucune culture commune.", Author = "International" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Figures_de_style", Text = "On dit communément que les figures sont des manières de parler éloignées de celles qui sont naturelles et ordinaires, que ce sont de certains tours et de certaines façons de s'exprimer, qui s'éloignent en quelque chose de la manière commune et simple de parler.", Author = "Figures de style" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Elisabeth_Mweya_Tol%27Ande", Text = "Écrivez pendant que vous êtes jeune, n’attendez pas de vieillir.", Author = "Elisabeth Mweya Tol'Ande" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pascal_Quignard", Text = "Le seul lieu de l'espace où peuvent se rencontrer le lecteur et l'auteur est dans le point final.", Author = "Pascal Quignard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alexis_de_Tocqueville", Text = "Tous ces hommes se mirent à la file deux par deux, suivant l'ordre alphabétique; je voulus marcher au rang que m'assignait mon nom, car je savais que dans les pays et dans les temps démocratiques, il faut se faire mettre à la tête du peuple et ne pas s'y mettre soi-même.", Author = "Alexis de Tocqueville" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Cendrars", Text = "J'ai vu\nJ'ai vu les trains silencieux les trains noirs qui revenaient de l'Extrême-Orient et qui passaient en fantômes\n\nEt mon œil, comme le fanal d'arrière, court encore derrière ces trains", Author = "Blaise Cendrars" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Nouvelle-Orl%C3%A9ans", Text = "Quand je suis arrivé à la Nouvelle-Orléans, j'ai fait gaffe de ne pas m'installer dans un bordel, bien que toute la ville me parût en être un.", Author = "La Nouvelle-Orléans" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aminata_Zaaria", Text = "Je suis très sensible à l'amitié féminine. Une femme seule peut entreprendre des choses importantes mais quand elles sont deux et qu'elles sont fortes, elles sont capables de choses encore plus grandioses.", Author = "Aminata Zaaria" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joseph_Kabila", Text = "Si vous ne croyez pas à ma parole, croyez au moins à mes œuvres.", Author = "Joseph Kabila" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Danton_%28film%2C_1983%29", Text = "Danton: Si vous voulez faire de la pauvreté une vertu révolutionnaire alors confiez vos affaires à Robespierre.", Author = "Danton (film, 1983)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stefan_Wul", Text = "Si cet homme meurt, je ne regretterai pas de l'avoir perdu, je regretterai d'avoir espéré un instant qu'il existait un individu de plus joignant les trois qualités: intelligence, force et réceptivité à la chance.", Author = "Stefan Wul" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bertall", Text = "Qui se rappelle les éclats de rire provoqués par l'exhumation de quelques vieux chapeaux de nos grand'mères retrouvés dans des armoires oubliées.Le temps est-il bien loin où ce qui nous paraît séduisant, au moment actuel, nous semblera peut-être avoir atteint les dernières limites du ridicule?", Author = "Bertall" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Toulou_Kiki", Text = "Je suis née au Niger dans un tout petit village appelé Tchirozérine, au nord d’Agadez. Mon père travaillait dans l’usine de charbon locale. Ma mère m’a eue à 14 ans, puis elle a enchainé huit grossesses.", Author = "Toulou Kiki" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Elisabeth_Diouf", Text = "Elle est une personnalité d’exception, symbole comme nous le savons de la discrétion, de la solidarité qu’on a toujours connu avec elle et du partage.", Author = "Elisabeth Diouf" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_%28ap%C3%B4tre%29", Text = "Ces choses ont été écrites afin que vous croyiez que Jésus est le Christ, le Fils de Dieu, et qu'en croyant vous ayez la vie en son nom.", Author = "Jean (apôtre)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roger_Judrin", Text = "Le culte du tragique est un chatouillement nécessaire aux âmes flasques. Leur angoisse ne s'attendrit pas.", Author = "Roger Judrin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Muir", Text = "Chacun d'entre nous a besoin de beauté comme de pain, de places pour jouer et de lieux de prière, d'endroits où la nature puisse le guérir et se réjouir, et le fortifier dans son corps et son âme.", Author = "John Muir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fabrice_Melquiot", Text = "Daddi Rotondo: Notre nid tomba de sa branche.", Author = "Fabrice Melquiot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89lisabeth_Badinter", Text = "Si la masculinité s'apprend et se construit, nul doute qu'elle peut changer. Au XVIIIe siècle, un homme digne de ce nom pouvait pleurer en public et avoir des vapeurs; à la fin du XIXe, il ne peut plus sous peine d'y laisser sa dignité masculine.", Author = "Élisabeth Badinter" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chris_Hedges", Text = "Il est impossible à l’intérieur du système de braver les exigences de Wall Street, l’industrie des combustibles fossiles ou les profiteurs de guerres. La seule voie qui nous reste, comme Aristote le savait, c’est la révolte.", Author = "Chris Hedges" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Henry", Text = "Ce qui se sent sans que ce soit par l'intermédiaire d'un sens est dans son essence affectivité.", Author = "Michel Henry" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_d%27Agoult", Text = "Démocratie, fière démocratie, prépare à ton foyer une place pour des hôtes insolents, venus de loin; voici le cortège de l'empire qui passe!", Author = "Marie d'Agoult" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9colonisation", Text = "La seconde blessure de la décolonisation, pour nous peut-être la plus grave, c’est le sentiment de l’injustice. Nous avons l’impression que nous sommes trahis et reniés, que nous sommes victimes d’une ingratitude parce que nous avons apporté beaucoup de bien.", Author = "Décolonisation" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sanzy_Viany", Text = "Chaque jour pour moi est un jour nouveau pour pouvoir me faire connaître par un Camerounais de plus.", Author = "Sanzy Viany" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diane_von_F%C3%BCrstenberg", Text = "Ce n'est pas que je suis arrogante, mais avec l'âge, on acquiert une certaine sagesse", Author = "Diane von Fürstenberg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Keiichi_Hara", Text = "Il existe encore des animateurs de très grand talent, mais ils ne sont pas très nombreux. Ceux qui ont travaillé sur le film ont quasiment tous entre 40 et 50 ans… Il me semble que ce secteur est vraiment en danger.", Author = "Keiichi Hara" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Quand_passent_les_faisans", Text = "Hyacinthe Camus: Je peux tout demander à mon cerveau, sauf de s'arrêter de penser.", Author = "Quand passent les faisans" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatima_Daas", Text = "Je porte mon attention exclusivement sur les femmes.\nJe me sens obligée de jouer à la justicière, de défendre les autres, de parler à leur place, de porter leurs paroles, de les rassurer, de les sauver.", Author = "Fatima Daas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pablo_Neruda", Text = "Je ne viens rien solutionner.\nJe suis venu ici chanter, je suis venu\nafin que tu chantes avec moi.", Author = "Pablo Neruda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ada_Osakwe", Text = "Les gouvernements doivent faire un bien meilleur travail en tant que facilitateurs d'entreprises et ne pas être un obstacle pour les PME, qui, comme nous le savons tous, sont les moteurs de la croissance et de l'emploi dans toute économie.", Author = "Ada Osakwe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Lefebvre", Text = "La majorité ne fait pas la vérité, c’est la vérité qui doit faire la majorité.", Author = "Marcel Lefebvre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bijou_Mushitu_Kat", Text = "Voir ce genre de forum se multiplier car la femme congolaise doit être préparée à participer en toute conscience à la vie politique.", Author = "Bijou Mushitu Kat" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gassin", Text = "Sur une hauteur, un bourg ramassé autour de son  église au clocher trapu. C'est Gassin. Nous allons tantôt entre deux murs de roc roux, tantôt entre de sveltes roseaux.", Author = "Gassin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatou_Ke%C3%AFta", Text = "Plus tu leur en donneras, et plus ils en voudront.", Author = "Fatou Keïta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Indira_Gandhi", Text = "Je ne suis pas assez modeste pour dire que je serais incapable de gouverner, mais je ne suis pas vaniteuse au point d'affirmer que d'autres ne pourraient pas remplir cette tâche.", Author = "Indira Gandhi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arnaldur_Indri%C3%B0ason", Text = "Quand quelqu'un disparaît en Islande, c'est pour toujours. Il n'y a jamais personne qui revienne des dizaines d'années plus tard.", Author = "Arnaldur Indriðason" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fortune", Text = "Adieu, mon cher et bon ami; si je croyais que la fortune pût vous rendre heureux, je vous dirais: Courez à la fortune; mais peut-être avez-vous raison de la dédaigner avec tant de trésors pour vous passer d'elle; j'aime mieux vous dire: Courez à la félicité, c'est la fortune du sage.", Author = "Fortune" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Adama_Saidou", Text = "La ponctualité, c’est important, surtout lorsqu’on est médecin.", Author = "Adama Saidou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Purisme", Text = "Les mots aujourd’hui sont devenus ce semble les objets de notre principale attention, l’imbécille purisme domine par-tout; on s’arrête à des mots, lorsqu’il n’est question que des choses.", Author = "Purisme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yaya_Mbil%C3%A9_Bitang", Text = "Je ne m'inspire pas du texte, je joue le texte tel quel, en réalité.", Author = "Yaya Mbilé Bitang" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Georges-Louis_Leclerc_de_Buffon", Text = "C'est par des expériences fines, raisonnées et suivies, que l'on force la nature à découvrir son secret; toutes les autres méthodes n'ont jamais réussi... Les recueils d'expériences et d'observations sont donc les seuls livres qui puissent augmenter nos connaissances.", Author = "Georges-Louis Leclerc de Buffon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Larry_Tremblay", Text = "Les choses ne font jamais leur temps, les vivants sont toujours plus lents que les morts.", Author = "Larry Tremblay" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Rochefort", Text = "C’est  Harold Pinter, cet ami Nobel, compagnon du whisky, qui, dans son théâtre et dans sa vie, écrivait ou disait souvent: ‘’Ce genre de choses’’.", Author = "Jean Rochefort" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Delphine_Ernotte", Text = "On a une télévision d'hommes blancs de plus de 50 ans, et ça, il va falloir que cela change.", Author = "Delphine Ernotte" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89lizabeth_Tchoungui", Text = "Ne vous laissez pas terrasser par la malveillance de ceux qui ne voient pas plus loin que leur ombre.", Author = "Élizabeth Tchoungui" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dragon", Text = "Mais déjà, droit sur eux, le dragon vigilant tendait son cou démesuré, dès qu'il les vit venir de loin de ses yeux toujours en éveil.", Author = "Dragon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Luis_Sep%C3%BAlveda", Text = "Vivre et laisser vivre, telle était sa devise.", Author = "Luis Sepúlveda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Immoraliste", Text = "Je ne suis ni triste, ni gai; l'air d'ici vous emplit d'une exhaltation très vague et vous fait connaître un état qui paraît aussi loin de la gaieté que de la peine; peut-être que c'est le bonheur.", Author = "L'Immoraliste" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gabriel_Faur%C3%A9", Text = "Pour moi, l’art, la musique surtout consiste à nous élever le plus loin possible au-dessus de ce qui est.", Author = "Gabriel Fauré" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lydia_Guirous", Text = "Un enfance kabyle, comment pourrais-je vous décrire une enfance kabyle? La Kabylie ne se raconte pas, on la vit, on la sent, on la touche, on la frôle, on la désire. Elle est un mélange de rêves et d'illusions.", Author = "Lydia Guirous" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vertige", Text = "Qu’est-ce qui force l’homme à ouvrir les yeux sinon le besoin de vertige?", Author = "Vertige" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ma_part_du_g%C3%A2teau", Text = "Mr. Brown: Les affaires se font toujours contre les autres. Ce n'est pas un sport pour les gens bien.", Author = "Ma part du gâteau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Crime_de_l%27Orient-Express_%28film%2C_2017%29", Text = "Hercule Poirot: Pourquoi les poules pondent les œufs de taille différentes?", Author = "Le Crime de l'Orient-Express (film, 2017)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eug%C3%A9nie_Musayidire", Text = "Les peintures expriment des aspects du génocide comme la trahison des proches, la négligence de l’Église et des dirigeants de la communauté, ainsi que des problèmes liés aux horreurs qui ont frappé la population locale.", Author = "Eugénie Musayidire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yasmina_Reza", Text = "De toute façon vous l'inventerez. Les écrivains ont en commun avec les tyrans de plier le monde à leur désir.", Author = "Yasmina Reza" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Florence_Muleka_Bajikila", Text = "Chaque pas que je fais construit la femme que je deviens", Author = "Florence Muleka Bajikila" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jardinier", Text = "Le jardinage est la passion, belle bête de jardinier.", Author = "Jardinier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Diff%C3%A9rence_invisible", Text = "Florian: Il y a apéro chez mes potes ce soir, hein! Tu te souviens?\nMarguerite: Oui. Mais je ne resterai pas longtemps.\nFlorian: Et voilà, tu vas encore être la première à partir. C'est vraiment pas drôle pour moi, tu sais...\nMarguerite: Pour moi non plus.", Author = "La Différence invisible" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Bourgeon", Text = "Agnès: Puisque tu ne sembles rien ignorer de mon anatomie, il eût été mesquin de te présenter mon couteau revêtu de sa gaine!", Author = "François Bourgeon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bruit", Text = "Le bruit, c’est la vie! Le silence, c’est la mort!", Author = "Bruit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maryse_Jaspard", Text = "L'acceptation de pratiques pour faire plaisir est du domaine de la négociation et des arrangements conjugaux.", Author = "Maryse Jaspard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Haman_Adama", Text = "Écoutez, pour l'instant, il n'y a aucune élection en vue. Tout ce que je sais, c'est que j'apporte ma contribution à la construction et au dynamisme de mon parti, le Rdpc. Le reste appartient à Dieu , personne ne peut le prédire maintenant.", Author = "Haman Adama" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Souleymane_Ciss%C3%A9", Text = "Ma façon de vivre, c’est de croire en l’avenir; si j’étais fataliste, je ne serais pas cinéaste. Rien ne me poussait à faire du cinéma. C’est moi qui l’ai choisi. Je voulais voir les choses et les faire voir. Quand on a cette curiosité, on ne peut pas être fataliste.", Author = "Souleymane Cissé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Julie_de_Lespinasse", Text = "Ah! Je suis bien malheureuse: ce que j'aime, ce qui me console, met mon âme à la torture par le trouble et les remords.", Author = "Julie de Lespinasse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Franchise", Text = "Dans la jungle, de lui-même l’explorateur se rit des pièges à loup dissimulés derrière les broussailles intimes. D’un saut, il franchit le fossé entre ce qui a été et ce qui, selon ses rêves, eût dû être. Il y a excès plutôt que défaut de franchise.", Author = "Franchise" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Pelot", Text = "On dit... on dit... on dit...\nOn dit que la Terre tourne.\n\nEt ça c'est vrai.", Author = "Pierre Pelot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coffi_Codjia", Text = "Si j’avais connu ce qui est en train d’être fait en ce moment, je crois que j’aurais pu arbitrer une finale de Coupe du Monde. Nous allons vers le professionnalisme… Les arbitres de football auront un salaire…S’il plaît à Dieu, la VAR viendra dans notre football.", Author = "Coffi Codjia" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatou_Bensouda", Text = "Les femmes ne recevront pas la justice qu'elles méritent. Les hommes pensaient qu'ils avaient le droit de battre les femmes, mais j'ai toujours pensé que cela ne devrait pas arriver.", Author = "Fatou Bensouda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Goldfinger", Text = "Des mots d'or il versera à ton oreille\nMais ses mensonges ne peuvent déguiser ce que tu crains\nCar une fille en or sait qu'il l'a embrassée\nC'est le baiser de la mort que donne\nMister Goldfinger", Author = "Goldfinger" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Patrick_S%C3%BCskind", Text = "Dans son immobilité, il avait l'air d'être son propre inventaire.", Author = "Patrick Süskind" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hubert_V%C3%A9drine", Text = "C'est tout cet universalisme occidental à la fois bien pensant, bien intentionné, hégémonique, paternaliste et sûr de lui, bouffi d'irréalisme et embrumé d'irrealpolitik, qui s'est heurté aux réalités.", Author = "Hubert Védrine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gabriel_Matzneff", Text = "S'appuyer sur un philosophe décrié, citer un poète tombé dans l'oubli, faire l'éloge d'un théologien dont personne ne sait le nom, c'est publier qu'on se sent en communion avec eux, transmettre la flamme, opérer une résurrection.", Author = "Gabriel Matzneff" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Adam_Smith", Text = "Quand nous visitons les palais des grands, nous ne pouvons nous empêcher de concevoir la satisfaction qui serait la nôtre si nous en étions nous-mêmes propriétaires et si nous disposions d’une demeure si habilement et si ingénieusement conçue.", Author = "Adam Smith" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Odome_Angone", Text = "Il n’y a pas de sujet frivole ni trivial, nous sommes les emboîtements d'un macro-récit. Les problématiques identitaires liées aux métaphores de l'imaginaire qui traversent le tissu social mais que l'on se pose en littérature ne sont pas que des questions de fiction.", Author = "Odome Angone" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nayanka_Bell", Text = "On ne choisit pas ses parents, \nsi on choisissait ses parents,\nsi on choisissait ses parents,\nchacun allait se choisir les meilleurs.", Author = "Nayanka Bell" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Petit_Nicolas_%28film%29", Text = "Nicolas: En fait, je sais pourquoi je ne sais pas ce que je veux faire plus tard. C'est parce que ma vie elle est chouette et je ne veux surtout pas qu'elle change!", Author = "Le Petit Nicolas (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cognos", Text = "Cognos s'est aperçu que le temps entre les interactions était l'indicateur clé du pic d'intérêt. Si le temps entre deux interactions dépasse 10 jours, la possibilité de  transformer cet intérêt d'achat chute dramatiquement.", Author = "Cognos" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Brian_May", Text = "Nous allons te (ou vous) secouer", Author = "Brian May" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rencontre", Text = "Le grand artiste gravit une pente vierge et, arrivé au sommet, au détour d'une corniche battue par les vents, qui croyez-vous qu'il rencontre? Le lecteur haletant et heureux. Tous deux tombent spontanément dans les bras l'un de l'autre et demeurent unis à jamais si le livre vit à jamais.", Author = "Rencontre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Laurent_Gbagbo", Text = "Je n’exclus rien. Je suis un homme politique. Je n’exclus rien.", Author = "Laurent Gbagbo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Salom%C3%A9_Saqu%C3%A9", Text = "Tous les journalistes doivent parler de la crise climatique. Ce n'est pas que l'affaire des spécialistes. Ça doit devenir notre boussole.", Author = "Salomé Saqué" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89ric_Plamondon", Text = "Le meilleur moyen d'être le premier, c'est d'être le premier dans une certaine catégorie. Le meilleur moyen d'être premier dans une certaine catégorie, c'est d'inventer la catégorie.", Author = "Éric Plamondon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniel_Pennac", Text = "Ce que je vois dans les yeux de la cliente, maintenant, ne me surprend pas. Je l'y vois, elle. Il a suffi que je me mette à pleurer pour qu'elle prenne ma place. Compassion. [...] Machine arrière toute. Elle retire sa plainte.", Author = "Daniel Pennac" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Paulo_Coelho", Text = "Qu'est-ce qu'un guerrier de la lumière?\nTu le sais. C'est celui qui est capable de comprendre le miracle de la vie, de lutter jusqu'au bout pour ce en quoi il croit, et - alors - d'entendre les cloches que la mer fait retentir dans ses profondeurs.", Author = "Paulo Coelho" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alain_Connes", Text = "Il me semble important de dépasser le domaine particulier de la biologie pour étudier le cerveau. Pour ce faire, les mathématiques fournissent un terrain beaucoup plus propice que d'autres. Parce qu'elles sont absolues, universelles, et donc indépendantes de toute influence culturelle.", Author = "Alain Connes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jo%C3%ABlle_Ecormier", Text = "Le Grand Tamarinier touche sans couler et s'affiche avant tout comme un conte philosophique profondément optimiste", Author = "Joëlle Ecormier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Friedrich_Wilhelm_Joseph_von_Schelling", Text = "L’alpha et l’oméga de toute philosophie est la liberté.", Author = "Friedrich Wilhelm Joseph von Schelling" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/A%C3%AFchatou_Kan%C3%A9_Boulama", Text = "J'ai une responsabilité envers les femmes qui se sont senties  valorisées par ma nomination, je sais qu'elles attendent beaucoup de moi. JE veux leur dire de se mobiliser pour que nous réussissons ensemble!", Author = "Aïchatou Kané Boulama" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mouftaou_Adoun", Text = "Je me battrai dur pour gagner ma place de titulaire et pour faire parler de moi dans ce championnat.", Author = "Mouftaou Adoun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hypatie", Text = "Le vil Galiléen t'a frappée et maudite,\nMais tu tombas plus grande! Et maintenant, hélas!\nLe souffle de Platon et le corps d'Aphrodite\nSont partis à jamais pour les beaux cieux d'Hellas!", Author = "Hypatie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fight_Club", Text = "Pendant un long moment pourtant, Tyler et moi avons été les meilleurs amis du monde. Les gens n'arrêtent pas de me demander: est ce que j'étais au courant pour Tyler Durden?", Author = "Fight Club" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Suffrage_universel", Text = "Qu'est-ce que le suffrage universel? C'est l'élection du père par les enfants.", Author = "Suffrage universel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Robin_Cook", Text = "Ce qui importe, c'est d'observer, d'exister, et d'exploiter les situations concrètes telles qu'elles se présentent.", Author = "Robin Cook" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Olivia_Tapiero", Text = "À l’extérieur, quand les animaux se croisent, ils gardent une distance. Ils se regardent, ils se reconnaissent puis passent leur chemin. Cet écart est sans doute le premier poème du monde, un poème oublié depuis longtemps.", Author = "Olivia Tapiero" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yvette_Chassagne", Text = "Je vous en prie, monsieur, je vous appellerai donc madame.", Author = "Yvette Chassagne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/V%C3%A9turie", Text = "Pour moi, je maudirais volontiers Veturia pour l'orgueil qu'elle a donné aux femmes.", Author = "Véturie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Juan_Lorenzo_Holmann_Chamorro", Text = "Aujourd'hui, nous n'existons plus pour le Nicaragua, ma carte d'identité, mon permis de conduire ont été annulés, nous avons été rayés de tous les registres.", Author = "Juan Lorenzo Holmann Chamorro" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nadine_Labaki", Text = "Je n'ai pas peur de mes émotions, je ne suis pas dans la retenue", Author = "Nadine Labaki" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fred_Jones", Text = "Fred:  Dans un cas comme celui-ci, Sammy et Scooby ont fait exactement ce qu'il fallait.  Partons!", Author = "Fred Jones" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hugo_Schuchardt", Text = "Il n'y a pas de langue totalement pure.", Author = "Hugo Schuchardt" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chinelo_Okparanta", Text = "sous les branches de l'udala. Nous devons apprendre à jeûner pour chasser la colère .", Author = "Chinelo Okparanta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89ric_Chevillard", Text = "Parfois même le dromadaire se trompe et il encule une chamelle, on l'a vu.", Author = "Éric Chevillard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hinda_D%C3%A9by_Itno", Text = "Le cancer tue plus que le SIDA, le paludisme et la tuberculose réunis, mais il figure parmi les maladies orphelines et puisqu’on en parle à peine, il continue de faire des victimes.", Author = "Hinda Déby Itno" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Open_data", Text = "L'information détenue par le gouvernement fédéral est un bien national.", Author = "Open data" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/H%C3%A9l%C3%A8ne_Dorion", Text = "Mes forêts sont de longues traînées de temps\nElles sont des aiguilles qui percent la terre\ndéchirent le ciel\navec les étoiles qui tombent", Author = "Hélène Dorion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mari%C3%A8me_Faye_Sall", Text = "C’est ce que je fais actuellement avec ma fondation, mes actions caritatives et en m’occupant de mes enfants; ce qui n’est pas une mince affaire. Je vous assure que cela remplit amplement mes journées. Je n’ai pas le temps pour l’oisiveté ni pour l’ennui..", Author = "Marième Faye Sall" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diaka_Sidib%C3%A9", Text = "Nous voulons construire un lendemain meilleur pour la Guinée à travers l’éducation des femmes.", Author = "Diaka Sidibé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bernadette_Gl%C3%A9hou%C3%A9nou-Dossou", Text = "Là où l’homme a réussi la femme le peut également.", Author = "Bernadette Gléhouénou-Dossou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ahmadou_Kourouma", Text = "La vie est au pouvoir d’Allah seul!", Author = "Ahmadou Kourouma" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Paola_Audrey_Ndengue", Text = "Il faut clairement avoir une capacité de s’adapter, de se réinventer même quand c’est nécessaire. Du coup ça demande de ne pas rester sur ses acquis..", Author = "Paola Audrey Ndengue" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Valery_Larbaud", Text = "Les liaisons commencent dans le champagne et finissent dans la camomille.", Author = "Valery Larbaud" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coumba_Dieng_Sow", Text = "Le Covid-19 ne pouvait arriver à un pire moment pour les communautés vulnérables de l'Afrique de l'Ouest.", Author = "Coumba Dieng Sow" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Adolf_Hitler", Text = "L'époque arabe fut l'âge d'or de l'Espagne la plus civilisée. Puis vint l'époque des persécutions toujours recommencées.", Author = "Adolf Hitler" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Friedrich_Flick", Text = "Pour lui l'économie c'est M. Flick, M. Stinnes, M. Krupp et M. Thyssen.", Author = "Friedrich Flick" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yann_Le_Cun", Text = "Avant de nous inquiéter du contrôle d’une IA super-intelligente, nous devons avoir le début d’un aperçu d’un système plus intelligent qu’un chat domestique.", Author = "Yann Le Cun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hamlet", Text = "Hamlet: Il y a plus de choses sur la terre et dans le ciel, Horatio, qu’il n’en est rêvé dans votre philosophie.", Author = "Hamlet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/M%C3%A9dia", Text = "Quand la guerre a éclaté j’avais onze ans. Tous les matins, avant de me diriger vers l’école, je lisais le journal de bout en bout – dans mon milieu nous n’avions pas la radio: l’avoir était considéré comme gauchiste, subversif", Author = "Média" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Orelsan", Text = "J'ai peur d'me griller les ailes à vouloir briller sous les projecteurs", Author = "Orelsan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Edna_O%27Brien", Text = "Il me semble avoir vu les choses avant de les vraiment vues; elles ont toujours été là, comme les mots, je crois, ont toujours été là, filant à travers nous.", Author = "Edna O'Brien" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Argent_%28couleur%29", Text = "Un flamboyant été de roses se consumait en parfums. L’immense baie des fenêtres découvrait la mer qui miroitait toute sous nos yeux éblouis, ruissellement d’argent fondu et parsemé de cristal.", Author = "Argent (couleur)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Martine_de_Bertereau", Text = "Il y eut autrefois des femmes non seulement belliqueuses et habiles aux armes, mais encore doctes aux arts, et sciences spéculatives.", Author = "Martine de Bertereau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Gregg_Sulzberger", Text = "J'ai dit franchement au président que je pensais que son discours n'était pas seulement facteur de division mais qu'il était de plus en plus dangereux. Je l'ai prévenu que ce langage incendiaire contribuait à une augmentation des menaces contre les journalistes et allait inciter à la violence.", Author = "Arthur Gregg Sulzberger" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Beau", Text = "Le merveilleux est beau, n'importe quel merveilleux est beau, il n'y a que le merveilleux qui soit beau.", Author = "Beau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Denys_de_La_Patelli%C3%A8re", Text = "François Gensac: Je vais mourir pour la fécondation du désert!... Demain sur les tombeaux, les blés seront plus beaux - comme dit le poète... Mon nom va devenir une marque. Une marque d'engrais. Le colonialisme est en pleine évolution!...", Author = "Denys de La Patellière" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Genre", Text = "Le genre masculin, étant le plus noble, doit prédominer toutes les fois que le masculin et le féminin se trouvent ensemble; mais l'oreille a de la peine à s'y accommoder, parce qu'elle n'a point accoustumé de l'oüir dire de cette façon…", Author = "Genre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rosalind_Franklin", Text = "La science et la vie quotidienne ne peuvent et ne doivent pas être séparées.", Author = "Rosalind Franklin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabel_Machik_Ruth_Tshombe", Text = "Sereine, rigoureuse et droite dans mes bottes, je le reste. Dommage pour une note mouillée d’acide et réputée officielle muée en un secret de polichinelle sur la toile! Est-ce fortuit? Savoir dire non à une forfaiture à un prix et je le paie. Rendez-vous à Kin, il n y aura pas d’honneur perdu!", Author = "Isabel Machik Ruth Tshombe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Richard_Bona", Text = "Dans les musiques traditionnelles du Cameroun la basse a une place très importante. Si le bassiste n'est pas là, les concerts ne commencent pas! La place de cette basse s'est répercutée dans les musiques modernes à travers les pionniers: Vicky Edimo, Jean Ekoto...", Author = "Richard Bona" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Florbela_Malaquias", Text = "Je dis que l’humanité est un tout et que si nous nous unissons et nous connectons pour développer, propager et renforcer les principes humanistes, l’humanité gagnera.", Author = "Florbela Malaquias" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Theresa_May", Text = "Je veux que la Grande-Bretagne soit la grande méritocratie du monde – un pays où chacun a une chance équitable d’aller aussi loin que son talent et son travail acharné le permettent.", Author = "Theresa May" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fredrik_Reinfeldt", Text = "Dans certaines parties du monde, le réchauffement de la planète va se traduire par des pénuries d'eau, la sécheresse et des déserts de plus en plus grands. Dans d'autres parties, il y aura de plus en plus de pluies, de tempêtes et d'inondations.", Author = "Fredrik Reinfeldt" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bineta_Diop", Text = "En incluant les femmes, l'Afrique va accélérer son développement.", Author = "Bineta Diop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ingrid_Astier", Text = "Soudain le ciel sème sa nuit et le regard s’ouvre à l’infini – beauté de l’astronomie.", Author = "Ingrid Astier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bertille_Marcos_Gu%C3%A8d%C3%A8gb%C3%A9", Text = "Mon ambition est de donner de la visibilité à ce que je fais et montrer que lorsqu’on est dans un domaine, on peut voir plus loin.", Author = "Bertille Marcos Guèdègbé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eben_Moglen", Text = "Nous avons besoin d'une FreedomBox pour protéger notre vie privée. Sans anonymat, l'espèce humaine deviendra une machine.", Author = "Eben Moglen" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bourkou_Louise_Ngaradoumri", Text = "L'exil m'a beaucoup formé et m'a rendu aussi mure et sage c'est un devoir pour moi de répondre à cet appel c'est cet atout que je voudrais partager avec le peuple tchadien.", Author = "Bourkou Louise Ngaradoumri" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Quinault", Text = "Atys: Qui n’a plus qu’un moment à vivre,\nN’a plus rien à dissimuler.", Author = "Philippe Quinault" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mama_B%C3%A9a", Text = "J'veux tout savoir de toi d'où tu viens où tu vas, qui tu es\nLes choses de ta vie, tes amours tes amis tes regrets\nJ'promets que j'rirai pas que j'ferai rien je rest'rai sans bouger\nJ'écoute bien tu verras, tu seras plus jamais l'étranger", Author = "Mama Béa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amina_Mama", Text = "La plus grande menace pour les femmes (et par extension pour l'humanité) est la croissance et l'acceptation d'une culture de militarisme misogyne, autoritaire et violente.", Author = "Amina Mama" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Seigneur_des_anneaux_%3A_La_Communaut%C3%A9_de_l%27anneau", Text = "Galadriel: I amar prestar aen... Le monde a changé... Han mathon ne nen... Je le vois dans l’eau... Han mathon ne chae... Je le ressens dans la terre... Han noston ned 'wilith... Je le sens dans l’air...", Author = "Le Seigneur des anneaux : La Communauté de l'anneau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lous_and_the_Yakuza", Text = "En Afrique, on est très spirituels: ici, si on parle de dieu, on dirait qu’on fait un affront. Même les catholiques ont peur de dire qu’ils le sont. La France et la Belgique sont les rares pays d’Europe à avoir un discours sur le voile.", Author = "Lous and the Yakuza" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Or_Mbongo", Text = "Ma mission sous ce soleil est de faire en sorte que ceux qui ne connaissent pas Dieu viennent vers Jesus. Moi je ne peux pas me laisser gagner.", Author = "L'Or Mbongo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Individu", Text = "A l'avenir, les individus qui sortiront du lot seront ceux qui maîtriseront les compétences technologiques ainsi que les aptitudes relationnelles directes.", Author = "Individu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/En_plein_d%C3%A9lire_scolaire", Text = "L'enseignement est une chose trop sérieuse pour être confiée à des incapables qui, perdant de vue le but recherché, accumulent sans sourciller les mesures absurdes, incohérentes et contradictoires dont ils sont bien les seuls à ignorer les effets pernicieux.", Author = "En plein délire scolaire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Elie", Text = "Un logiciel libre est gratuit, quand on l'a payé une fois.", Author = "François Elie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Martine_Ntumba_Bukasa", Text = "Je suis entrée en politique pour lutter contre l’injustice", Author = "Martine Ntumba Bukasa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aristippe_de_Cyr%C3%A8ne", Text = "[I]l y a une voie intermédiaire, que je m’efforce de suivre, et qui ne passe ni par le pouvoir, ni par l’esclavage, mais par la liberté, qui est la voie la plus sûre vers le bonheur.", Author = "Aristippe de Cyrène" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/N%C3%A9lie_Jacquemart", Text = "J’espère que j’aurai Chaalis, c’est mon plus vif désir. [...] un lieu de repos et d’activité, cela est bon et sain car je ne suis qu’une pierre roulante.", Author = "Nélie Jacquemart" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Claire_Simon", Text = "J'ai continué à essayer de faire venir des réalisateurs africains ou nord-africains, des enfants d'immigrés, des documentaristes, et c'était toujours un combat. Mais j'ai fini par gagner.", Author = "Claire Simon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Myst%C3%A9rieuse_Affaire_de_Styles", Text = "Imaginez notre stupeur quand , il y a trois mois, elle nous a annoncé ses fiançailles avec son Alfred! Cet individu a au moins vingt ans de moins qu'elle! C'est du maquereautage ostensible. Mais que voulez-vous, mère n'en fait qu'à sa tête et elle l'a épousé.", Author = "La Mystérieuse Affaire de Styles" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jules_Renard", Text = "Un mot si joli qu'on le voudrait avec des joues, pour l'embrasser.", Author = "Jules Renard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Margot_Wallstr%C3%B6m", Text = "C'est comme ça qu'on change le monde: en étant très, très pragmatique. Je refuse de m'engager dans toutes ces discussions théoriques sur les définitions. Je suis convaincue qu'il faut que ce soit un outil pratique.", Author = "Margot Wallström" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Koffi_Olomid%C3%A9", Text = "Même la feuille qui tombe d'un arbre connaît sa destination.", Author = "Koffi Olomidé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Art%C3%A9mis", Text = "Nous chantons Artémis - malheur à qui, chantant, l'oublie - Artémis, qui aime l'arc et les chasses, et les chœurs nombreux, et les jeux sur la montagne.", Author = "Artémis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%96d%C3%B6n_von_Horv%C3%A1th", Text = "Rien ne donne autant le sentiment de l'infinitude que la bêtise.", Author = "Ödön von Horváth" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Grande_Loge_f%C3%A9minine_de_France", Text = "La prostitution, c’est tout le contraire de la liberté des femmes pour laquelle nous nous battons.", Author = "Grande Loge féminine de France" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_de_Beauvoir", Text = "Se vouloir libre, c'est aussi vouloir les autres libres", Author = "Simone de Beauvoir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_IX_de_France", Text = "Ni cette perte, ni autre quelconque, ne saurait me séparer de la fidélité que je dois à mon Dieu.", Author = "Louis IX de France" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Liste_de_proverbes", Text = "Ânesse le jour, femme la nuit.", Author = "Liste de proverbes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Service_de_renseignement", Text = "Le renseignement est l'enfer de l'incertitude de la ruse, un poison qu'on croit distiller aux autres mais qui vous infecte aussi, qui poisse les mains et le cœur, qui détruit la beauté et la majesté du verbe. La qualité de ce qu'on donne se mesure au mot près.", Author = "Service de renseignement" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pl%C3%A9biscite", Text = "Le plébiscite n'est qu'une mécanique à faire dire oui et le référendum est un remède négatif parce que, s'il peut s'opposer à une mesure exécrable, son rôle n'est point d'en enfanter de salutaire.", Author = "Plébiscite" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kitia_Tour%C3%A9", Text = "Le chasseur reconnait toujours la taille du gibier qu’il suit à la grandeur de l’empreinte que l’animal laisse dans la boue.", Author = "Kitia Touré" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Imre_Kert%C3%A9sz", Text = "Et je suis resté dépouillé, les mains vides. Je me suis retrouvé face à mon cauchemar immatériel et informe: le temps. Il tendait vers moi sa bouche bêtement béante, et je n'avais rien à lui fourrer dans le gosier.", Author = "Imre Kertész" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabelle_de_Charri%C3%A8re", Text = "On préfère la prison, la honte, le fond de la mer à la pauvreté, et jamais la Déesse Fortune ne reçut tant de vœux ni de sacrifices.", Author = "Isabelle de Charrière" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Audre_Lorde", Text = "La licorne noire est rétive\nla licorne noire est intraitable\nla licorne noire n’est pas\nlibre.", Author = "Audre Lorde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Star_Trek_%3A_G%C3%A9n%C3%A9rations", Text = "Dr. Tolian Soran: Ne commencez-vous pas à sentir le temps qui vous rattrape? Il est semblable à un prédateur. Il vous pourchasse. Oh, vous pouvez essayer de le distancer avec des médecins, des médicaments, de nouvelles technologies, mais à la fin, le temps va vous rattraper et vous tuer.", Author = "Star Trek : Générations" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rania_El-Mashat", Text = "C'est en donnant des moyens au secteur privé qu'il sera possible d'atteindre ce niveau en termes de création d'emplois et d'impact économique général.", Author = "Rania El-Mashat" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jim_Harrison", Text = "La poésie n’est pas une obsession, mais une vocation. C’est une rivière dans laquelle tu sautes dès qu’on t’y appelle et tu passes ta vie à flotter au gré du courant.", Author = "Jim Harrison" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christine_Arnothy", Text = "La moralité est faite pour les pauvres, pour mieux les tenir.", Author = "Christine Arnothy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89checs", Text = "On ne peut pas se permettre, à haut niveau, d’avoir des pensées parasites. Quand tu joues, ton univers doit se limiter exclusivement à ces 64 cases. Si l’adversaire gagne, c’est que tu t’es toi-même perdue.", Author = "Échecs" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sylvain_Bemba", Text = "Quand un chien menace deux enfants, on les voit utiliser leur peur comme bouclier pour unir leurs faiblesses en un ultime rempart.", Author = "Sylvain Bemba" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Komi_Koutch%C3%A9", Text = "La contestation est une vertu de la démocratie.", Author = "Komi Koutché" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sosth%C3%A8ne_L%C3%A9opold_Bayemi_Matjei", Text = "Nous savons combien la corruption cause de dégâts dans notre société, et l’Église ne peut rester insensible à ce qui blesse l’être humain.", Author = "Sosthène Léopold Bayemi Matjei" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pi%C3%A8ce", Text = "Avez-vous la monnaie de ma pièce? Personne au monde ne peut avoir la monnaie de ma pièce.", Author = "Pièce" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Aventures_de_Petit_Jules_et_P%C3%A9p%C3%A9_Jules", Text = "La propreté est la mère de toutes les vertus. […] Si tu as les mains sales, tâche qu'elles soient propres! Ça se voit moins!", Author = "Les Aventures de Petit Jules et Pépé Jules" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9j%C3%A0_vu_%28film%2C_2006%29", Text = "Durant toute ma carrière, j'ai essayé d'attraper des gens après qu'ils aient fait quelque chose d'horrible. J'aimerais, pour une fois dans ma vie, attraper quelqu'un avant qu'il ne fasse quelque chose d'horrible.", Author = "Déjà vu (film, 2006)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Judith_Gautier", Text = "Car le soleil des jours de printemps réchauffe beaucoup moins qu’il n’éclaire, et les retours de froidures sont les plus sensibles au corps, comme le reproche de celui qu’on croyait ami blesse le cœur plus douloureusement.", Author = "Judith Gautier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bijoux_Goya_Kitenge", Text = "travailler pour promouvoir une alternative politique plus respectueuse de la démocratie et des libertés individuelles", Author = "Bijoux Goya Kitenge" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeanne_d%27Arc_Jutras", Text = "Misérabilisme et homosexualité féminine, sacres et gémissements: rien de plus pour François Hébert.", Author = "Jeanne d'Arc Jutras" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ambrose_Bierce", Text = "Abstinent: personne faible qui cède à la tentation de se refuser un plaisir.", Author = "Ambrose Bierce" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeanne-Marie_Leprince_de_Beaumont", Text = "On se corrige de l’orgueil, de la colère, de la gourmandise et de la paresse: mais c’est une espèce de miracle que la conversion d’un cœur méchant et envieux.", Author = "Jeanne-Marie Leprince de Beaumont" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cyprien_%28film%29", Text = "Shabbat shalom les pédés! C'est kascher chez vous?", Author = "Cyprien (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Delphine_Zanga_Tsogo", Text = "Je pense que si la femme n'est pas leader politique, ici, c'est qu'à un moment donné on a relégué les femmes au domaine social et qu'elles n'ont pas été encouragées à se lancer dans la politique pure.", Author = "Delphine Zanga Tsogo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Simpson", Text = "Homer: Oh, c'est pas vrai! Y'a combien de classes dans cette satanée école?", Author = "Les Simpson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "[Karl Marx est] un esprit d'une nature dissolvante, d'un caractère dominateur, sans fortes croyances philosophiques ou religieuses, et inspiré par des haines plutôt que par l'amour.", Author = "Giuseppe Mazzini" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Agnes_Binagwaho", Text = "Toute vie est précieuse, mais le début est magique.", Author = "Agnes Binagwaho" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lorraine_Lokoka", Text = "On a bien géré défensivement, surtout en défense contre Diaby qu'on a bien contrôlé. C'était important de gagner après le match catastrophique de Landerneau. On se relance bien avant la trêve. C'est encourageant.", Author = "Lorraine Lokoka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nathalie_Fortain", Text = "Je suis arrivée là par hasard. Depuis l'âge de 7 ans, je faisais de la vitesse et de la hauteur. Personne ne voulait s'atteler à la compétition marche athlétique. Je l'ai fait et j'ai gagné. Après, il a bien fallu que je m'entraîne!", Author = "Nathalie Fortain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gold_%28groupe%29", Text = "Un peu plus près des étoiles\nAu jardin de lumière et d'argent\nPour oublier les rivages brûlants\nUn peu plus près des étoiles\nA l'abri des colères du vent\nÀ peine un peu plus libres qu'avant", Author = "Gold (groupe)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zerocalcare", Text = "L'identité c'est ce qui n'est qu'à toi.\nEt la seule chose qui n'appartient qu'à toi, ce sont tes secrets.\n\nUn homme sans aucun secret est un homme sans identité.", Author = "Zerocalcare" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89cole_buissonni%C3%A8re", Text = "La classe est sur les plus hautes branches du retour, entre les verdiers et les brûlures. C'est l'école buissonnière dans toute son acception.", Author = "École buissonnière" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wiyaala", Text = "Si les gens disent que les Blancs apprécient ma musique plus que les miens, cela signifie qu’il y a quelque chose qui ne va pas chez mon propre peuple.", Author = "Wiyaala" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kidi_Bebey", Text = "Quand on est enfant, on ne fait pas forcément attention à la couleur de la peau, mais aux signes de pouvoir et on veut devenir comme celui qui l’a pour pouvoir donner des ordres aux autres pendant que l’on se pavane.", Author = "Kidi Bebey" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Len%C3%A9ru", Text = "Je ne veux plus écrire que contre la guerre. Ce qui ne veut pas dire, mon filleul, que je ne trouve pas très bien de faire celle-ci. Je suis fille, petite-fille, arrière-petite-fille de soldats, mais je ne veux plus que même un luxe moral nous coûte aussi cher.", Author = "Marie Lenéru" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pauline_Croze", Text = "T'es beau,\nT'es beau parce que t'es courageux,\nDe regarder dans le fond des yeux,\nCelui qui te défie d'être heureux.", Author = "Pauline Croze" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Berthe_Sylva", Text = "C'est aujourd'hui dimanche.\nTiens, ma jolie maman,\nVoici des roses blanches,\nQue ton cœur aime tant\nVa, quand je serai grand\nJ'achèt'rai au marchand\nToutes ses roses blanches\nPour toi, jolie maman....", Author = "Berthe Sylva" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/OuLiPo", Text = "Le changement de genre littéraire peut prendre la forme d'une amplification (…) ou d'une réduction: alors c'est l'exemple du Cid réduit à un sonnet par G. Fourest. On pourrait encore le concentrer en le réduisant à son dernier vers:\nQu'il est joli garçon l'assassin de papa!", Author = "OuLiPo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Entrepreneur", Text = "L'entrepreneur paye au fermier un prix certain pour ses denrées afin d'en tirer sur le marché en ville un prix incertain; ce dernier doit permettre le défraiement des frais de transport et laisser à l'entrepreneur un profit pour son entreprise.", Author = "Entrepreneur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Salvador_Allende", Text = "L’histoire est à nous et ce sont les peuples qui la font.", Author = "Salvador Allende" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Animal_que_donc_je_suis", Text = "Sous sa forme phénoménale la plus massive, de la chasse à la corrida, des mythologies aux abattoirs, et sauf exception, c’est le mâle qui s’en prend à l’animal, comme c’est Adam que Dieu a chargé d’asseoir son autorité sur les bêtes.", Author = "L'Animal que donc je suis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Felicia_Impastato", Text = "Etudiez, car en étudiant vous ouvrez votre tête et vous comprenez ce qui est bien et ce qui ne l'est pas", Author = "Felicia Impastato" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karin_Michaelis", Text = "J’avais besoin de vivre seule. Toute seule, pour moi, avec moi.", Author = "Karin Michaelis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sophia_Myles", Text = "Madame de Pompadour: C'est la coutume, je pense, de n'avoir d'ami imaginaire que durant l'enfance. Il faut vous féliciter pour votre persévérance.", Author = "Sophia Myles" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Wyndham", Text = "Il est surprenant de voir resurgir ce qui nous a jamais quittés, lorsqu'on est mis à l'épreuve.", Author = "John Wyndham" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andrew_Coburn", Text = "Un homme patient évite les erreurs.", Author = "Andrew Coburn" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christian_Corouge", Text = "Je crois que c'est Taylor qui disait ça, que si on pouvait mettre des bœufs à la place d'un ouvrier, on les y mettrait.", Author = "Christian Corouge" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Colette_Jeannine_Minka", Text = "Être prête à partager son expérience et être ravie de servir de modèle pour les jeunes générations qui veulent devenir les femmes d’affaires accomplies.", Author = "Colette Jeannine Minka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Akiko_Yosano", Text = "Rideau de la nuit\nOù s'épuisent les murmures\nDans les étoiles\nTandis qu'ici-bas les hommes\nOnt les cheveux en broussaille", Author = "Akiko Yosano" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jules_Bessan", Text = "Il faut que les nouveaux qui vont venir après moi, travaillent pour améliorer mes performances car, après Rio, j'arrête.", Author = "Jules Bessan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maudits_soupirs_pour_une_autre_fois", Text = "Le temps c’est pas une faux qu'il a, c'est une sorte de louche et une marmite monstre, il fout tout dedans, il bascule, il s'amuse à tritouiller ça marmelade obscène, que tout se mélange confond s'embarbouille englue...", Author = "Maudits soupirs pour une autre fois" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tania_Mokolo_Ndjoli", Text = "À chaque montée des eaux du fleuve Congo, le territoire de Mankanza, ma circonscription électorale, a toujours été victime d’inondations qui exacerbent les conditions de vie déjà difficiles de la population, d’autant plus que 70% des villages et campements sont naturellement marécageux.", Author = "Tania Mokolo Ndjoli" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alexandra_Kollonta%C3%AF", Text = "La séparation de la cuisine et du mariage a été aussi importante que celle de l’Église et de l’État.", Author = "Alexandra Kollontaï" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/M%C3%A9d%C3%A9e_%28mythologie%29", Text = "Et je n'approuve pas le citoyen à l'humeur insolente\nqui blesse les siens en dédaignant de les comprendre.", Author = "Médée (mythologie)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_Nzuzi_wa_Mbombo", Text = "Si le salut de la femme requiert la collaboration des hommes, il ne peut s’opérer effectivement qu’au moyen d’actions conscientes et volontaires des femmes elles-mêmes.", Author = "Catherine Nzuzi wa Mbombo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Pagnol", Text = "Je suis né dans la ville d’Aubagne, sous le Garlaban couronné de chèvres, au temps des derniers chevriers.", Author = "Marcel Pagnol" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eug%C3%A8ne_Huzar", Text = "La science fait l’industriel, et à son tour l’industriel fait le savant […]. C’est de cette action et de cette réaction réciproques que naît le progrès.", Author = "Eugène Huzar" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Victor_Bouadjio", Text = "Tout garçon vivant dans le giron maternel repousse chaque jour l’âge de sa maturité.", Author = "Victor Bouadjio" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Walid_Mouallem", Text = "S’en prendre à la Syrie n’est pas une mince affaire. Nous avons deux options: soit nous rendre, soit nous défendre avec les moyens dont nous disposons. La seconde solution est la meilleure: nous nous défendrons.", Author = "Walid Mouallem" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sahle-Work_Zewde", Text = "Si l’histoire de l’Afrique était écrite par des Africains et pardes femmes, je pense que nous découvririons de nombreux héros méconnus.", Author = "Sahle-Work Zewde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Joyce", Text = "Comme mon cœur battait tandis qu'il revenait vers moi au pas de course à travers le champ! Il courait comme s'il avait dû me porter secours. Et je fus tout contrit; car au fond de moi je l'avais toujours un peu méprisé.", Author = "James Joyce" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marilyn_Douala_Bell", Text = "Pour exposer l'art contemporain en Afrique, il faut savoir être seigneur ou guerrier: se battre chaque jour pour rappeler que ce qui peut paraître superflu, sur un continent qui a bien d'autres priorités, relève en fait de l'essentiel.", Author = "Marilyn Douala Bell" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-Claver_Ilboudo", Text = "L'expertise acquise empiriquement, c'est bien, (...) mais rien ne vaut le diplôme, car il confère la crédibilité, un atout fondamental dont notre société naissante a besoin pour s'affirmer dans la jungle des affaires.", Author = "Pierre-Claver Ilboudo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chantal_Yelu_Mulop", Text = "Donnez-nous seulement les infrastructures et nous ferons le reste.", Author = "Chantal Yelu Mulop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gabriel_Garc%C3%ADa_M%C3%A1rquez", Text = "Bien des années plus tard, face au peloton d'exécution, le colonel Aureliano Buendia devait se rappeler ce lointain après-midi au cours duquel son père l'avait emmené découvrir la glace.", Author = "Gabriel García Márquez" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Robert_et_Robert", Text = "À New York, tous les taxis sont jaunes... Comme le mien!", Author = "Robert et Robert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alice_Delphine_Tang", Text = "Le social camerounais exerce une forte pression sur le roman qui émerge dans ce pays, notamment sur le roman féminin.", Author = "Alice Delphine Tang" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeanne_de_Cavally", Text = "On a l’impression que la plante des pieds, cuite, va se détacher et rester collée dans le sable, tandis que le cerveau, dans la tête, est en train de bouillir.", Author = "Jeanne de Cavally" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/H%C3%A9lie_de_Saint_Marc", Text = "Je me répétais: Si on doit un jour ne plus comprendre comment un homme a pu donner sa vie pour quelque chose qui le dépasse, ce sera fini de tout un monde, peut-être de toute une civilisation.", Author = "Hélie de Saint Marc" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Corps_de_mon_ennemi", Text = "Pendant qu'une saine jeunesse agite des calicots, elle ne brandit pas de pancarte.", Author = "Le Corps de mon ennemi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/H%C3%A9l%C3%A8ne_Ou%C3%A9draogo_Daross", Text = "Je suis une enfant de la terre des hommes noirs, je suis née fatiguée, j’ai vécu fatiguée et je ne souhaite pas mourir fatiguée.", Author = "Hélène Ouédraogo Daross" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Beno%C3%AEt_Poelvoorde", Text = "Rien n'est plus hypocrite que le visage de l'acteur qui n'a pas remporté le César, applaudissant à s'en rompre les mains parce qu'il passe à la télé.", Author = "Benoît Poelvoorde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%82me", Text = "Cette simplicité de l'âme, nous consacrons notre vie à l'acquérir, ou à la retrouver si nous l'avons connue, car c'est un don de l'enfance qui le plus souvent ne survit pas à l'enfance… il faut très longtemps souffrir pour y rentrer, comme tout au bout de la nuit on découvre une autre aurore…", Author = "Âme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Shoah", Text = "Plusieurs se demandaient pourquoi ils avaient survécu alors que leur frère, leur sœur ou leurs parents n'étaient pas revenus. La survie tenait à la chance, à la résistance physique, ou à une protection inespérée.", Author = "Shoah" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cavalerie", Text = "Annibal dut à ses Numides ses principales victoires. Scipion, ayant conquis l'Espagne et fait alliance avec Masinissa, ôta aux Carthaginois cette supériorité. Ce fut la cavalerie numide qui gagna la bataille de Zama, et finit la guerre.", Author = "Cavalerie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cebio_Soukou", Text = "En fin de compte, cela ne convenait plus et cela n'avait aucun sens pour l'une ou l'autre des parties de prolonger le contrat. Puis, après deux merveilleuses années, vous vous séparez et voyez où les choses vont ensuite.", Author = "Cebio Soukou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Schizophr%C3%A9nie", Text = "La psychose réussie permet de voir s'estomper la menace suicidaire grâce à la reconstruction psychique délirante dressant un rempart solide contre l'effondrement mélancolique.", Author = "Schizophrénie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/B%C3%A9nabar", Text = "Tout ce que j'en conclus: je dois pas être un poète,\nc'est qu'ça doit être chiant, très chiant d'être une mouette.", Author = "Bénabar" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Omar_Khayyam", Text = "J'ai lancé contre une pierre un bol cette nuit;\nL'acte brutal, j'étais ivre quand je l'ai commis;\nLe bol m'a dit en son langage de bol:\nJ'ai été ce que tu es! tu seras toi aussi ce que je suis!", Author = "Omar Khayyam" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hugo_von_Hofmannsthal", Text = "Le vent de printemps court\nDans les allées désertes,\nD'étranges choses passent\nAvec lui dans un souffle.", Author = "Hugo von Hofmannsthal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chantal_Chambu_Mwavita", Text = "Face aux violations graves des droits humains occasionnées par les conflits qui sévissent dans la partie est du pays et face aux défis financiers et sécuritaires, les autorités congolaises n’ont ni capitulé ni rangé les outils de protection des droits humains", Author = "Chantal Chambu Mwavita" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/B%C3%A9r%C3%A9nice_%28princesse_de_Jud%C3%A9e%29", Text = "Bérénice: Nous séparer? Qui? Moi?\nTitus de Bérénice?", Author = "Bérénice (princesse de Judée)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Martin_Peltier", Text = "Pour avoir un maximum d'influence aujourd'hui, il faut tenir l'histoire.", Author = "Martin Peltier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amalasonte", Text = "Bienheureuse es-tu, ma souveraine, dont la gloire est multiple; pour toi la bienfaisance divine supprime tout besoin de combattre, car soit par un bonheur céleste tu fais fuir les adversaires de la République, soit par ta générosité naturelle tu les rallies à ton empire.", Author = "Amalasonte" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/August_Macke", Text = "Les idées insaisissables se manifestent sous des formes saisissables. Saisissables grâce à nos sens en tant qu’étoile, tonnerre, fleur, en tant que forme.", Author = "August Macke" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Pascot", Text = "Annoncer que plus de 25% minimum des députés et 30% des sénateurs prennent plus que souvent des libertés avec la probité, l'éthique et la morale et/ou ont affaire à la justice, ferait très mauvais effet dans la presse nationale, voire internationale.", Author = "Philippe Pascot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Prestige", Text = "Robert Angier: Jamais je ne pensais trouver une réponse au fond d'un verre de bière.\nCutter: Cela ne vous a pas empêché de chercher.", Author = "Le Prestige" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Victoire_Laly", Text = "J’ai toujours eu l’espoir que la vie s’améliorerait à un moment donné et aujourd’hui, grâce à ces expériences, je suis une femme forte, sûre d’elle et résiliente.", Author = "Victoire Laly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marina_Abramovi%C4%87", Text = "Il y a deux mois j’ai failli mourir. Ça a été un véritable choc en repensant à tout ce que j’avais pu faire auparavant. Je lavais des squelettes, je déambulais avec des squelettes, je transportais des squelettes-sans compter mes propres funérailles…", Author = "Marina Abramović" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bandy_Kiki", Text = "Début 2017, alors que les troubles politiques s’intensifiaient dans les régions anglophones du Cameroun, mes opinions en tant que blogueur sur les crises ont fini par faire de moi un objet de critiques publiques et d’intimidation sur Internet.", Author = "Bandy Kiki" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Orgueil_et_Pr%C3%A9jug%C3%A9s_%28film%2C_1940%29", Text = "Mary Bennet: Lui avez-vous dit que vous aviez cinq filles, Papa?\nMr. Bennet: Eh bien, je lui ai dit que s'il rencontrait cinq des filles les plus idiotes d'Angleterre, ça devrait être mes filles!", Author = "Orgueil et Préjugés (film, 1940)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Porte_%C3%A9troite", Text = "Il n'y a pas de qualité si plaisante de la jeunesse qui ne puisse, à vieillir, se gâter.", Author = "La Porte étroite" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joseph_Ponthus", Text = "Parce qu'aujourd'hui c'est plus officiellement des prolétaires: c’est des illettrés et des sans-dent.", Author = "Joseph Ponthus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ir%C3%A8ne_Joliot-Curie", Text = "Il y avait des questions sur lesquelles ma mère avait des opinions d’une intransigeance absolue. Par exemple, elle estimait que les femmes devaient avoir les mêmes droits, et d’ailleurs les mêmes devoirs que les hommes.", Author = "Irène Joliot-Curie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Terrorisme", Text = "D'autres pays engagent des terroristes, mais nous, nous engageons des États terroristes. Nous sommes un grand pays!", Author = "Terrorisme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Florence_Tsagu%C3%A9_Assopgoum", Text = "La culture c'est quelque chose de vital qui nous donne des repères, nous lie avec les autres, avec le passé, nous façonne de façon implicite et explicite.", Author = "Florence Tsagué Assopgoum" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/N%C3%A9ron", Text = "Qualis artifex pereo! (Quel grand artiste périt avec moi!)", Author = "Néron" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Insolente_Veggie", Text = "Ce qu'on veut, c’est que ce soit interdit de faire du mal aux animaux.", Author = "Insolente Veggie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dora_Decca", Text = "Les enfants de la rue, quand ils trouvent une mère, c’est une vraie mère.", Author = "Dora Decca" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/P%C3%A9dagogie_Montessori", Text = "on retrouve dans le système du Dr Decroly tous les moyens que préconise Mme Montessori, mais sa méthode reste trop souvent verbale, abstraite; elle laisse très peu de temps en somme aux exercices qui mettent l'enfant en contact avec la belle réalité.", Author = "Pédagogie Montessori" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emily_Dickinson", Text = "Où j'ai perdu, je marche plus doucement \nJe sème de tendres fleurs du jardin\nJe m'arrête au-dessus de la tête absente\nEt je la pleure. \n\nQui j'ai perdu, pieusement je le protège\nD'un accent rude, ou d'un mot cruel\nCar je sens que son oreiller entend\nÀ travers la pierre!", Author = "Emily Dickinson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89mile_Faguet", Text = "Deux états sociaux ruinent l'idée ou plutôt le sentiment de la patrie: la vie politique trop violente, et la vie politique nulle.", Author = "Émile Faguet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Annette_Mbaye_d%E2%80%99Erneville", Text = "En ce qui concerne la polygamie, je la conçois lorsqu'elle est acceptée par amour, lorsque la femme, consciente, organise elle-même sa vie conjugale, sans contrainte. Finalement, c'est une affaire toute personnelle que ni les décrets ni les manifestes ne feront disparaître.", Author = "Annette Mbaye d’Erneville" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Louise_Et%C3%A9ki-Otabela", Text = "Des années 40 à nos jours il y a des femmes extraordinaires dans tous les domaines d’activités au Cameroun; ce que l’on a appelé les femmes émancipées… Bien avant nos mères, nos grand-mères ont organisées des rébellions de femmes contre l’ordre social patriarcal.", Author = "Marie Louise Etéki-Otabela" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Casablanca_%28film%29", Text = "Je ne me mouille pour personne", Author = "Casablanca (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Classicisme", Text = "Le classique, parce qu'il accepte la société dans laquelle il est né, s'efforce de la peindre avec vérité et tend à s'effacer derrière ses personnages.", Author = "Classicisme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Georges_Duby", Text = "Il arrive que l'historien découvre inopinément beaucoup de ce qu'il cherche lorsqu'il sort de sa chambre et regarde autour de lui. […] Ce que je cherchais dans mes courses à travers les champs et les bois, c'était une bonne prise, concrète, sur le réel.", Author = "Georges Duby" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rahmatou_Seck_Samb", Text = "La mort, comme un vautour, a fondu sur sa proie, délice de nos vies, et nous l’a ravie pour toujours.", Author = "Rahmatou Seck Samb" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Aventures_de_Rabbi_Jacob", Text = "Ça alors! C’était Farès? C’est effarant!", Author = "Les Aventures de Rabbi Jacob" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louisa_May_Alcott", Text = "J’ai souvent le sentiment que je vendrais volontiers mon âme à Satan en échange d’une année de liberté.", Author = "Louisa May Alcott" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marais", Text = "Les grands marais phosphorescents font de jolis rêves et les crocodiles se reprennent la valise faite avec leur peau.", Author = "Marais" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ron_Howard", Text = "Nous avons voulu en parler de façon réaliste et sérieuse. Et nous nous sommes dit que plus nous serions honnêtes, plus les rires seraient élevés. C'est une façon de faire remonter la pression.", Author = "Ron Howard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Claude_Ptol%C3%A9m%C3%A9e", Text = "La géographie est la représentation par le dessin de la partie connue de la terre dans sa totalité.", Author = "Claude Ptolémée" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dobermann", Text = "Inspecteur Sauveur Cristini: Ils ont tous des têtes de camés, ça s'défonce, ça s'flingue ... c'est la mode, avec moi tout ces bouffons y s'raient déjà morts.", Author = "Dobermann" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89milie_Flore_Faignond", Text = "Regardez les plantes hybrides comment elles sont belles. Le métissage, il est beau d'abord dans la culture.", Author = "Émilie Flore Faignond" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89lizabeth_Bourgine", Text = "J’aimais lire, lire tout, le jour, le soir, en marchant pour aller à l’école, lire du théâtre, et puis le cinéma, les comédies musicales, le théâtre et l’Opéra de Rennes..", Author = "Élizabeth Bourgine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-Emmanuel_Barr%C3%A9", Text = "Je m'appelle Pierre-Emmanuel. J'aime les fleurs et la sodomie. Ne faites pas les timides, hein, quand deux hommes se sentent seuls, c'est parfois très agréable d'aller se promener en forêt.", Author = "Pierre-Emmanuel Barré" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois-Auguste_Mignet", Text = "Rien n'est plus propre à refaire un homme que de vivre au clair soleil, parler provençal, manger de la brandade et faire tous les matins une partie de boules.", Author = "François-Auguste Mignet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fanatisme", Text = "Le fanatisme, voyez-vous, (…) c'est la dernière révolte du pauvre, la seule qu'on n'ose lui refuser. Elle le fait brailler le dimanche mais baster la semaine, et il y a ici des gens qui s'en arrangent. Bien des choses iraient mieux s'il y avait moins de ventres creux.", Author = "Fanatisme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roger_Caillois", Text = "Roger Caillois était un écrivain français de premier rang […] \nEt il pensait si fort et si vite qu'il lui arrivait de bégayer.", Author = "Roger Caillois" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ar%C3%A8s", Text = "Zeus Père, n'es-tu donc pas indigné, quand tu vois toutes ces horreurs? Sans cesse les dieux que nous sommes subissent les pires tourments, cela les uns par les autres, pour plaire aux mortels.", Author = "Arès" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/M%C3%A9pris", Text = "[L]es hommes sont ainsi faits qu’ils méprisent ceux qui les ménagent et qu’ils respectent ceux qui ne leur concèdent rien.", Author = "Mépris" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Roi_lion", Text = "Oh! J’ai jamais le droit d’aller nulle part.", Author = "Le Roi lion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nisreen_Elsaim", Text = "J'étudiais la physique, parce que j'étais persuadée que la science pouvait changer le monde, mais je me suis aperçue que si les scientifiques n'étaient pas ceux qui prenaient les décisions, il serait vraiment difficile de faire des progrès.", Author = "Nisreen Elsaim" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Autre_c%27est_moi", Text = "Where is Brian? [...] et toi comme un idiot tu répondais sagement: Brian is in the kitchen", Author = "L'Autre c'est moi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alfred_Elton_van_Vogt", Text = "Dans leur rage et leur désir de puissance, des hommes suivent des chefs dont les idées sont aussi confuses que les leurs propres.", Author = "Alfred Elton van Vogt" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Farida_Nabourema", Text = "Abdiquer serait trahir les générations à venir, nous sommes résolus à ne jamais faiblir. Pour un Togo libre et prospère, nous nous battons, car c’est notre devoir sacré, notre ultime mission.", Author = "Farida Nabourema" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Julie_Andrews", Text = "Madame était sûre que j'étais capable de chanter Mozart et Rossini, mais, pour être honnête, je ne l'ai jamais été.", Author = "Julie Andrews" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/B%C3%A9atrice_Kindja_Mwendanga", Text = "Les postes de prise des décision ne sont pas seulement dans le domaine politique", Author = "Béatrice Kindja Mwendanga" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Monique_Bessomo", Text = "Si comme toi, crier je pouvais \nDans le vent et à haute voix \nEn exprimant mon abîme avec joie \nÀ tous mes semblables je dirais:\nTrop, trop, c'est trop, c'est trop \nQue de cruauté dans le cœur des humains! \nQue de pauvreté sur les bords des chemins!", Author = "Monique Bessomo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Astou_N%27Diaye", Text = "Chers frères et sœurs il faut finir le lycée au moins et sachez que sport et études vont de pair ici et il n’y a pas d’autre moyens.", Author = "Astou N'Diaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cesare_Battisti", Text = "Je n’ai jamais été victime d’une injustice et j’ai mené en bateau tous ceux qui m’ont aidé. À certains d'entre eux, il ne fallait même pas mentir.", Author = "Cesare Battisti" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Georges-Adrien_Crapelet", Text = "On l'a dit avec raison: un livre sans faute est une chimère aussi rare que les centaures et les hippogriphes; […]", Author = "Georges-Adrien Crapelet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Charles_Benoist", Text = "N'importe qui étant bon à n'importe quoi, on peut, n'importe quand, le mettre n'importe où.", Author = "Charles Benoist" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fantastique", Text = "Le fantastique n'est fantastique que par rapport à une réalité normale: sa force est de contraste et d'invraisemblance. Mais pour que l'invraisemblable ait du relief, il doit se détacher d'un contexte vraisemblable.", Author = "Fantastique" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Elias_Canetti", Text = "Il n'est rien que l'homme redoute davantage que le contact de l'inconnu.", Author = "Elias Canetti" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniel_Woodrell", Text = "La chambre noire où chacun cèle ses véritables convictions, ses plus secrets désirs, possède la porte la mieux scellée du monde.", Author = "Daniel Woodrell" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Peste_%28roman%29", Text = "Andy Warhol avait tort. Dans l'avenir, les gens n'auront pas droit à un quart d'heure de célébrité. Non,  dans l'avenir, tout le monde sera assis au moins un quart d'heure a côté de quelqu'un de célèbre.", Author = "Peste (roman)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne-Marie_Albiach", Text = "parlant il augmente les obscurcissements\nqu'il rénove", Author = "Anne-Marie Albiach" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anvers", Text = "Bruxelles se fait passer, bien à tort, pour une capitale. La vraie capitale serait Anvers, si une capitale pouvait être un simple centre de commerce.", Author = "Anvers" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuelle_Devos", Text = "Je ne suis pas dans le contrôle. Ce n'est pas parce que j'ai picolé et dansé que l'on va me découvrir autrement. Je ne me censure pas", Author = "Emmanuelle Devos" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Samira_Wiley", Text = "Je suis noire, je suis gay, je suis une femme. Mon pays me déteste.", Author = "Samira Wiley" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maurice_Blanchot", Text = "[…] mourir non pas personnellement, mais par l’intermédiaire de tous les autres.", Author = "Maurice Blanchot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jonathan_Swift", Text = "Les caprices de l'espèce femelle ne sont pas limités à une seule partie du monde ni à un seul climat, [ils] sont bien plus généraux qu'on ne pourrait l'imaginer.", Author = "Jonathan Swift" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Abdoulaye_Sadji", Text = "Le monde n'était jamais en équilibre, sa fin approchait à en juger par la dépravation des moeurs, le manque de vergogne de la femme et la lâcheté des hommes.", Author = "Abdoulaye Sadji" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wladimir_Porch%C3%A9", Text = "Que grâce à la radio-télévision, Genève ne soit plus séparée de Melbourne, cela ne signifie-t-il pas qu’à chaque instant, chaque habitant de Melbourne peut immédiatement, s’il le désire, participer à la vie de Genève?", Author = "Wladimir Porché" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuel_Todd", Text = "La contribution principale de la France à l'histoire de l'humanité est justement d'avoir fait échapper la démocratie à sa gangue ethnique originelle et défini un corps de citoyens sans référence aux notions de race ou de sang.", Author = "Emmanuel Todd" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Peter_Thiel", Text = "Les entreprises transcendent le pouvoir. Si elles ferment, le marché boursier s'effondre. Si le gouvernement ferme, rien n'arrive, et nous continuons à avancer, parce que cela n'a pas d'importance. La paralysie du gouvernement est en réalité bonne pour nous tous.", Author = "Peter Thiel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alexandre_le_Grand", Text = "Alors que ses compagnons lui demandaient s'il voulait concourir à Olympie pour l'épreuve du stade, car il était agile, il répondit: Oui, à condition d'avoir des rois pour adversaires.", Author = "Alexandre le Grand" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Olivia_Yac%C3%A9", Text = "<<Notre présence compte, et nos voix doivent être entendues.>>", Author = "Olivia Yacé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christine_Kafando", Text = "Les compétences que nous avons acquises doivent servir de modèle pour les nouvelles générations.", Author = "Christine Kafando" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yvonne_Vera", Text = "Il lui tardait profondément que le silence fût complet. Il lui tardait d'échapper aux cris insistants de triomphe de cet homme. Ce silence n'était pas de l'oubli, mais un commencement.", Author = "Yvonne Vera" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Face_aux_feux_du_soleil", Text = "Première Loi: Un robot ne peut porter atteinte à un être humain ni, restant passif, laisser cet être humain exposé au danger.", Author = "Face aux feux du soleil" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniel_de_Roulet", Text = "Dans ma génération helvétique, ni moi ni tant d'autres n'avons été des militants jusqu'au-boutistes. Dans un pays étouffé par sa propre guerre froide, nous n'avons été que des militants intermittents.", Author = "Daniel de Roulet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Linagora", Text = "Les sociétés apprécient de plus en plus le modèle tarifaire courant des logiciels libres, qui consiste à payer non pas selon le nombre d'utilisateurs d'un logiciel mais en fonction du service que l'on attend de l'application.", Author = "Linagora" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Reza_Aslan", Text = "Mahomet n'a jamais prétendu créer une nouvelle religion. le message de Mahomet était une tentative de réformer des croyances religieuses et des pratiques culturelles de l’Arabie pré-islamique afin de convertir les peuples arabes au Dieu des juifs et chrétiens.", Author = "Reza Aslan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aoua_Ke%C3%AFta", Text = "La mère poule ne donne jamais de mauvaises choses aux poussins. Elle trie la terre, saisit et essaie d'abord tout ce quelle découvre avant de le placer devant les poussins.", Author = "Aoua Keïta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anita_Ekberg", Text = "Brando peut sans problème ressembler à un tonneau de vin.", Author = "Anita Ekberg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yasmina_Sandoz", Text = "L’idée est d’avoir une bibliothèque à l’image du monde, et pas uniquement représentative de la culture de l’homme blanc occidental.", Author = "Yasmina Sandoz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yasmine_Motarjemi", Text = "Si les employés n'ont pas le temps de faire leur travail, s'ils sont en sous effectif, s'ils n'ont pas l'expertise ou pire, s'ils n'ont pas d'éthique ou si la direction soutient une telle situation...un jour, les failles s'alignent et vous allez avoir un incident.", Author = "Yasmine Motarjemi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/R%C3%A9gis_Debray", Text = "Entre une pratique sans tête et une théorie sans jambes, il n'y aura jamais à choisir.", Author = "Régis Debray" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mbarka_Bouaida", Text = "Il faut savoir que de toutes les façons le continent est énorme, qu'un collectionneur nigérian sera d'abord intéressé par un artiste nigérian, qu'un Tunisien préférera un artiste tunisien. L'idée d'une collection panafricaine est plus un concept européen ou américain.", Author = "Mbarka Bouaida" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wandiswa_Ntengento", Text = "Les réseaux sociaux ont rendu l'information plus accessible au public et ont mis les organes de presse sous pression pour diffuser les nouvelles plus rapidement qu'auparavant.", Author = "Wandiswa Ntengento" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Guillaume", Text = "M. Kopp a fait voir que, si l'accroissement indéfini des richesses est une chimère, parce que la quantité de matière est limitée par la nature, il est cependant possible d'accroître le bien-être général, sans augmenter la somme des richesses, en en accélérant la circulation.", Author = "James Guillaume" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_Weil", Text = "Le mot de révolution est un mot pour lequel on tue, pour lequel on meurt, pour lequel on envoie les masses populaires à la mort, mais qui n'a aucun contenu.", Author = "Simone Weil" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marl%C3%A8ne_Canguio", Text = "Tokyo, c'était la liberté.", Author = "Marlène Canguio" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Magicien_d%27Oz", Text = "Dorothée vivait au milieu des grandes plaines du Kansas, avec Oncle Henri, qui était fermier, et Tante Em, qui était la femme du fermier.", Author = "Le Magicien d'Oz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Macaque", Text = "Un macaque chéri, jeune mais blasé, grave\n﻿Comme au Sénat le Président,\nCrève, plein d’insolence, & du bout de la dent,\n﻿La peau jaune d’une goyave.", Author = "Macaque" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Boubou_Hama", Text = "La langue de la femme est celle de la vipère. Elle est venimeuse.", Author = "Boubou Hama" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Djami", Text = "De toutes les compositions des gens de lettres, il n'y en a pas de plus séduisantes que celles où respire le charme de l'amour.", Author = "Djami" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mongo_B%C3%A9ti", Text = "Il est difficile de concevoir une humanité aussi méprisable autrement que marchant rapidement vers un destin moins féroce, traversant fébrilement la nuit pour déboucher sur la clarté âcrée du jour.", Author = "Mongo Béti" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Carole_Agito_Amela", Text = "L'action dont je suis et serai toujours fière, aujourd'hui et demain, c'est de servir loyalement le pays", Author = "Carole Agito Amela" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sue_Gardner", Text = "Les projets de Wikimédia attirent plus de 500 millions de visiteurs uniques chaque mois dans le monde.", Author = "Sue Gardner" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aim%C3%A9_C%C3%A9saire", Text = "Partir. Mon cœur bruissait de générosités emphatiques. Partir... j'arriverais lisse et jeune dans ce \npays mien et je dirais à ce pays dont le limon entre dans la composition de ma chair: J'ai longtemps \n\nerré et je reviens vers la hideur désertée de vos plaies.", Author = "Aimé Césaire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/F%C3%A9odalit%C3%A9", Text = "Ce fut dans la poussière des archives seigneuriales que je découvris les affreux mystères des usurpations de la caste noble.", Author = "Féodalité" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bon_sens", Text = "Le bon sens est la chose du monde la mieux partagée: car chacun pense en être si bien pourvu, que ceux même qui sont les plus difficiles à contenter en toute autre chose, n'ont point coutume d'en désirer plus qu'ils en ont.", Author = "Bon sens" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bastien_Four", Text = "J'ai fait mon premier [taureau] sans toucher la tête et même si le taureau était loin, j'avais l'impression que je n'arriverai pas au bout!", Author = "Bastien Four" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Football", Text = "Ce que je sais de la morale, c'est au football que je le dois.", Author = "Football" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ak%C3%A9_Loba", Text = "Les dieux faisant un tri parmi les hommes, éliminent les pires et les meilleurs, ne laissant vieillir que les rares mortels qui ont vécu sans haine et sans excès pour qu'ils conduisent la génération suivante.", Author = "Aké Loba" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-L%C3%A9ontine_Tsibinda", Text = "La poésie m'a séduite un jour sur la route de l'école: j'adorais le rouge fou des flamboyants au mois de novembre, le bleu insolent d'un ciel d'avril, la nature en fête. Depuis, elle me permet de tenir devant les coups du destin.", Author = "Marie-Léontine Tsibinda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Gar%C3%A7on_et_le_H%C3%A9ron", Text = "Kiriko: Il se passe parfois des choses étranges, ici...", Author = "Le Garçon et le Héron" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sophie_Carquain", Text = "Un auteur, tout comme un comédien, est victime d'un défaut d'être.", Author = "Sophie Carquain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dikkenek", Text = "Annule-moi un peu ce rendez-vous avec ces deux imbéciles de l'école de TV. J'ai pas le temps, j'ai matériellement pas le temps de faire ça.\nDes trous de cul pareil ça m'intéresse pas.", Author = "Dikkenek" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ifeoma_Hope_Uddoh", Text = "le meilleur conseil financier que j'ai pour les femmes est – d'avoir un état d’esprit de croissance.", Author = "Ifeoma Hope Uddoh" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Agatha_Christie", Text = "Aucun détail ne doit être négligé. S'il ne cadre pas avec la théorie, alors c'est elle qui est fautive.", Author = "Agatha Christie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maryse_Cond%C3%A9", Text = "Mais elle était une femme. A ce titre, elle ne pouvait être que l'assistante du génie.", Author = "Maryse Condé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/P%C3%AAcheur", Text = "Nous sommes pareils à ces poissons retenus vifs dans la glace des lacs de montagne. La matière et la nature semblent les protéger cependant qu'elles limitent à peine la chance du pêcheur.", Author = "Pêcheur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ines_Mpambara", Text = "Nous ne rapportons pas suffisamment les problèmes de santé. Il est nécessaire d'aller voir toute la population pour leur demander leur état de santé et leur bien-être général.", Author = "Ines Mpambara" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Charlotte_Gainsbourg", Text = "Ce que j'adore à New York, c'est que toutes les cultures, toutes les communautés, toutes les fêtes sont célébrées. Je trouve cela dément. Quand je me promène à Brighton Beach et que j'entends l'accent russe de ma grand-mère, cela me met en joie!", Author = "Charlotte Gainsbourg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Johnny_Hallyday", Text = "Si on n’avait pas perdu une heure et quart, on serait là depuis une heure et quart.", Author = "Johnny Hallyday" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Affaire_Seznec", Text = "Avec son bandeau sur les yeux, la justice était aveugle. Depuis l'affaire d'Outreau, elle est devenue sourde. Avec l'affaire Seznec, elle est devenue folle. Honte à elle! Les juges avaient une occasion unique de se racheter. C'est raté.", Author = "Affaire Seznec" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Silvina_Ocampo", Text = "Une chose qui n’existe pas mais qui a un nom finit par exister; en revanche, une chose qui existe mais qui n’a pas de nom finit par ne pas exister.", Author = "Silvina Ocampo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Martin_Luther", Text = "Le chrétien est un homme libre, maître de toutes choses; il n'est soumis à personne.Le chrétien est un serviteur plein d'obéissance, il se soumet à tous.", Author = "Martin Luther" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniel_Ellsberg", Text = "J'ai ressenti en tant que citoyen américain, en tant que citoyen responsable, que je ne pouvait plus coopérer en cachant cette information au public américain. J'ai fait cela clairement à mes riques et périls et je suis prêt à répondre de toutes les conséquences de cette décision.", Author = "Daniel Ellsberg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Horloge", Text = "Animal humain, horloge de sang.", Author = "Horloge" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Elle_cause_plus..._elle_flingue", Text = "Depuis l'épieu mérovingien jusqu'aux roquettes à tête fouineuse, y'a pas une arme que tu connaisses pas!", Author = "Elle cause plus... elle flingue" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Robert_Delaunay", Text = "L’œil est notre sens le plus élevé, celui qui communique le plus étroitement avec notre cerveau, la conscience.", Author = "Robert Delaunay" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Annie_Mollard-Desfour", Text = "Ni neutre, ni ennuyeuse, cette couleur aux multiples teintes est aujourd’hui comme hier la couleur de la nuance et de l’ambiguïté.", Author = "Annie Mollard-Desfour" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andr%C3%A9_Manoukian", Text = "La musique, c'est des maths et de l'éros. C'est Pythagore qui chante My Way en duo avec Melody Gardot!", Author = "André Manoukian" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kofi_Annan", Text = "La sécurité n’est pas seulement le premier devoir de tout gouvernement, c’est également un préalable fondamental au développement.", Author = "Kofi Annan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Raisin", Text = "Sur le bord des nuages se tient une femme, sur le bord des îles une femme se tient comme sur les hauts murs décorés de vigne étincelante le raisin mûrit, à belles grappes dorées et noires.", Author = "Raisin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ngina_Kenyatta", Text = "Les jeunes et les dirigeants d'aujourd'hui devraient être désintéressés et donner la priorité aux intérêts du pays, pour que le Kenya connaisse une croissance et un développement bien plus importants.", Author = "Ngina Kenyatta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mame_Fagueye_B%C3%A2", Text = "Quand on épouse une carrière d’artiste il faut une bonne dose d’amour et de passion pour ce que l’on fait, car c’est un combat de tous les jours.", Author = "Mame Fagueye Bâ" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Collaboration", Text = "Dans le cadre d'une collaboration, 1 + 1 = 3: j'ai besoin de toi, tu as besoin de moi et, ensemble, nous atteignons un objectif commun plus ambitieux en générant une valeur supplémentaire.", Author = "Collaboration" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Jullien", Text = "Les images qui fonctionnent sont celles devant lesquelles les gens peuvent se dire: c'est bien vu, je fais ça tout le temps.", Author = "Jean Jullien" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/V_pour_Vendetta_%28bande_dessin%C3%A9e%29", Text = "Souviens-toi, souviens-toi du 5 novembre 1605, de la conspiration des poudres de Guy Fawkes et de Jacques Ier, souviens t'en, car à l'oublier jamais je ne pourrai me résoudre.", Author = "V pour Vendetta (bande dessinée)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Achille_Chav%C3%A9e", Text = "Le fanatique de la tolérance finit un jour ou l'autre dans la tolérance du fanatisme.", Author = "Achille Chavée" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Martine_Broda", Text = "la fleur dit oui de sa mousse sanglante\nun dur peut-être sourira\na frissonné comme la hache\nne pardonne pas plus que le nom\nquand je tournerai à vivre\nle lit blessé dont tu mourras", Author = "Martine Broda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marina_Fo%C3%AFs", Text = "Dans l’intimité, la notoriété est quelque chose de compliqué.", Author = "Marina Foïs" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alicia_Keys", Text = "Je ne vais pas vous mentir, il y a des moments où je me sens un peu submergée et où je veux être à la hauteur de toutes les attentes. Du coup, cela peut parfois créer une pression supplémentaire si je me laisse aller, et il m'arrive de céder à cette pression.", Author = "Alicia Keys" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eug%C3%A8ne_%C3%89bod%C3%A9", Text = "La résignation est un assommoir et la solitude une agonie avant le désastre.", Author = "Eugène Ébodé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Liliane_Bettencourt", Text = "Le pouvoir de l'argent s'arrêtent où commence le goût de la vie.", Author = "Liliane Bettencourt" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_Gore", Text = "Il y a des jours où les petits affronts sont plus difficiles à supporter qu'une blessure grave.", Author = "Catherine Gore" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Monty_Python%27s_Flying_Circus", Text = "Présentateur: Et maintenant quelque chose de complètement différent.", Author = "Monty Python's Flying Circus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karl_Barth", Text = "Je ne suis pas sûr que les anges, lorsqu’ils sont en train de glorifier Dieu, jouent de la musique de Bach; je suis certain, en revanche, que lorsqu’ils sont entre eux, ils jouent du Mozart, et que Dieu aime alors tout particulièrement les entendre.", Author = "Karl Barth" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/N%C3%A9gation", Text = "Dès qu'on nie, on fait la leçon aux autres ou on se la fait à soi-même. On prend à partie un interlocuteur, réel ou possible, qui se trompe et qu'on met sur ses gardes", Author = "Négation" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabelle_Attan%C3%A9", Text = "Toutes les sociétés asiatiques qui s’illustrent par un déficit de femmes ont en commun une forte préférence pour les fils, exacerbée par la baisse du nombre d’enfants. Là est le cœur du problème. C’est bien la conjonction de ces deux tendances qui est à la source de cette discrimination croissante.", Author = "Isabelle Attané" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Essossimna_Marguerite_Gnakad%C3%A8", Text = "L'amour de la patrie transcende la distance et les frontières.", Author = "Essossimna Marguerite Gnakadè" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_de_Rouvroy%2C_duc_de_Saint-Simon", Text = "Je l’imagine, la nuit, penché sur un bureau éclairé d’une chandelle, salivant de bonheur du sang tiède qui coule sur les pages grâce aux meurtres de sa plume. Il est enchanté de méchanceté.", Author = "Louis de Rouvroy, duc de Saint-Simon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sugata_Mitra", Text = "Dans une société ignorante, le pouvoir se structure par la domination physique. Dans la société de l'information, je dois devenir votre ami pour que vous partagiez votre savoir avec moi. C'est un chemin vers la non-violence.", Author = "Sugata Mitra" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Robyn_Ochs", Text = "Je m'identifie comme bisexuelle car je reconnais que j'ai en moi le potentiel d'être attiré, romantiquement et/ou sexuellement, par des gens de plus d'un sexe, pas forcément au même moment, pas forcément de la même façon et pas forcément au même degré.", Author = "Robyn Ochs" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sigourney_Weaver", Text = "Je n’étais pas une personne sûre d’elle, mais je savais ce que je ne voulais pas faire. Je ne voulais pas de sécurité, je ne voulais pas de continuité. À l’école d’art dramatique, on m’avait découragé de faire carrière, alors je me suis dit, bon, je m’en fiche. Je vais juste essayer à ma façon.", Author = "Sigourney Weaver" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gilles_Perret", Text = "Je suis ouvert au débat. Mais je ne veux être jugé que par des gens qui ont vu mes films.", Author = "Gilles Perret" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Marie_Le_Guen", Text = "Ces immigrés, on devrait quand même aussi considérer cela, ils ont une volonté de travailler absolument considérable. S'ils veulent passer en Grande-Bretagne comme ils le font à Calais, c'est parce qu'ils cherchent de l'emploi, ils cherchent un avenir.", Author = "Jean-Marie Le Guen" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nain", Text = "Les hommes errants plus forts que les nains habituels\nNe se rencontrent pas. L'on raconte\nQu'ils se dévoreraient.", Author = "Nain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Leslie_Kaplan", Text = "La révolution est glacée , continuait Mathias, il avait envie de pleurer.\nJe suis seul.\nIl donna un coup de pied dans une pierre.\nIl leva la tête, regarda le ciel.\n\nLe ciel est vide, dit Mathias. C'est atroce. Je m'en fous, mais c'est atroce.", Author = "Leslie Kaplan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Odette_Kayitesi", Text = "le secteur de l'élevage nécessite une attention adéquate pour attirer davantage d'investissements afin de renforcer les services vétérinaires.", Author = "Odette Kayitesi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sarah_Etonge", Text = "Il faudrait que ceux-là sachent que quand j’ai commencé à courir, j’étais suffisamment jeune. J’avais déjà eu mes sept enfants. Le dernier d’entre eux est venu au monde quand j’avais vingt-sept ans. J’ai commencé à courir à vingt-huit ans. Comment ne pouvais-je pas gagner?", Author = "Sarah Etonge" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ana_Dias_Louren%C3%A7o", Text = "Nous avons vécu trop longtemps avec une réalité dans laquelle les femmes étaient reléguées aux marges du pouvoir politique, voyant leurs voix réduites au silence et leurs contributions sous-estimées.", Author = "Ana Dias Lourenço" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Moteur_de_recherche", Text = "Nous commençons à peine à comprendre que les moteurs de recherche sont la porte d'entrée de toutes les interactions sociales.", Author = "Moteur de recherche" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Thomas_Henry_Huxley", Text = "Les pires difficultés d’un homme commencent quand il peut faire ce qui lui plaît.", Author = "Thomas Henry Huxley" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Carmen_Conde", Text = "Je crois que j'ai commencé à écrire à l'âge de quatorze ans, après avoir lu quelques livres importants dont je commençais à comprendre la valeur exacte. La lecture a été pour moi la chose la plus importante, au même titre que la musique et les autres arts.", Author = "Carmen Conde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Naomi_Oreskes", Text = "La science  nous a montré que la civilisation industrielle  contemporaine n'est pas durable.", Author = "Naomi Oreskes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amina_J._Mohammed", Text = "Je crois que tant de problèmes auxquels les filles sont confrontées seraient résolus si nous pouvions briser l'emprise du patriarcat, la misogynie, que nous déguisons en tradition culturelle ou en religion", Author = "Amina J. Mohammed" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Pape-Carpantier", Text = "La femme n'est pas d'une autre nature que celle de l'homme, elle possède les mêmes facultés.", Author = "Marie Pape-Carpantier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Genevi%C3%A8ve_Boko_Nadjo", Text = "La Commission électorale n’explique pas la loi. Mais elle explique les modalités d’application de la loi .", Author = "Geneviève Boko Nadjo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Connolly", Text = "Eh bien, qu'en dis-tu? Je fais la grasse matinée, je lis un bon bouquin, et je participe à une insurrection. Tout ça dans la foulée. Tu parles d'une révolution de luxe!", Author = "James Connolly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fazila_Jeewa-Daureeawoo", Text = "Peut-être que nous avons une tendance à Maurice à faire les choses et à suivre les règlements, même s’ils sont dépassés, comme on l’a toujours fait. Peut-être que nous n’avons pas la culture de l’innovation, de la remise en question et du changement.", Author = "Fazila Jeewa-Daureeawoo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maurice_Genevoix", Text = "Admettre que les racines de l’art  plongent dans un terreau magique, c’est peut être s’ouvrir un chemin vers les prestiges de la fleur, ses enchantements, ses sortilèges.", Author = "Maurice Genevoix" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pleur", Text = "Que le trépas vers moi ne vienne pas sans pleurs,\nQu’à ma mort mes amis s’affligent et sanglotent.", Author = "Pleur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chlo%C3%A9_Quenum", Text = "Je n’ai réalisé à quel point j’allais loin qu’une fois à l’autre bout de la planète, sous un ciel différent, avec 12 heures de décalage horaire avec la France. C’était une expérience très émouvante, qui m’a rappelé beaucoup de choses.", Author = "Chloé Quenum" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Si_Mohand_Ou_Mhand", Text = "Je le jure de Tizi-Ouzou\nJusqu’à l’Akfadou\nNul d’eux ne me commandera\n\nPlutôt rompre que plier\nPlutôt être maudit\nDans un pays où les chefs sont des entremetteurs\n\nL’exil m’est prédestiné\nPar Dieu j’aime mieux l’exil \nQue la loi des pourceaux.", Author = "Si Mohand Ou Mhand" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Edward_Bernays", Text = "La manipulation consciente, intelligente, des opinions et des habitudes organisées des masses joue un rôle important dans une société démocratique. Ceux qui manipulent ce mécanisme social imperceptible forment un gouvernement invisible qui dirige véritablement le pays.", Author = "Edward Bernays" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabelle_Kocher", Text = "Assumez qui vous êtes et ce que vous voulez.", Author = "Isabelle Kocher" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hemley_Boum", Text = "La maternité est comme la vie, en nuances de gris, et beaucoup trop souvent, le gris vire au noir..", Author = "Hemley Boum" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Golshifteh_Farahani", Text = "C’est le problème de l’exil. Les gens pensent qu’on est libre, léger, mais la tragédie commence de l’autre côté de la mer.", Author = "Golshifteh Farahani" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mariama_Ndoye", Text = "Paraphrasant Térence, j’affirme: Je suis femme, je veux que rien de ce qui est féminin ne me soit étranger.", Author = "Mariama Ndoye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jack_Vance", Text = "La musique est une communication - une communication émotionnelle, évidemment - et cela implique un accord sur la symbologie.", Author = "Jack Vance" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marion_Montaigne", Text = "Dès que je regarde un film, je râle comme un pou à la moindre approximation scientifique. Mais la pop culture m’est très utile pour accrocher le spectateur, car qui se lève le matin en se disant: Tiens, aujourd’hui, je vais me passionner pour la génétique?", Author = "Marion Montaigne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeannine_Mabunda_Lioko", Text = "Nous sommes là pour apporter des réponses aux désidératas des citoyens", Author = "Jeannine Mabunda Lioko" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bernard_Laponche", Text = "Le nucléaire ne représente pas seulement une menace terrifiante, pour nous et pour les générations qui suivront; il condamne notre pays à rater le train de l'indispensable révolution énergétique.", Author = "Bernard Laponche" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Terry_Goodkind", Text = "Les gens ont tendance à tenir pour vrai ce qu'ils souhaitent être la vérité ou ce qu'ils redoutent être la vérité.", Author = "Terry Goodkind" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hippolyte_Taine", Text = "Un vrai peintre regarde avec plaisir un bras bien attaché et des muscles vigoureux, quand même ils seraient employés à assommer un homme. Un vrai romancier jouit par contemplation de la grandeur d'un sentiment nuisible - ou du mécanisme ordonné d'un caractère pernicieux.", Author = "Hippolyte Taine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Treizi%C3%A8me_Docteur", Text = "Treizième Docteur: Nous sommes tous capable du changement le plus incroyable. Nous pouvons évoluer, tout en restant fidèle à nous-mêmes. Nous pouvons honorer qui nous étions, et choisir qui nous voulons devenir.", Author = "Treizième Docteur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89pigraphe", Text = "Épigrapher est toujours un geste muet dont l'interprétation reste à la charge du lecteur.", Author = "Épigraphe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9borah_Heissler", Text = "Ni tableau, ni théâtre, où les choses auraient été engagées, pour figurer une vie autre que la leur.", Author = "Déborah Heissler" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Port", Text = "Corsaire Sanglot aborde au port. Le môle est en granit, la douane en marbre blanc. Et quel silence. De quoi parlé-je? Du Corsaire Sanglot. Il aborde au port, le môle est de porphyre et la douane en lave fondue... et quel silence sur tout cela.", Author = "Port" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Violon", Text = "Le luthier, en fabricant un violon, permet la naissance des plus beaux sons de miel et d'or que l'oreille humaine puisse entendre", Author = "Violon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lawrence_Oates", Text = "Je vais juste dehors et cela pourra prendre un certain temps", Author = "Lawrence Oates" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gabriel_Syveton", Text = "(...) l'Action française commémora au cimetière Montparnasse le quatrième anniversaire de l'assassinat de Gabriel Syveton, par le port d'une couronne dont la banderole portait: A la mémoire de Gabriel Syveton, assassiné par ordre, la veille du procès qui fit peur au traître Dreyfus.", Author = "Gabriel Syveton" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Claire_Voisin", Text = "Un trait spécifique des mathématiques est le fait qu’elles fonctionnent en corps à corps avec le langage, qui y joue un rôle fondamental et apparaît dans l’organisation de la démarche mathématique à toutes les étapes: la définition, l’hypothèse, la démonstration, le théorème.", Author = "Claire Voisin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Patriotisme", Text = "Plus encore que le patriotisme qui est une hystérie comme une autre, mais plus creuse et plus mortelle qu’une autre, ce qui nous répugne c’est l’idée de Patrie qui est vraiment le concept le plus bestial, le moins philosophique dans lequel on essaie de faire entrer notre esprit.", Author = "Patriotisme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Leila_Zerrougui", Text = "La participation des femmes congolaises au processus électoral est essentielle.", Author = "Leila Zerrougui" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Garcia-Fons", Text = "Dans les années 1962-65, je digérais mal une certaine réussite, j'éprouvais une sorte de refus, un malaise. [...] Et je me prends à regretter cette réussite-là, qu'il fallait savoir exploiter pour l'infléchir en temps voulu dans le sens de mes aspirations.", Author = "Pierre Garcia-Fons" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nicolas_Machiavel", Text = "Mais comme ceux qui ont à considérer des montagnes se placent dans la plaine, et sur des lieux élevés lorsqu’ils veulent considérer une plaine, de même, je pense qu’il faut être prince pour bien connaître la nature et le caractère du peuple, et être du peuple pour bien connaître les princes.", Author = "Nicolas Machiavel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Awa_Marie_Coll_Seck", Text = "Les problèmes de santé du continent ne sont pas insurmontables. Mais il faut les prendre à bras le corps. Cela demande des financements que nous devons trouver au niveau local: c’est à nous, au Sénégal, de trouver des solutions pour aboutir à des solutions pérennes.", Author = "Awa Marie Coll Seck" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9d%C3%A9_Rose_Creppy", Text = "Une Nana Benz, c'est une femme qui a aidé le Togo et l'Afrique par son acharnement au travail. Les Nanas Benz ont toujours eu des moyens de transport très très puissants. C'est pourquoi elles achetaient des Mercedes Benz.", Author = "Dédé Rose Creppy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fredric_Brown", Text = "Le dernier homme sur la Terre était assis tout seul dans une pièce. Il y eut un coup à la porte…", Author = "Fredric Brown" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kalista_Sy", Text = "Je porte un bagage lourd. Je n'ai pas le droit à l'échec.", Author = "Kalista Sy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Honor%C3%A9_Gabriel_Riqueti_de_Mirabeau", Text = "Ne vous paraît-il pas absurde de mettre en opposition les intérêts de deux cent mille privilégiés avec ceux de vingt-cinq millions de citoyens?", Author = "Honoré Gabriel Riqueti de Mirabeau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatima_Ali", Text = "Je crois que j'étais né pour être chef. C'était ma vocation.", Author = "Fatima Ali" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Annie_Matundu_Mbambi", Text = "Je travaille sur le désarmement. C’est bien de savoir par exemple quels progrès sont réalisés par la MONUSCO et les FARDC dans les territoires où sont présents les groupes armés. Ensuite, au niveau de la base, nous pouvons être des intermédiaires pour expliquer le travail de la MONUSCO en RDC", Author = "Annie Matundu Mbambi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Francis_Parkman", Text = "La civilisation espagnole a écrasé l’Indien; la civilisation anglaise l’a méprisé et négligé; la civilisation française l’a étreint et chéri.", Author = "Francis Parkman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Antoine_Bello", Text = "Ce qu'un apprenti demande à son maître, c'est qu'il lui enseigne les techniques, les savoirs qui lui permettront plus tard de faire œuvre de création à son tour.", Author = "Antoine Bello" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Espoir", Text = "Hassan: Il y a un proverbe bédouin qui dit: L’espoir est femme et le désespoir est homme. Pour une fois, nous ferions mieux d’essayer de le faire mentir.", Author = "Espoir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zulma_Carraud", Text = "Si Dieu nous retirait son soleil chaque fois que nous l’offensons, nous n’aurions guère d’épis mûrs pour la moisson.", Author = "Zulma Carraud" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vigd%C3%ADs_Finnbogad%C3%B3ttir", Text = "Le pessimisme mine le courage, tandis que l'optimisme le renforce.", Author = "Vigdís Finnbogadóttir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dieu", Text = "Car Dieu a tant aimé le monde qu’il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu’il ait la vie éternelle.", Author = "Dieu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dix-neuf_po%C3%A8mes_anciens", Text = "La vie de l'homme: un seul séjour dans l'existence,\nPrompt et subit, comme poussière en un typhon.", Author = "Dix-neuf poèmes anciens" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne-Gabriel_Meusnier_de_Querlon", Text = "Adieu, plaiſant pays de France,\nÔ ma patrie, La plus chérie\nQui as nourri ma jeune enfance!\nAdieu, France, adieu mes beaux jours.", Author = "Anne-Gabriel Meusnier de Querlon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Toxicomanie", Text = "Le cheval est capricieux par nature et quand par surcroît il est toxicomane, le pire est à craindre, mon cher.", Author = "Toxicomanie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Livre_des_Psaumes", Text = "Quand même j’aurais à marcher dans la vallée des ombres de la mort,\nJe ne craindrais aucun mal, parce que vous êtes avec moi.\nVotre bâton, votre houlette,\nVoilà mon réconfort.", Author = "Livre des Psaumes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Debbie_Ford", Text = "L'ombre se réfère à cette portion de nous-mêmes qui est en perpétuel changement et mouvance sous l'éclairage de la conscience de l'ego, à ces aspects du moi que nous n'arrivons pas à amener complètement dans le champ de l'intelligence responsable.", Author = "Debbie Ford" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anthony_Kavanagh", Text = "Que Dieu vous garde parce que j'ai pas de place chez moi.", Author = "Anthony Kavanagh" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Origin_Unknown", Text = "Trente et une secondes.", Author = "Origin Unknown" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ros%C3%A9e", Text = "Ses bas de soie rouge jettent une lueur tournoyante sur les coteaux de jonc. Le fantôme a environ deux cents ans, il parle encore un peu français. Mais dans sa chair transparente se conjuguent la rosée du soir et la sueur des astres.", Author = "Rosée" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Architecte", Text = "ARCHITECTES. Tous imbéciles. Oublient toujours l’escalier des maisons.", Author = "Architecte" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fr%C3%A9d%C3%A9ric_Calon", Text = "Il faudrait d'une part étudier plus à fond le mécanisme de la thermorégulation chez les personnes âgées et, d'autre part, tester des molécules qui pourraient stimuler cette régulation thermique pour voir si on est capable d'avoir un effet sur la mémoire.", Author = "Frédéric Calon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Moustapha_Abdel_Jalil", Text = "Nous n’accepterons aucune idéologie extrémiste. Nous sommes un peuple musulman, pour un islam modéré, et nous resterons sur cette voie.", Author = "Moustapha Abdel Jalil" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coup_de_foudre_%C3%A0_Notting_Hill", Text = "William: Ma vie est foutue parce que je ne lis pas Voici.", Author = "Coup de foudre à Notting Hill" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/R%C3%A9surrection", Text = "On ne voit point deux fois le rivage des morts,\nSeigneur; puisque Thésée a vu les sombres bords,\nEn vain vous espérez qu’un dieu vous le renvoie;\nEt l’avare Achéron ne lâche point sa proie.", Author = "Résurrection" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alexandre_Lacassagne", Text = "Le milieu social est le bouillon de culture de la criminalité; le microbe c'est le criminel, un élément qui n'a d'importance que le jour où il trouve le bouillon qui le fait fermenter.", Author = "Alexandre Lacassagne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaamelott/Yvain", Text = "Je refuse d’aller me battre pour soutenir une politique d’expansion territoriale dont je ne reconnais pas la légitimité.", Author = "Kaamelott/Yvain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ainsi_parlait_Zarathoustra", Text = "Mais une fois que Zarathoustra fut seul, il se dit en son cœur: Serait-ce possible! Ce vieux saint dans sa forêt n'a pas encore entendu dire que Dieu est mort!", Author = "Ainsi parlait Zarathoustra" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mekomb%C3%A9_Th%C3%A9r%C3%A8se", Text = "Une fille mariée précocement n'a pas l'occasion de mener une vie de jeune fille, n'a pas la possibilité d'aller à l'école et de s'épanouir comme les autres filles. C'est son avenir qui est ainsi brisé.", Author = "Mekombé Thérèse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Th%C3%A9ophraste", Text = "Les lois doivent être faites en vue de ce qui arrive le plus souvent, et non en vue d'événements extraordinaires.", Author = "Théophraste" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Grands_Ducs", Text = "Victor Vialat: Deviens jamais vieux, mon p'tit. Fais jamais cette connerie.", Author = "Les Grands Ducs" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gaspard_Proust", Text = "Moi à la base, je voulais faire prêtre mais comme je suis trop timide pour aborder les enfants...", Author = "Gaspard Proust" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/H%C3%A9l%C3%A8na_Villovitch", Text = "Tu vas passer une année absolument démentielle", Author = "Hélèna Villovitch" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/David_Djigla", Text = "Faire rêver les jeunes comme d’autres joueurs africains m’ont fait rêver.", Author = "David Djigla" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuel_Carr%C3%A8re", Text = "Je toisais cette vie de haut, je n'en aurais pas voulu, il n'empêche que ce jour-là je regardais les enfants, je regardais leurs parents les filmer avec leurs caméscopes, et je me disais que le choix de la vie à Rosier n'était pas seulement celui de la sécurité et du troupeau, mais de l'amour.", Author = "Emmanuel Carrère" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Moussa_Latoundji", Text = "La priorité, c’est que l’équipe retrouve la gagne des matchs, le bon jeu. Que le peuple retrouve ce qu’il aime voir, la victoire. Je pense que nous allons faire avec tous les joueurs qui jouent partout dans le monde et qui sont en forme.", Author = "Moussa Latoundji" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zora_Neale_Hurston", Text = "Parfois, je me sens victime de discrimination, mais cela ne me met pas en colère. Cela m'étonne simplement. Comment peut-on se priver du plaisir de ma compagnie? Cela me dépasse.", Author = "Zora Neale Hurston" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Shadiya_Alimatou_Assouman", Text = "Nous considérons le commerce électronique non seulement comme un accélérateur des échanges, mais aussi comme un moyen important de surmonter les barrières érigées par la pandémie de COVID-19 et d’assurer la continuité des activités commerciales.", Author = "Shadiya Alimatou Assouman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7oise_Verg%C3%A8s", Text = "La peur est une de ses armes favorites pour produire conformisme et consentement.", Author = "Françoise Vergès" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ndeye_Binta_Leye", Text = "C'était très difficile. Je recevais moi-même les clients et je m'occupais de la broderie anglaise. Je devais m'occuper en même temps des tailleurs, de la facturation et des livraisons. Il y avait aussi mon foyer à gérer, avec un enfant surtout. Mais je croyais au succès.", Author = "Ndeye Binta Leye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mireille_Mathieu", Text = "Que l'on touche à la liberté\nEt Paris se met en colère!", Author = "Mireille Mathieu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Pauly", Text = "Défendre la jeunesse, c'est mettre à sa portée tous les moyens de faire valoir ses aptitudes et ses goûts.", Author = "Paul Pauly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zenab_Issa_Oki", Text = "Je suis devenue ce que je suis aujourd’hui, c’est parce que beaucoup de personnes m’ont soutenu et cru en moi.", Author = "Zenab Issa Oki" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Jour_de_gloire", Text = "Dans l'aviation l'alcool, interdit, ça déséquilibre l'appareil.", Author = "Le Jour de gloire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Adam", Text = "Cette fois-ci, voilà l’os de mes os et la chair de ma chair! On l’appellera femme, elle qui fut tirée de l’homme.", Author = "Adam" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christian_Jacq", Text = "Le coeur dresse les plans et guide l'individu; quant au caractère, il mantient ce qui fut acquis et préserve les visions du coeur.", Author = "Christian Jacq" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Thomas_Sowell", Text = "La désinformation est encore pire, même lorsqu'elle est bien intentionnée.", Author = "Thomas Sowell" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alexis_L%C3%A9ontiev", Text = "La force de ce préjugé profondément ancré dans les esprits, selon lequel le développement spirituel de l'homme prend sa source en lui-même, est si grande qu'elle conduit à poser le problème à l'envers.", Author = "Alexis Léontiev" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tierno_Mon%C3%A9nembo", Text = "La chance ne pénètre pas le derrière de celui qui dort.", Author = "Tierno Monénembo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rapport_au_savoir", Text = ". Il m'arrive (…) de rencontrer des gens qui savent des choses que je ne sais pas. Je les tiens par le coude et je veux qu'ils me disent tout, tout de suite. Et je les interroge et je les interroge, jusqu'à ce qu'ils aient la voix blanche et s'en aillent, plumés comme volaille.", Author = "Rapport au savoir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Folie_des_grandeurs", Text = "C'est pour le roi? Non c'est pour Salluste… Voleur! Mais non pas voleur, c'est pour Salluste.", Author = "La Folie des grandeurs" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_de_Marolles", Text = "J'ai perdu des amis par un rare caprice, quand je leur ai donné des livres que j'ai faits, comme gens offensez, sans pardonner jamais, bien qu'on n'ait point blessé leur méchant artifice.", Author = "Michel de Marolles" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yollande_Ebongo_Bosongo", Text = "Pour l’année 2020, dix-sept mille fonctionnaires iront à la retraite.", Author = "Yollande Ebongo Bosongo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/MC_Solaar", Text = "Le vent se lève pour dire que mon karma\nSuit la cadence qui me mène au nirvâna\nEnsorceler le pacte et sceller la beauté du corps\nSans effort, c'est de danser\nOn me traite de traitre quand je traite de la défaite du silence\nLe silence est d'or, mais j'ai choisis la cadence", Author = "MC Solaar" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Grammaire_de_Port-Royal", Text = "Parler est expliquer ses pensées par des signes que les hommes ont inventés à dessein.", Author = "Grammaire de Port-Royal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Anthelme_Brillat-Savarin", Text = "L'univers n'est rien que par la vie, et tout ce qui vit se nourrit.", Author = "Jean Anthelme Brillat-Savarin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Fid%C3%A8le_Berger", Text = "La terre promise recule à mesure qu'on en approche. Et si par hasard on la touche, ce n'est plus que la terre obtenue.", Author = "Le Fidèle Berger" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Genevi%C3%A8ve_Fauconnier", Text = "Ce qu'on invente est plus logique que la vie. La réalité construit une histoire qui a trop de longueurs. On s'y perd. Longueurs qui pourtant se réduisent à peu de choses, une fois dépassées:  Cet été-là, tu avais une robe à pois...", Author = "Geneviève Fauconnier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arturo_P%C3%A9rez-Reverte", Text = "Vous savez bien que lorsqu'on élimine l'impossible, ce qui reste, pour improbable qu'il puisse paraître, doit nécessairement être vrai.", Author = "Arturo Pérez-Reverte" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Laurent_Alexandre", Text = "L’homme qui vivra 1 000 ans est déjà né.", Author = "Laurent Alexandre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dracula_%28film%2C_1992%29", Text = "Dracula: Entrez ici de votre plein gré et laissez-y un peu de la joie que vous y apportez.", Author = "Dracula (film, 1992)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Crumley", Text = "Mais la visualisation d'un rêve n'altère en rien l'essence de sa réalité; au contraire il permet au rêve de devenir plus facilement réalité.", Author = "James Crumley" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Oscar_Wilde", Text = "On devrait toujours être légèrement improbable.", Author = "Oscar Wilde" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Synarchie", Text = "L'ordre est le strict équilibre entre la liberté et l'autorité dans chaque domaine de la vie collective et à tout moment : seul cet équilibre est synarchique, et par lui seul l'État peut durer.", Author = "Synarchie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89mile_Cou%C3%A9", Text = "Tous les jours, à tous points de vue, je vais de mieux en mieux.", Author = "Émile Coué" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_Girard", Text = "Chacun se croit seul en enfer et c'est cela l'enfer.", Author = "René Girard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Shashi_Deshpande", Text = "La religion n'est malheureusement et ironiquement jamais bonne pour les femmes, car toutes les religions sont enracinées dans le patriarcat.", Author = "Shashi Deshpande" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tita_Mandeleau", Text = "Quelle rage que de se sentir l'âme aventureuse de Sir Francis Drake et de devoir marchander avec ces gens-là comme un vulgaire maquignon à la foire de Mayfair.", Author = "Tita Mandeleau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Justice", Text = "La Loi n’a le droit de défendre que les actions nuisibles à la Société. Tout ce qui n’est pas défendu par la Loi ne peut être empêché, et nul ne peut être contraint à faire ce qu’elle n’ordonne pas.", Author = "Justice" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nadia_Murad", Text = "Nous n’ambitionnions pas d’avoir plus de terres ni de pouvoir, et rien dans notre religion ne nous commande de conquérir les populations non yézidies et de répandre notre foi.", Author = "Nadia Murad" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C3%A9sar_%28sculpteur%29", Text = "Je n’ai pas d’imagination. Elle ne me vient qu’avec le toucher et les yeux. Sans ces deux éléments, le cerveau ne fonctionne pas.", Author = "César (sculpteur)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Terminus_Canebi%C3%A8re", Text = "Être flic, c'est comme manger des cacahuètes: c'est très dur de s'arrêter.", Author = "Terminus Canebière" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nic%C3%A9phore_Soglo", Text = "J’invite donc les commanditaires et les auteurs de cette désinformation, de ce Fake-news, d’indiquer à quel compte bancaire sont logés ces détournements, à quelle occasion, et avec qui ces actes crapuleux ont été commis.", Author = "Nicéphore Soglo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Farah_Pahlavi", Text = "Ces jeunes me bluffent [...] J'admire le courage des femmes, des jeunes filles et garçons nés après la révolution islamique. Leur cran reste intact malgré les dangers.", Author = "Farah Pahlavi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_Chapus", Text = "Le recours pour excès de pouvoir est d’autre part ce que j’appellerais un recours d’utilité publique.", Author = "René Chapus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Grande_Porte", Text = "Toutes les émissions de télévision ont des publicités pour nous gonfler le moral en nous disant combien notre travail est important, combien le monde entier compte sur nous pour se nourrir.", Author = "La Grande Porte" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ir%C3%A8ne_Assiba_d%27Almeida", Text = "De toutes les femmes que j’ai été je préfère la Femme que je suis Aujourd’hui.", Author = "Irène Assiba d'Almeida" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Multinationale", Text = "Mon inquiétude, c’est de voir les multinationales et les grands groupes financiers concentrer les richesses et devenir très puissants. Au bout du compte, les intérêts financiers dépasseront alors les peuples et les États organisés, ils affaibliront les pouvoirs politiques et la démocratie.", Author = "Multinationale" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/G%C3%A9nie", Text = "Contrairement aux figures de la Vestale ou de Cornalie, qui exaltent le foyer et la maternité, celle de Sappho raconte l'histoire de la femme de génie, rejetée par des hommes incultes, jeunes et beaux, qui meurt parce qu'elle a abdiqué les pouvoirs de l'esprit.", Author = "Génie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nicki_Minaj", Text = "Mon vrai nom est Maraj. Fendi l'a lancé quand il m'a croisé parce que j'avais genre un mauvais flux!", Author = "Nicki Minaj" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Justin_Lh%C3%A9risson", Text = "Il est un bel échantillon de misère physiologique. Il a les yeux creux, le visage sombre et renfrogné. De sourdes tempêtes soufflent dans son esprit et dans son ventre…", Author = "Justin Lhérisson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maurice_Benhamou", Text = "Chaque nuit initie l’autre nuit. Chaque lettre enseigne à l’autre son mystère. Au-dessus de la nuit de l’écrit, passe un astre de chair. Sans nom. Solitaire. Périssable.", Author = "Maurice Benhamou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Frank_Dartal", Text = "Dans cet univers clos, tout changement dans les idées reçues pouvait engendrer une catastrophe.Pour durer, l'homme devait s'accrocher à des fantasmes, des mythes, des rites. Son néant devait être comblé sous peine de verser dans la folie.", Author = "Frank Dartal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nelly_Roussel", Text = "Ô femmes! L'heure a sonné des révoltes libératrices. Ce n'est pas la charité que nous demandons c'est la justice.", Author = "Nelly Roussel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amy_Sarr_Fall", Text = "Bien sûr qu’il y a des obstacles, mais il faut savoir les surmonter, sinon la vie n’aurait pas de sens. Il y a quelques années, j’avais été victime de diffamation et j’en étais effondrée. Je n’étais pas préparée à ce genre de chose et cela peut vous briser le moral.", Author = "Amy Sarr Fall" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Thierry_Destrez", Text = "Soyez bref, la pensée orale a sa syntaxe: des phrases courtes de 15 mots maximum.", Author = "Thierry Destrez" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Oprah_Winfrey", Text = "Je n'ai jamais eu d'enfants, je n'ai jamais même pensé que j'aurais des enfants. Maintenant j'ai 152 filles, et j'en attends 75 de plus l'année prochaine. C'est une forme de gestation!", Author = "Oprah Winfrey" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Francisco_de_Goya", Text = "La duchesse d'Albe vient d'entrer dans mon atelier et a voulu que je lui peignisse le visage au pastel. Peindre ainsi sur le vif, mon cher;  charmante occupation, que je préfère aux études sur le mannequin.", Author = "Francisco de Goya" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Empereur-Dieu_de_Dune", Text = "Vos ennemis vous renforcent. Vos alliés vous affaiblissent.", Author = "L'Empereur-Dieu de Dune" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Riss", Text = "Si le sportif a une telle place dans nos médias, c'est parce qu'il est le symbole parfait de nos sociétés sans but, dont la devise pourrait être tout ça pour ça.", Author = "Riss" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nathalie_Koah", Text = "Au Cameroun, la femme ne parle pas de sexe, ne hausse pas la voix, ne tient pas tête à un homme….", Author = "Nathalie Koah" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Guillaume_Gyr", Text = "On prétend, à tort ou à raison, que toutes les révolutions modernes ont été préparées, mûries et conduites par les associations secrètes, et particulièrement par la Franc-Maçonnerie. […] Cette accusation est trop grave pour ne point reposer sur des preuves nombreuses et irréfragables.", Author = "Jean Guillaume Gyr" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tim_Jackson", Text = "[Prospérité sans croissance] était le premier rapport adressé à un gouvernement qui remettait en cause la croissance. Et cela reste un fait unique.", Author = "Tim Jackson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bj%C3%B6rn_Larsson", Text = "Je pense à ce qu'a dit Ian Nicholson à propos du mal de mer et de ses deux stades: le premier, au cours duquel on pense qu'on va mourir, n'est rien à côté du second, au cours duquel on comprend qu'on ne va pas mourir.", Author = "Björn Larsson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vingt_Mille_Lieues_sous_les_mers", Text = "L’année 1866 fut marquée par un événement bizarre, un phénomène inexpliqué et inexplicable que personne n’a sans doute oublié.", Author = "Vingt Mille Lieues sous les mers" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yakari", Text = "Roc Tranquille: Quand l'âge est là, le sommeil s'en va...", Author = "Yakari" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Cheng", Text = "Avant que tout ne soit perdu, avant que le siècle ne se termine, quelqu’un, du fond de l’insondable argile, a tout de même réussi, par la seule vertu de la parole, à faire don des trésors amassés le long d’une vie emplie de fureurs et de saveurs.", Author = "François Cheng" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mireille_Kamariza", Text = "Pour les immigrés, pour les personnes issues de milieux traditionnellement défavorisés, tout se joue sur les opportunités et sur ceux qui peuvent vous ouvrir la porte.", Author = "Mireille Kamariza" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Miroir_qui_gla%C3%A7ait", Text = "Parce que je crois aussi que, souvent, les jeunes sont plus vifs à saisir la réalité des choses que les vieux. Comme ils manquent d'expérience, ils ne sont pas tentés de sortir des solutions toutes faites.", Author = "Le Miroir qui glaçait" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gilles-%C3%89ric_S%C3%A9ralini", Text = "Les OGM dits de première génération, destinés à la production agricole dominante, et servant au passage à breveter la base de l'alimentation, constituent donc, et pour longtemps, le véritable enjeu.", Author = "Gilles-Éric Séralini" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/S%C3%A9noussi_Hassana_Abdoulaye", Text = "Être maire d’une capitale comme N’Djamena n’est pas un honneur à prendre à la légère. C’est un engagement total et exigeant.", Author = "Sénoussi Hassana Abdoulaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jiddu_Krishnamurti", Text = "L'amour est un tout indissociable et perpétuellement neuf.", Author = "Jiddu Krishnamurti" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eug%C3%A8ne_Fromentin", Text = "Je me suis mis d'accord avec moi-même, ce qui est bien la plus grande victoire que nous puissions remporter sur l'impossible.", Author = "Eugène Fromentin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Claude_Kaufmann", Text = "Même au sein d'un couple, chacun se vit comme un être autonome, aspirant à son espace de respiration personnel.", Author = "Jean-Claude Kaufmann" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kareyce_Fotso", Text = "La femme est le socle de l’humanité. Je pense que c’est important, vu le rôle que la femme joue dans la société, de s’arrêter quelques fois et de lui rendre hommage.", Author = "Kareyce Fotso" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marthe_Fare", Text = "Je suis une féministe antiféministe. Je suis féministe seulement pour les femmes qui veulent qu’on lutte pour elles.", Author = "Marthe Fare" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Faim", Text = "Il n'est pas de guerrier qui puisse affronter le combat une journée entière, jusqu'au soleil couché, s'il n'a goûté au pain.", Author = "Faim" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/K%C3%A9ba_Mbaye", Text = "C'est par sa capacité de se mobiliser aux heures difficiles, pour construire ce qui est essentiel à son destin de dignité, qu'un peuple sculpte l'image que l'histoire retiendra de lui.", Author = "Kéba Mbaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marek_Halter", Text = "La lumière montait comme une mer, vague après vague, déposant tour à tour des couleurs tendres et des éclats de quartz, allumant l'ocre des remparts, l'argent bleu des oliviers, la blancheur des terrasses.", Author = "Marek Halter" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Meurtre_myst%C3%A9rieux_%C3%A0_Manhattan", Text = "À chaque fois que j'écoute du Wagner, j'ai envie d'envahir la Pologne.", Author = "Meurtre mystérieux à Manhattan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rolande_Ngo_Issi", Text = "Il faut aimer ce qu’on fait, il faut d’abord identifier ses atouts, il faut identifier ses convictions et maintenant travailler à ce que cela devient un atout pour soi..", Author = "Rolande Ngo Issi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuel_Berl", Text = "La politique française me semble évoluer moins comme une histoire que comme une névrose.\nSon trait dominant, à mon estime, c'est l'affaiblissement progressif du sens du réel qu'elle manifeste, depuis quinze ans.\nPolitique schizophrène.", Author = "Emmanuel Berl" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Benoit", Text = "Si les pages qui vont suivre voient un jour la lumière du soleil, c’est qu’elle m’aura été ravie. Le délai que je fixe à leur divulgation m’en est un assez sûr garant.", Author = "Pierre Benoit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Baudouin_%28roi_des_Belges%29", Text = "Serait-il normal que je sois le seul citoyen belge à être forcé d’agir contre sa conscience dans un domaine essentiel? La liberté de conscience vaut-elle pour tous sauf pour le Roi?", Author = "Baudouin (roi des Belges)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Indien", Text = "Je crus pendant une seconde qu’elle était devenue folle, elle aussi. Et je hurlai de joie, semblable à un Indien qui se venge.\nElle ne se troubla point. Elle était habituée à mon humeur fantasque. Elle me méprisait trop pour me craindre.", Author = "Indien" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nous%2C_les_dieux", Text = "Philosophie et science ont toujours été opposées, mais pour moi elles se rejoignent dans ce qu'on pourrait nommer spiritualité laïque. Là, ce qui importe, ce sont les questions plus que les réponses.", Author = "Nous, les dieux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Charles_Seignobos", Text = "L'histoire a pour but de décrire, au moyen de documents, les sociétés passées et leurs métamorphoses.", Author = "Charles Seignobos" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/V%C3%A9ronique_Kilumba_Nkulu", Text = "Ma foi m’a permis de restaurer un climat de paix entre les agents du cabinet du ministre et ceux de mon cabinet qui étaient à couteaux tirés avant mon arrivée.", Author = "Véronique Kilumba Nkulu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Upfield", Text = "La pièce, la maison, la vie elle-même semblaient être entrées dans une zone d'ombre qui déformait le monde réel et le rendait fantastique.", Author = "Arthur Upfield" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tina_S%C3%A9gl%C3%A9", Text = "Ce système fait que ma sensibilité artistique et ma culture musicale africaine restent parfaitement intactes.", Author = "Tina Séglé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Estelle_Johnson", Text = "La chose la plus importante en sport est de ne pas s’effondrer ou à l’inverse de s’enflammer.", Author = "Estelle Johnson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louise_Arbour", Text = "Le Conseil de sécurité pouvait m'arrêter, il pouvait gracier Milošević. Il pouvait faire tout ce qu'il voulait s'il estimait qu'une action de ma part risquait de déclencher la Troisième Guerre mondiale. C'était son problème, pas le mien.", Author = "Louise Arbour" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/F%C3%A9lix_Timmermans", Text = "Le soleil avait plongé, pareil à un poisson d’or.", Author = "Félix Timmermans" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Organisation_internationale_du_travail", Text = "Une paix universelle et durable ne peut être fondée que sur la base de la justice sociale", Author = "Organisation internationale du travail" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Publius_Syrus", Text = "Ne fais pas ta joie du malheur d'autrui.", Author = "Publius Syrus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stephen_Clarke_%28%C3%A9crivain%29", Text = "L'année ne commence pas le 1er janvier, tous les Français savent ça. Il n'y a que ces fous d'Anglo-Saxons pour croire un truc pareil. En réalité, l'année commence le premier lundi de septembre.", Author = "Stephen Clarke (écrivain)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Koyaanisqatsi", Text = "Si nous déterrons les richesses du sol, nous inviterons le désastre.\nVers le Jour de la Purification, il y aura des toiles d’araignée tissées à travers le ciel.\nUn jour, il se peut qu’un récipient de cendres soit jeté du ciel: il pourrait embraser la terre et faire bouillir les océans.", Author = "Koyaanisqatsi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%C3%A9opold_Ier_%28roi_des_Belges%29", Text = "La Belgique n’a pas de nationalité et vu le caractère de ses habitants ne pourra jamais en avoir.", Author = "Léopold Ier (roi des Belges)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Laurent_Gerra", Text = "Un jour à droite, un jour à gauche. C'est pour ça que les chiottes sont toujours dégueulasses. Il arrive jamais à viser le centre.", Author = "Laurent Gerra" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Farhad_Khosrokhavar", Text = "Le domaine délimité par le terrorisme couvre en grande partie celui de la radicalisation.", Author = "Farhad Khosrokhavar" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_Cuzacq", Text = "Si l’Adour est veuf de gros navires, le développement du tourisme amène de plus en plus sur ses rives l’essaim gracieux des yachts effilés. Maigre compensation aux difficultés économiques de l’heure.", Author = "René Cuzacq" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Samuel_Butler", Text = "Il a été souvent remarqué, je crois, qu'une poule n'était seulement que le moyen qu'avait un œuf de fabriquer un autre œuf.", Author = "Samuel Butler" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kenneth_Cook", Text = "Mais la vérité ne peut rester approximative très longtemps.", Author = "Kenneth Cook" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sefi_Atta", Text = "Dans mon pays, les femmes sont encensées lorsqu'elles renoncent à leur droit de protester Finalement il arrive qu'elles meurent en ne léguant rien d'autre à leurs filles que leur altruisme; un héritage surprenant, comme un filet de larmes dans une gorge desséchée.", Author = "Sefi Atta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mahawa_Bangoura", Text = "Le nouveau défi collectif est de faire émerger l’image d’un monde d’égalité, de dignité, d’équité et de solidarité internationale, traduite en une coopération économique et sociale et en un véritable ajustement social, plaçant l’être humain au centre.", Author = "Mahawa Bangoura" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Silex_and_the_City", Text = "Nous sommes en 40000 avant J-C... Toute la planète semble obéir aux lois de la sélection naturelle... Toute? Non,une vallée résiste encore et toujours à l'évolution.", Author = "Silex and the City" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Autour_de_la_Lune", Text = "C’est une prison, dit-il, mais une prison qui voyage, et avec le droit de mettre le nez à la fenêtre, je ferais bien un bail de cent ans!", Author = "Autour de la Lune" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Barreau", Text = "Le fou écarte les barreaux de l'espace et saute en lui-même. Il disparaît d'emblée en s'avalant.", Author = "Barreau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chantal_Yayi", Text = "Papa est à son dernier mandat. Que tout le peuple béninois soit rassuré. C’est un digne fils de la patrie. Que Dieu vous couvre", Author = "Chantal Yayi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Miguel_Primo_de_Rivera", Text = "Nous avons la raison avec nous, donc la force, bien que, jusqu'à maintenant, nous n'ayons fait usage de la force qu'avec modération.", Author = "Miguel Primo de Rivera" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stardust", Text = "Le Narrateur (en voix off): Un philosophe écrivit un jour Sommes-nous humains parce que nous contemplons les étoiles ou les contemplons-nous parce que nous sommes humains? Sans intérêt aucun. Les étoiles nous contemplent-elles en retour? Voilà une question digne d'être posée.", Author = "Stardust" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gilles_Archambault", Text = "Depuis quelques années, je n'attend rien d'autre de la vie que des mots.", Author = "Gilles Archambault" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Xavier_Niel", Text = "Ras-le-bol de la peine de prison de deux ans ferme!", Author = "Xavier Niel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anta_Sarr", Text = "Ce n’est pas du ressort de l’Etat de venir faire un audit dans une structure privée", Author = "Anta Sarr" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Taylor_Swift", Text = "Nous ne voulons pas de cette guerre, et nous avons honte que notre président soit originaire du Texas.", Author = "Taylor Swift" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Ping", Text = "L’Afrique n’est pas un problème, mais une opportunité.", Author = "Jean Ping" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karl_Polanyi", Text = "Notre thèse est l'idée qu'un marché s'ajustant lui même était purement utopique. Une telle institution ne pouvait exister de façon suivie sans anéantir la substance humaine et naturelle de la société, sans détruire l'homme et sans transformer son milieu en désert.", Author = "Karl Polanyi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Euphrasie_Calmont", Text = "Nos parents morts ne sont pas perdus. Ils sont là dans nos cœurs et vivent avec nous. Si nous les avons profondément aimés, nous les retrouverons toujours au même endroit dans nos pensées.", Author = "Euphrasie Calmont" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Katharine_Hepburn", Text = "Je n'ai aucune crainte de la mort. Ce doit être merveilleux, comme un long sommeil. Et puis, regardons les choses en face: ce qui compte c'est ce qu'on fait de sa vie.", Author = "Katharine Hepburn" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tib%C3%A9tain", Text = "Les langues servent toutes à communiquer. Aucune n'est meilleure ou pire qu'une autre. Mais certaines sont estimées plus que d'autres à cause de la vérité qu'elles véhiculent et préservent. Si vous cherchez à cultiver l'art du bonheur, par exemple, le tibétain vous sera très utile.", Author = "Tibétain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89lisabeth_Pognon", Text = "Nous avions tout fait pour faire aimer cette justice constitutionnelle, qu’elle soit acceptée par le peuple. Je crois que de ce point de vue-là, nous avions réussi puisque la 6ème mandature est applaudie encore bien que critiquée et acceptée dans notre environnement juridique", Author = "Élisabeth Pognon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Lovelock", Text = "Il y a plus ou moins 80 pourcents d'humains de trop par rapport à ce que le monde peut supporter. […] Un milliard est à peu prêt le bon nombre d'humains sur Terre. Nous sommes prêt de sept milliards.", Author = "James Lovelock" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arlette_Soudan-Nonault", Text = "1. Demain se prépare aujourd’hui", Author = "Arlette Soudan-Nonault" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Annette_Wieviorka", Text = "Les historiens sont ceux qui ont été les gardiens de l'histoire et de l'humanité.", Author = "Annette Wieviorka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Victoria_Kwakwa", Text = "Ce n’est pas la Banque Mondiale qui dicte les réformes. Nous pouvons faire des suggestions techniques, mais ce sont avant tout des réformes nationales que nous soutenons pleinement.", Author = "Victoria Kwakwa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Georges_Gastaud", Text = "Car derrière l'assurance feinte de ceux qui professent dogmatiquement le matérialisme dialectique, se cache trop souvent le refus de débattre, et si possible , d'éprouver les thèses qu'ils avancent.", Author = "Georges Gastaud" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Organisation_Consul", Text = "Il y eut des instants où même dans le cœur du petit fonctionnaire le plus modeste et le plus loyal, les rumeurs fantastiques qui couraient sur l'O.C. faisaient monter l'enthousiasme aussi vite que montait la mousse au col de leur chope de bière.", Author = "Organisation Consul" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amsatou_Sow_Sidib%C3%A9", Text = "Je me veux apôtre de la non-violence… Quand la violence se passe chez moi, surtout dans l’espace universitaire… je suis peinée. L’université doit être un espace de réflexion et non un espace où ce sont les biceps et les armes qui règnent.", Author = "Amsatou Sow Sidibé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Henry_Newman", Text = "La connaissance est une chose, la vertu en est une autre.", Author = "John Henry Newman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Shrek_2", Text = "L'Âne: Allez, grouille-toi, Shrek, ça va bouchonner sur le périph'!", Author = "Shrek 2" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Hollande", Text = "Faire simple, ce n'est pas faire médiocre, ou même banal, c'est au contraire avoir le respect des français... être exemplaire", Author = "François Hollande" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_XXIII", Text = "Le seigneur soit béni! Tout ce que la franc-maçonnerie, c'est-à-dire le Diable, a entrepris depuis soixante ans contre l'Église et le pape en Italie a été réduit à néant.", Author = "Jean XXIII" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Affaire", Text = "Les affaires se font toujours contre les autres.", Author = "Affaire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_de_Gonzague-Frick", Text = "(En réponse à la question Pourquoi écrivez-vous?) En vérité j'écris pour donner de mes nouvelles poétiques à mes amis dont je vous adresserai la liste complète et commentée au premier loisir.", Author = "Louis de Gonzague-Frick" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Jos%C3%A9_Crespin", Text = "J'ai vu tant de gens qui essayaient d'ouvrir ma porte quand elle était entre-ouverte. Ils essayaient de prendre une photo, alors je me suis dit que ce n'était pas possible que l'on vienne à Gorée uniquement pour la Maison des esclaves.", Author = "Marie-José Crespin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Val%C3%A9riane_Vukosavljevi%C4%87", Text = "D'un point de vue sportif, terminer juste à côté du podium était extrêmement frustrant, mais c'était une super expérience pour moi. Tous les athlètes rêvent de jouer aux Jeux olympiques; J'ai pu le faire; Et j'espère jouer à plus!", Author = "Valériane Vukosavljević" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Luciano_Berio", Text = "Je suis contre l’œuvre objet. Une œuvre est un signal au sein d’un parcours, comme passer par Rome au milieu d’un voyage de Paris jusqu’en Chine.", Author = "Luciano Berio" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nord_%28roman%29", Text = "Le Teuton est le dernier client de le planète qui nous passait n'importe quoi… son armée, sans doute la seule, la dernière, qu'était prête à mourir pour nous… on y a montré nos natures!", Author = "Nord (roman)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/PNL", Text = "J'téma la lune, les pêchés m'entêtent\nLes anges me parlent mais moi j'entends pas\nJ'suis dans ma bulle, j'suis baisé j'm'embête\n\nEt j'comprends pas pourquoi j'comprends pas", Author = "PNL" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Audiard", Text = "Déjà la Seine charrie des poissons morts.Il n'y a plus qu'à s'asseoir sur un banc et attendre. La fin du monde est pour dimanche.Le plus tôt sera le mieux.", Author = "Michel Audiard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuel-Joseph_Siey%C3%A8s", Text = "1°. Qu’est-ce que le Tiers-État? - Tout.\n2°. Qu’a-t-il été jusqu’à présent dans l’ordre politique? - Rien.\n3°. Que demande-t-il? - A être quelque chose.", Author = "Emmanuel-Joseph Sieyès" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marion_Delorme", Text = "Elle avait trente-neuf ans quand elle est morte, cependant elle était aussi belle que jamais. Sans les fréquentes grossesses qu'elle a eues, elle eût été belle jusqu'à soixante ans.", Author = "Marion Delorme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sha%C3%AFne_Cassim", Text = "Je pense que la destruction de l'être passe beaucoup par le langage. Le langage érige des murs. C'est une cathédrale de mots qui empêchent, qui interdisent, où il n'y a pas de libre arbitre.", Author = "Shaïne Cassim" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne_Sylvestre", Text = "Mon mari est parti un beau matin d'automne\nParti je ne sais où\nJe me rappelle bien la vendange était bonne\nEt le vin était doux", Author = "Anne Sylvestre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Netumbo_Nandi-Ndaitwah", Text = "Je n’ai pas été élue parce que je suis une femme, mais parce que j’en suis capable.", Author = "Netumbo Nandi-Ndaitwah" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dj%C3%A8n%C3%A8_Keita", Text = "Ce que les gens oublient, c’est que le parti n’est pas une affaire de nomination. Il y a deux voies: soit le consensus, soit le vote. Celui qui obtient le plus de voix l’emporte, et le candidat malheureux doit rejoindre le vainqueur pour célébrer la victoire.", Author = "Djènè Keita" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cali", Text = "On ne peut pas traiter de voleur un jeune qui télécharge, alors que nous sommes d'abord les voleurs.", Author = "Cali" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dominique_von_Burg", Text = "Le rôle des journalistes a toujours été de faire le tri entre ce qu’on publie ou non.", Author = "Dominique von Burg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marine_Le_Pen", Text = "De toute façon la France sera dirigée par une femme: ce sera, ou moi, ou Madame Merkel.", Author = "Marine Le Pen" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amanda_Sthers", Text = "Regardez-moi cette fougue! Même ses erreurs ont de la gueule!", Author = "Amanda Sthers" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aholou_K%C3%A8k%C3%A8", Text = "L’avenir d’un être humain est entre les mains du créateur.", Author = "Aholou Kèkè" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lina_Khan", Text = "Nous croyons à des marchés ouverts, concurrentiels, mais pour que ces marchés donnent de bons résultats, nous devons nous assurer que les entreprises jouent le jeu d'une concurrence non faussée. C'est le boulot que le Congrès a donné à la FTC et c'est ce que nous faisons.", Author = "Lina Khan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Souvenirs_de_Marnie", Text = "Marnie: Je ne puis rester ici plus longtemps. Il me faut te dire adieu. Alors, Anna, je t'en prie... Dis-moi que tu me pardonnes!", Author = "Souvenirs de Marnie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Monica_Bellucci", Text = "Peinture, musique, littérature, cinéma: seul le temps atteste de la valeur d'une œuvre. L'instant est toujours soumis aux aléas, aux émotions, à un certain état d'esprit. Pour pouvoir jauger, il faut attendre. Passer après le public, les critiques, les modes… Juger à nu. Poser un œil vierge.", Author = "Monica Bellucci" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/F%C3%A9nelon", Text = "Chacun doit infiniment plus au genre humain, qui est la grande patrie, qu'à la patrie particulière dans laquelle il est né.", Author = "Fénelon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alice_Maguedjio", Text = "Si vous voulez connaitre la santé d'un pays, allez vous renseigner sur la santé du marché.", Author = "Alice Maguedjio" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Justine_Behanzin", Text = "J’ai préféré vivre dans la masse, le temps de faire émerger au plan national la voix des femmes", Author = "Justine Behanzin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Sibelius", Text = "Si nous comprenions le monde, nous nous rendrions compte qu'il y a une logique d'harmonie derrière ses multiples dissonances apparentes.", Author = "Jean Sibelius" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Linah_Mohohlo", Text = "Les femmes en particulier souffrent d'un écart en matière d'accès aux produits bancaires et d'épargne par rapport à leurs homologues occidentales.", Author = "Linah Mohohlo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Th%C3%A9r%C3%A8se_Kuoh-Moukouri", Text = "Le mariage était une ouverture aussi bien sur le plan matériel que sur le plan moral: un idéal plus rêvé que vécu.", Author = "Thérèse Kuoh-Moukouri" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cloud_Atlas", Text = "Sonmi-451: La vérité est une. S'il y a des versions, il n'y a plus de vérité.", Author = "Cloud Atlas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Henriette_Wamu_Atamina", Text = "Nul ne doute que l'adresse prochaine du chef de l'Etat à la nation, laquelle scellera cette union, sonnera le glas d'une nouvelle ère de gouvernance de la RDC.", Author = "Henriette Wamu Atamina" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Hobbit", Text = "Dans un trou vivait un hobbit. Ce n'était pas un trou déplaisant, sale et humide, rempli de bouts de vers et d'une atmosphère suintante, non plus qu'un trou sec, nu, sablonneux, sans rien pour s'asseoir ni sur quoi manger: c'était un trou de hobbit, ce qui implique le confort.", Author = "Le Hobbit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Thanatos", Text = "Thanatos a pour unique but de ramener toute matière vivante à l'état inorganique; Éros, de son côté, travaille patiemment à rassembler des groupes de plus en plus étendus et à embrasser la vie dans sa totalité.", Author = "Thanatos" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nadia_Buari", Text = "La pauvreté est une maladie. Vos amis offrent des maisons, des voitures à leurs copines, vous êtes là pour leur offrir des cartes, des fleurs.", Author = "Nadia Buari" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Duke_Nukem", Text = "Il est temps de botter des culs et de mâcher du chewing-gum, et je n'ai plus de chewing gum!", Author = "Duke Nukem" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jules_C%C3%A9sar", Text = "Toute la Gaule est divisée en trois parties.", Author = "Jules César" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/South_Park%3A_L%27Annale_du_destin", Text = "Capitaine Diabète: N'ayez crainte, et c'est MOI, CAPITAINE DIABÈTE!", Author = "South Park: L'Annale du destin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dominique_Reyni%C3%A9", Text = "On ne peut pas dire qu’un parti est antisémite et ensuite s’y rallier", Author = "Dominique Reynié" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Assamala_Amoi", Text = "Plus de parfum ni de fleurs de jasmin\nTu m’arroses de pétrole et me transformes en torche\nPour laver ton honneur et celui de la famille\n\nEt tu me dis que tu m’aimes", Author = "Assamala Amoi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bob_l%27%C3%A9ponge", Text = "M. Krabs: Eh bien, mon garçon, on dirait que vous n'avez même pas le pied marin.\nBob l'éponge: M. Krabs, s'il vous plaît. Je prouverai que je suis un cuisinier de friture. Demandez à Carlo, il se portera garant pour moi.", Author = "Bob l'éponge" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Soufiane_El_Khalidy", Text = "On doit avoir peur de faire de mauvais films au départ si on s'aventure dans de nouveaux sentiers, mais il faut oser pour qu'on s'améliore et qu'on progresse.", Author = "Soufiane El Khalidy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alfred_Sauvy", Text = "Les chiffres sont des innocents qui, sous la sollicitation, sous la torture, avouent très vite ce qu'on leur demande, quitte à se rétracter plus tard.", Author = "Alfred Sauvy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dyana_Gaye", Text = "Le Sénégal m’apparaît comme un champ de possibles très vaste.", Author = "Dyana Gaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Gantheret", Text = "Cet essai est une réflexion  sur deux pratiques qui sont miennes: d’analyste et d’écrivain. Je les dis deux puisque ces mots les distinguent, mais ce dont j’aimerais témoigner, ce que je souhaite affirmer ici est leur profonde unicité.", Author = "François Gantheret" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bisexualit%C3%A9", Text = "Les bisexuels les trouble-fête de l’intégrisme identitaire. Ils nous rappellent surtout que tout le monde n’est pas forcément d’un bord ou de l’autre.", Author = "Bisexualité" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Courants_de_l%27espace", Text = "Le joug que l'on connait est préférable au joug que l'on ignore.", Author = "Les Courants de l'espace" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Haine", Text = "C’est l’histoire d’un homme qui tombe d’un immeuble de cinquante étages. Le mec, au fur et à mesure de sa chute, il se répète sans cesse pour se rassurer: jusqu’ici tout va bien, jusqu’ici tout va bien, jusqu’ici tout va bien. \nMais l'important n’est pas la chute, c’est l’atterrissage.", Author = "La Haine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sidoine_Oussou", Text = "Comme tous les béninois, j'étais remonté par la lourde défaite des Écureuils. Maintenant, je suis sincèrement surpris par la décision du ministre. Les responsabilités relatives à la défaite des Écureuils sont partagées.", Author = "Sidoine Oussou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Patrick_Tambay", Text = "Je pense souvent à la mort, en espérant qu'elle ne pense pas à moi.", Author = "Patrick Tambay" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Am%C3%A9nagement_du_territoire_en_France", Text = "Aménager le territoire, c'est prendre conscience de l'espace français comme richesse et comme devoir.", Author = "Aménagement du territoire en France" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_L%C3%A9vesque", Text = "J'ai jamais... J'ai jamais pensé que je pouvais être aussi fier d'être québécois... que ce soir.", Author = "René Lévesque" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hassana_Alidou", Text = "On ne peut pas construire un pays sans l’identité culturelle des peuples.", Author = "Hassana Alidou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Peter_Altenberg", Text = "La femme nous pompe les trois quarts de notre énergie. Mais si nous ne l'avions pas, nous n'aurions pas d'énergie.", Author = "Peter Altenberg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/George_Eliot", Text = "Examinez bien vos paroles, et vous trouverez que, lors même que vous n'avez aucune motif d'être faux, il est très difficile de dire l'exacte vérité.", Author = "George Eliot" }
    };
}